import { Book } from "@/lib/types";

export const _1kings: Book = {
  id: "1kings",
  name: "1. Könige",
  shortName: "1.Kön",
  testament: "old",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Und der König David war alt, hochbetagt*. Man bedeckte ihn mit Kleidern, aber es wurde ihm nicht warm.", heading: "Adonijas Versuch, König zu werden", footnotes: ["℘ V. 15; Jos 13,1; 1Chr 23,1"] },
      { number: 2, text: "Da sagten seine Diener zu ihm: Man suche meinem Herrn, dem König, ein Mädchen, eine Jungfrau, dass sie vor dem König <dienend> stehe und seine Pflegerin sei! Wenn sie <dann> in deinem Schoß liegt, wird meinem Herrn, dem König, warm werden*.", footnotes: ["℘ Pred 4,11"] },
      { number: 3, text: "Und man suchte ein schönes Mädchen im ganzen Gebiet Israels; und man fand Abischag*, die Schunemiterin*, und brachte sie zum König.", footnotes: ["℘ Kap. 2,17", "℘ Jos 19,18"] },
      { number: 4, text: "Das Mädchen aber war überaus schön*, und sie wurde Pflegerin des Königs und bediente ihn; aber der König erkannte sie nicht.", footnotes: ["℘ 1Mo 12,11"] },
      { number: 5, text: "Adonija aber, der Sohn der Haggit*, erhob sich und sagte: Ich bin es, der König wird! Und er schaffte sich Wagen und Reiter* an und fünfzig Mann, die vor ihm herliefen*.", footnotes: ["℘ Kap. 2,13; 2Sam 3,4", "o. Pferde; o. Gespanne", "℘ 2Sam 15,1"] },
      { number: 6, text: "Sein Vater aber hatte ihn, solange er lebte, nie gekränkt, dass er gesagt hätte: Warum handelst du so*? Und auch war er sehr schön von Gestalt*; und seine Mutter* hatte ihn nach Absalom geboren*.", footnotes: ["℘ 1Sam 3,13; Spr 29,15", "℘ 2Sam 14,25", "w. sie", "℘ 1Chr 3,2"] },
      { number: 7, text: "Und er hatte seine Verabredungen mit Joab*, dem Sohn der Zeruja, <getroffen> und mit dem Priester Abjatar*; und sie standen mit ihrer Hilfe hinter Adonija*.", footnotes: ["℘ Kap. 2,22", "℘ Kap. 2,26; 1Chr 27,34", "w. halfen Adonija hinterher"] },
      { number: 8, text: "Aber der Priester Zadok und Benaja, der Sohn Jojadas*, und der Prophet Nathan* und Schimi* und Reï und die Helden, die David hatte*, waren nicht mit Adonija.", footnotes: ["℘ 2Sam 20,23.25", "℘ 2Sam 7,2; 12,25", "℘ Kap. 4,18", "℘ 2Sam 23,8"] },
      { number: 9, text: "Und Adonija schlachtete Schafe und Rinder und Mastvieh bei dem Stein Sohelet*, der neben En-Rogel* ist; und er lud alle seine Brüder, die Söhne des Königs, ein und alle Männer von Juda, die im Dienst des Königs standen*.", footnotes: ["d. h. Schlangenstein, o. gleitender Stein", "d. h. Walkerquelle\n℘ 2Sam 17,17", "w. und von allen Männern Judas die Diener des Königs"] },
      { number: 10, text: "Den Propheten Nathan aber und Benaja und die Helden und seinen Bruder Salomo* lud er nicht ein.", footnotes: ["℘ Kap. 2,13; 2Sam 12,24"] },
      { number: 11, text: "Da sagte Nathan zu Batseba, der Mutter Salomos*: Hast du nicht gehört, dass Adonija, der Sohn der Haggit, König geworden ist*? Und unser Herr David hat nichts <davon> erkannt.", heading: "Salomos Salbung zum König", footnotes: ["℘ V. 10", "℘ 2Sam 15,10"] },
      { number: 12, text: "Und nun komm, ich will dir einen Rat geben*, und <so> rette dein Leben und das Leben deines Sohnes Salomo!", footnotes: ["℘ Spr 27,9"] },
      { number: 13, text: "Auf, geh zum König David hinein und sage zu ihm: »Hast nicht du selbst, mein Herr König, deiner Magd geschworen und gesagt: Dein Sohn Salomo soll nach mir König sein, und er soll es sein, der auf meinem Thron sitzen wird?* Warum aber ist Adonija König geworden?«", footnotes: ["℘ Kap. 2,12; 1Chr 29,23.28; 28,5"] },
      { number: 14, text: "Siehe, während du dort noch mit dem König redest, werde ich nach dir hineinkommen und deine Worte bekräftigen*.", footnotes: ["w. voll machen, o. vollenden"] },
      { number: 15, text: "Da ging Batseba zum König hinein in das Gemach; der König aber war sehr alt*, und Abischag, die Schunemiterin, bediente den König.", footnotes: ["℘ V. 1"] },
      { number: 16, text: "Und Batseba verneigte sich und fiel vor dem König nieder*. Da sagte der König: Was hast du?", footnotes: ["℘ 1Sam 20,41; 1Petr 2,17"] },
      { number: 17, text: "Und sie sagte zu ihm: Mein Herr, du selbst hast ja deiner Magd bei dem HERRN, deinem Gott, geschworen: »Dein Sohn Salomo soll nach mir König sein, und er soll es sein, der auf meinem Thron sitzen wird.«" },
      { number: 18, text: "Und nun siehe, Adonija ist König geworden, und du*, mein Herr und König, hast nichts <davon> erkannt.", footnotes: ["So lesen sehr viele hebr. Handschr. und die alten Üs.; Mas. T.: und jetzt"] },
      { number: 19, text: "Und er hat Stiere und Mastvieh und Schafe in Menge geschlachtet und hat alle Söhne des Königs und den Priester Abjatar und den Heerobersten Joab eingeladen; aber deinen Knecht Salomo hat er nicht eingeladen." },
      { number: 20, text: "Auf dich aber, mein Herr und König, auf dich sind die Augen von ganz Israel <gerichtet>, dass du ihnen bekannt gibst, wer auf dem Thron meines Herrn, des Königs, nach ihm sitzen soll." },
      { number: 21, text: "Und es wird geschehen, wenn mein Herr, der König, bei seinen Vätern liegt*, dass ich und mein Sohn Salomo als Sünder dastehen*.", footnotes: ["℘ Kap. 2,10", "℘ Ri 9,5; 2Chr 22,10"] },
      { number: 22, text: "Und siehe, während sie noch mit dem König redete, kam der Prophet Nathan herein." },
      { number: 23, text: "Und man meldete dem König: Der Prophet Nathan ist da! Und er kam herein vor den König und warf sich vor dem König auf sein Angesicht zur Erde nieder*.", footnotes: ["℘ 1Sam 20,41; 1Petr 2,17"] },
      { number: 24, text: "Und Nathan sagte: Mein Herr und König, du hast <wohl> selbst angeordnet: Adonija soll nach mir König sein, und er soll es sein, der auf meinem Thron sitzen wird!" },
      { number: 25, text: "Denn er ist heute hinabgegangen, hat Stiere und Mastvieh und Schafe in Menge geschlachtet und hat alle Söhne des Königs und die Heerobersten und den Priester Abjatar eingeladen; und siehe, sie essen und trinken vor ihm und sagen: Es lebe der König Adonija!*", footnotes: ["℘ V. 34.39; Kap. 2,15; 1Sam 10,24; 2Sam 16,16; 2Kö 9,13; 11,12"] },
      { number: 26, text: "Mich selbst aber, deinen Knecht, und den Priester Zadok* und Benaja, den Sohn Jojadas, und deinen Knecht Salomo hat er nicht eingeladen.", footnotes: ["℘ Kap. 2,35; 2Sam 8,17"] },
      { number: 27, text: "Wenn diese Sache von meinem Herrn, dem König, aus <so> geschehen ist, dann hast du deine Knechte* also nicht wissen lassen, wer auf dem Thron meines Herrn, des Königs, nach ihm sitzen soll*?", footnotes: ["so mit der Schreibform des Mas. T.; die Leseform mit vielen anderen hebr. Handschr. und den alten Üs. haben die Einzahl: deinen Knecht", "℘ 1Chr 23,1"] },
      { number: 28, text: "Da antwortete der König David und sagte: Ruft mir Batseba! Und sie kam herein vor den König und trat vor den König." },
      { number: 29, text: "Und der König schwor und sprach: So wahr der HERR lebt, der meine Seele aus jeder Not gerettet hat*,", footnotes: ["℘ 1Mo 48,16"] },
      { number: 30, text: "ja, wie ich dir <einst> bei dem HERRN, dem Gott Israels geschworen habe, indem ich sprach: Gewiss, dein Sohn Salomo soll nach mir König sein, und er soll der sein, der an meiner Stelle auf meinem Thron sitzen wird*, ja, so werde ich am heutigen Tag tun*.", footnotes: ["℘ Kap. 2,12; 1Chr 29,23.28; 28,5", "℘ Pred 8,4"] },
      { number: 31, text: "Da verneigte sich Batseba mit dem Gesicht zur Erde und warf sich vor dem König nieder* und sprach: Es lebe mein Herr, der König David, ewig!*", footnotes: ["℘ 1Sam 20,41; 1Petr 2,17", "℘ Neh 2,3; Dan 2,4"] },
      { number: 32, text: "Darauf sagte der König David: Ruft mir den Priester Zadok und den Propheten Nathan und Benaja, den Sohn Jojadas! Und sie kamen herein vor den König." },
      { number: 33, text: "Und der König sprach zu ihnen: Nehmt die Diener eures Herrn mit euch und lasst meinen Sohn Salomo auf meiner eigenen Mauleselin reiten* und führt ihn zum Gihon* hinab!", footnotes: ["℘ Est 6,8", "℘ 2Chr 33,14"] },
      { number: 34, text: "Und der Priester Zadok und der Prophet Nathan sollen ihn dort zum König über Israel salben*. Und ihr sollt ins Horn stoßen und sagen: Es lebe der König Salomo!*", footnotes: ["℘ Kap. 19,16; 1Sam 10,1; 2Kö 11,12", "℘ V. 25; 2Chr 23,11"] },
      { number: 35, text: "Dann zieht <wieder> herauf hinter ihm her, und er soll hereinkommen und sich auf meinen Thron setzen. Er ist es, der an meiner Stelle König sein soll*. Und ihn habe ich dazu bestimmt, Fürst über Israel und über Juda zu sein*.", footnotes: ["℘ 1Chr 23,1", "℘ 1Chr 23,1"] },
      { number: 36, text: "Da antwortete Benaja, der Sohn Jojadas, dem König und sagte: Amen*! So spreche* der HERR, der Gott meines Herrn, des Königs!", footnotes: ["℘ Jer 28,6; Offb 5,14", "drei hebr. Handschr. und die syr. Üs.: So mache es"] },
      { number: 37, text: "So wie der HERR mit meinem Herrn, dem König, gewesen ist, so möge er mit Salomo sein* und seinen Thron <noch> größer machen als den Thron meines Herrn, des Königs David*!", footnotes: ["℘ Jos 1,17", "℘ 1Chr 29,25"] },
      { number: 38, text: "So zogen der Priester Zadok und der Prophet Nathan und Benaja, der Sohn Jojadas, und die Kreter und Pleter* hinab und ließen Salomo auf der Mauleselin des Königs David reiten* und führten ihn zum Gihon.", footnotes: ["Die Kreter und Pleter bildeten Davids Leibgarde.\n℘ Kap. 2,35; 2Sam 8,18", "℘ Sach 9,9; Offb 19,11-16"] },
      { number: 39, text: "Und der Priester Zadok holte das Ölhorn aus dem Zelt* und salbte Salomo*; und sie stießen ins Horn, und alles Volk sprach: Es lebe der König Salomo!*", footnotes: ["℘ 2Mo 30,25", "℘ Kap. 2,15; 1Chr 29,22", "℘ V. 25; 2Chr 23,11"] },
      { number: 40, text: "Und alles Volk zog hinauf hinter ihm her; und das Volk blies auf Flöten, und sie freuten sich mit großer Freude, so dass die Erde <fast> von ihrem Geschrei barst*.", footnotes: ["℘ 1Sam 4,5"] },
      { number: 41, text: "Und Adonija hörte es und alle die Geladenen, die bei ihm waren, als sie eben aufgehört hatten zu essen. Und Joab hörte den Schall des Horns und sagte: Weshalb hört man die Stadt so lärmen?", heading: "Adonijas Unterwerfung" },
      { number: 42, text: "Während er noch redete, siehe, da kam Jonatan*, der Sohn des Priesters Abjatar. Und Adonija sagte: Komm, denn du bist ein zuverlässiger Mann und wirst gute Botschaft bringen*!", footnotes: ["℘ 2Sam 15,27.36", "℘ 2Sam 18,27"] },
      { number: 43, text: "Da antwortete Jonatan und sagte zu Adonija: Nein! Unser Herr, der König David, hat Salomo zum König gemacht." },
      { number: 44, text: "Und der König hat den Priester Zadok und den Propheten Nathan und Benaja, den Sohn Jojadas, und die Kreter und Pleter mit ihm gesandt, und sie haben ihn auf der Mauleselin des Königs reiten lassen." },
      { number: 45, text: "Und der Priester Zadok und der Prophet Nathan haben ihn am Gihon zum König gesalbt. Dann sind sie von dort mit Freuden<geschrei> heraufgezogen, und die Stadt ist in Bewegung. Das ist das Geschrei, das ihr gehört habt." },
      { number: 46, text: "Und außerdem: Salomo hat sich auf den Königsthron* gesetzt*.", footnotes: ["w. auf den Thron der Königswürde o. des Königtums", "℘ 1Chr 29,23"] },
      { number: 47, text: "Und außerdem sind die Diener des Königs hineingegangen, um unserem Herrn, dem König David, Segenswünsche zu überbringen*, indem sie sagten: Dein Gott mache den Namen Salomos <noch> herrlicher als deinen Namen und mache seinen Thron <noch> größer als deinen Thron! Und der König hat sich auf dem Lager anbetend geneigt*.", footnotes: ["w. um unseren Herrn, den König, zu segnen", "℘ 1Mo 47,31"] },
      { number: 48, text: "Und außerdem hat der König so gesprochen: Gepriesen sei der HERR, der Gott Israels*, der heute einen <von meinen Söhnen> eingesetzt hat, der auf meinem Thron sitzt* — und meine Augen dürfen <es noch> sehen*!", footnotes: ["℘ Ps 41,14; Lk 1,68", "℘ Kap. 2,4.24; 3,6; 8,20; Ps 132,11", "℘ Lk 2,30"] },
      { number: 49, text: "Da erschraken all die Geladenen, die bei Adonija waren, und standen auf und gingen weg, jeder seines Weges*.", footnotes: ["℘ Spr 24,21.22"] },
      { number: 50, text: "Und Adonija fürchtete sich vor Salomo; und er machte sich auf, ging hin und ergriff die Hörner des Altars*.", footnotes: ["℘ Kap. 2,28; 2Mo 27,2"] },
      { number: 51, text: "Das wurde Salomo berichtet, indem man sagte: Siehe, Adonija fürchtet den König Salomo, und siehe, er hält die Hörner des Altars fest und sagt: Der König Salomo schwöre mir heute, dass er seinen Knecht nicht mit dem Schwert töten wird!" },
      { number: 52, text: "Und Salomo sagte: Wenn er sich als ein zuverlässiger Mann erweist, soll von seinem Haar keines auf die Erde fallen*. Wenn aber Böses an ihm gefunden wird, dann soll er sterben*.", footnotes: ["℘ 2Sam 14,11", "℘ Kap. 2,24; Spr 13,6; Röm 13,4"] },
      { number: 53, text: "Und der König Salomo sandte hin, und man holte ihn vom Altar herunter; und er kam und warf sich vor dem König Salomo nieder*. Und Salomo sagte zu ihm: Geh in dein Haus!", footnotes: ["℘ 2Sam 14,33"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "Als nun die Tage Davids herannahten, dass er sterben sollte*, befahl er seinem Sohn Salomo und sagte:", heading: "Davids letzter Wille und Tod", footnotes: ["℘ 1Mo 47,29"] },
      { number: 2, text: "Ich gehe <nun> den Weg aller Welt*. So sei stark und erweise dich als Mann*!", footnotes: ["℘ Jos 23,14; 2Sam 12,23", "℘ 5Mo 31,7; 1Chr 28,10; 2Tim 2,1"] },
      { number: 3, text: "Bewahre, was der HERR, dein Gott, zu bewahren geboten hat*, dass du auf seinen Wegen gehst, indem du seine Ordnungen, seine Gebote und seine Rechtsbestimmungen und seine Zeugnisse* bewahrst, wie es im Gesetz des Mose geschrieben ist*, damit du Erfolg hast* in allem, was du tust, und überall, wohin du dich wendest;*", footnotes: ["w. Bewahre das zu Bewahrende des HERRN, deines Gottes", "o. Mahnungen", "℘ 5Mo 17,18-20; Jos 23,6; Pred 12,13", "o. verständig handelst", "℘ 5Mo 29,8; 1Chr 22,12.13; Ps 119,2"] },
      { number: 4, text: "damit der HERR sein Wort aufrechterhält, das er über mich geredet hat, als er sprach: Wenn deine Söhne auf ihren Weg achthaben, so dass sie in Treue* vor mir leben* mit ihrem ganzen Herzen und mit ihrer ganzen Seele, dann soll es dir* nicht an einem Mann fehlen auf dem Thron Israels*.", footnotes: ["o. in Wahrheit; o. in Zuverlässigkeit", "w. gehen", "so mit einer griech. Üs. und Vulg.; Mas. T.: und mit ihrer ganzen Seele, indem er sprach: Es soll dir", "w. dann soll dir nie ein Mann ausgerottet werden vom Thron Israels hinweg\n℘ Kap. 1,48; 6,12; 8,25; 9,5; 11,36; 2Sam 7,13; Ps 132,12"] },
      { number: 5, text: "Auch hast du ja selbst erkannt, was mir Joab, der Sohn der Zeruja, angetan hat, was er den beiden Heerobersten Israels, Abner, dem Sohn Ners, und Amasa, dem Sohn Jeters, angetan hat, dass er sie ermordete und so mit Kriegsblut den Frieden belastete*. So hat er Kriegsblut an seinen Gürtel gebracht, der um seine Hüften war, und an seine Schuhe, die an seinen Füßen waren*.", footnotes: ["w. und Kriegsblut auf den Frieden legte", "LXX: und Kriegsblut im Frieden gerächt hat, so dass er unschuldiges Blut an meinen Gürtel gebracht hat, der um meine Hüften war, und an meine Schuhe, die an meinen Füßen waren\n℘ V. 32; 5Mo 27,24; 2Sam 3,27"] },
      { number: 6, text: "So handle <nun> nach deiner Weisheit* und lass sein graues Haar nicht in Frieden in den Scheol hinabfahren*!", footnotes: ["℘ Kap. 3,12; 2Tim 2,7", "℘ 1Mo 9,6; 2Sam 3,39"] },
      { number: 7, text: "Aber an den Söhnen des Gileaditers Barsillai sollst du Gnade erweisen*, und sie sollen unter denen sein, die an deinem Tisch essen*; denn ebenso sind sie mir entgegengekommen, als ich vor deinem Bruder Absalom floh*.", footnotes: ["℘ 2Sam 19,38.39", "℘ 2Sam 9,7-10; 2Kö 25,29.30", "℘ 2Sam 17,27-29; Hebr 6,10"] },
      { number: 8, text: "Und siehe, bei dir ist Schimi*, der Sohn Geras, der Benjaminiter aus Bahurim; das ist der, der mich mit einem schlimmen Fluch verflucht hat am Tag, als ich nach Mahanajim ging*. Aber er kam mir dann entgegen, an den Jordan herab, und ich schwor ihm bei dem HERRN und sprach: Wenn ich dich mit dem Schwert töte*!*", footnotes: ["℘ V. 36", "℘ 2Sam 16,5-8", "Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde.", "℘ 2Sam 19,17-24"] },
      { number: 9, text: "Jetzt aber lass ihn nicht ungestraft*, denn du bist ein weiser Mann und wirst erkennen, was du ihm tun sollst*. Lass sein graues Haar mit Blut <befleckt> in den Scheol hinabfahren*!", footnotes: ["℘ 2Mo 22,27", "℘ 1Mo 9,6; 2Sam 3,39", "℘ 1Mo 9,6; 2Sam 3,39"] },
      { number: 10, text: "Und David legte sich zu seinen Vätern* und wurde in der Stadt Davids* begraben*.", footnotes: ["℘ Kap. 1,21; 2Sam 7,12; Apg 13,36", "℘ Kap. 3,1; 8,1; 11,21.43; 14,31; 15,8.24; 22,51; 2Sam 5,7; 2Kö 8,24; 2Chr 24,16", "℘ Apg 2,29"] },
      { number: 11, text: "Und die Tage, die David über Israel König war, <betrugen> vierzig Jahre*. In Hebron war er sieben Jahre König, und in Jerusalem war er 33 Jahre König.", footnotes: ["℘ 2Sam 5,4.5"] },
      { number: 12, text: "Und Salomo setzte sich auf den Thron seines Vaters David*, und seine Königsherrschaft war fest gegründet*.", footnotes: ["℘ Kap. 1,13.30.35", "℘ V. 46; 2Chr 1,1"] },
      { number: 13, text: "Und Adonija, der Sohn der Haggit*, kam zu Batseba, der Mutter Salomos*. Und sie sagte: <Bedeutet> dein Kommen Friede? Und er sagte: <Ja,> Friede*.", heading: "Salomos Urteil über Adonija, Abjatar, Joab und Schimi", footnotes: ["℘ Kap. 1,5", "℘ Kap. 1,11", "℘ 1Sam 16,4.5"] },
      { number: 14, text: "Und er sagte: Ich habe ein Wort an dich. Und sie sagte: Rede!" },
      { number: 15, text: "Da sagte er: Du hast selbst erkannt, dass mir das Königtum zukam und dass ganz Israel sein Gesicht auf mich gerichtet hatte, dass ich König werden sollte*. Aber das Königtum hat sich <von mir> gewandt und ist meinem Bruder <zuteil> geworden, weil es von dem HERRN für ihn <bestimmt> war*.", footnotes: ["℘ Kap. 1,25", "℘ Kap. 1,39; 1Chr 22,9.10"] },
      { number: 16, text: "Jetzt aber möchte ich eine einzige Bitte von dir erbitten. Weise mich nicht ab! Da sagte sie zu ihm: Rede!" },
      { number: 17, text: "Und er sagte: Sprich doch zum König Salomo, denn er wird dich nicht abweisen, dass er mir Abischag, die Schunemiterin*, zur Frau gebe!", footnotes: ["℘ Kap. 1,3"] },
      { number: 18, text: "Darauf sagte Batseba: Gut, ich selbst will deinetwegen mit dem König reden." },
      { number: 19, text: "So ging Batseba zum König Salomo hinein, um mit ihm wegen Adonija zu reden. Und der König erhob sich, <kam> ihr entgegen und beugte sich vor ihr nieder. Dann setzte er sich auf seinen Thron und ließ einen Thron für die Königinmutter aufstellen; und sie setzte sich zu seiner Rechten." },
      { number: 20, text: "Dann sagte sie: <Nur> eine einzige kleine Bitte möchte ich von dir erbitten. Weise mich nicht ab! Und der König sagte zu ihr: Bitte, meine Mutter, denn ich werde dich nicht abweisen." },
      { number: 21, text: "Und sie sagte: Möge Abischag, die Schunemiterin, deinem Bruder Adonija zur Frau gegeben werden!" },
      { number: 22, text: "Da antwortete der König Salomo und sagte zu seiner Mutter: Warum bittest du um Abischag, die Schunemiterin, für Adonija? Bitte doch gleich um das Königtum für ihn*, denn er ist ja mein älterer Bruder, und zu ihm <hält> der Priester Abjatar und Joab, der Sohn der Zeruja*!*", footnotes: ["℘ 2Sam 16,21", "so mit den alten Üs.; Mas. T.: Bitte doch gleich um das Königtum für ihn . . . und für den Priester Abjatar und für Joab, den Sohn der Zeruja", "℘ Kap. 1,7"] },
      { number: 23, text: "Und der König Salomo schwor bei dem HERRN und sprach: So soll mir Gott tun und so hinzufügen*!* Um <den Preis> seines Lebens hat Adonija dieses Wort geredet!", footnotes: ["Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde.", "℘ Kap. 19,2; 20,10; 2Sam 3,9.35"] },
      { number: 24, text: "Und nun — so wahr der HERR lebt, der mich bestätigt hat und mich auf den Thron meines Vaters David gesetzt* und der mir ein Haus gemacht hat, wie er geredet hat —, fürwahr, heute <noch> soll Adonija getötet werden*!", footnotes: ["℘ Kap. 1,46.48", "℘ Kap. 1,52; Spr 20,2"] },
      { number: 25, text: "Und der König Salomo sandte hin zu Benaja, dem Sohn Jojadas, der stieß ihn nieder. So starb er*.", footnotes: ["℘ 2Sam 12,10"] },
      { number: 26, text: "Zum Priester Abjatar* aber sagte der König: Geh nach Anatot* auf dein Feld, denn du bist ein Mann des Todes! Aber am heutigen Tag will ich dich nicht töten, weil du die Lade des Herrn, HERRN, vor meinem Vater David getragen hast* und weil du gelitten hast in allem, worin mein Vater gelitten hat*.", footnotes: ["℘ Kap. 1,7", "℘ Jos 21,18", "℘ 2Sam 15,24", "℘ 1Sam 22,20-23"] },
      { number: 27, text: "So verstieß Salomo den Abjatar, dass er nicht mehr Priester des HERRN war, um das Wort des HERRN zu erfüllen, das er in Silo über das Haus Elis geredet hatte*.", footnotes: ["℘ 1Sam 2,30-35"] },
      { number: 28, text: "Und die Kunde <davon> kam zu Joab, denn Joab hatte sich Adonija zugeneigt* — Absalom aber hatte er sich nicht zugeneigt* —; da floh Joab ins Zelt des HERRN und ergriff die Hörner des Altars*.", footnotes: ["w. hatte sich hinter Adonija her ausgestreckt, o. war abgewichen hinter Adonija her\n℘ Kap. 1,7", "w. aber hinter Absalom her hatte er sich nicht ausgestreckt o. war er nicht abgewichen\n℘ 2Sam 18,2", "℘ Kap. 1,50.51"] },
      { number: 29, text: "Und es wurde dem König Salomo berichtet: Joab ist in das Zelt des HERRN geflohen, und siehe, er <befindet sich> neben dem Altar*. Da sandte Salomo Benaja, den Sohn Jojadas, mit dem Auftrag: Geh hin, stoß ihn nieder*!", footnotes: ["℘ Spr 28,17", "℘ 2Mo 21,14"] },
      { number: 30, text: "So ging Benaja in das Zelt des HERRN und sagte zu Joab: So spricht der König: Geh hinaus! Er aber sagte: Nein, sondern hier will ich sterben. Da brachte Benaja dem König Antwort und sagte: So hat Joab geredet, und so hat er mir geantwortet." },
      { number: 31, text: "Der König sagte zu ihm: Tu, wie er geredet hat, und stoß ihn nieder und begrabe ihn! Entferne so das unschuldige Blut*, das Joab vergossen hat, von mir und von dem Haus meines Vaters*!", footnotes: ["o. das ohne Grund <geflossene> Blut", "℘ 5Mo 19,13"] },
      { number: 32, text: "Der HERR wird sein Blut auf seinen Kopf zurückbringen*, weil er zwei Männer niedergestoßen hat, die gerechter und besser waren als er*, und sie mit dem Schwert ermordet hat*, ohne dass mein Vater David es wusste*: Abner, den Sohn des Ner, den Heerobersten Israels, und Amasa, den Sohn des Jeter, den Heerobersten Judas*.", footnotes: ["℘ V. 44; Kap. 8,32; 1Mo 42,22; 4Mo 32,23; Ri 9,24.56.57; 2Sam 3,29; Hes 17,19", "℘ 2Chr 21,13", "℘ Mt 26,52", "o. es erkannt hatte", "℘ V. 5"] },
      { number: 33, text: "So wird ihr Blut zurückkehren auf den Kopf Joabs* und auf den Kopf seiner Nachkommen für ewig*; aber David und seinen Nachkommen und seinem Haus und seinem Thron wird ewig Friede <zuteil> werden von dem HERRN*.", footnotes: ["℘ V. 44; Kap. 8,32; 1Mo 42,22; 4Mo 32,23; Ri 9,24.56.57; 2Sam 3,29; Hes 17,19", "℘ 2Sam 3,29.39; Spr 25,5", "℘ 1Chr 17,27; Ps 21,4-7; Jes 9,6"] },
      { number: 34, text: "So ging Benaja, der Sohn Jojadas, hinauf, stieß ihn nieder und tötete ihn; und er wurde in seinem Haus in der Wüste begraben." },
      { number: 35, text: "Und der König setzte Benaja, den Sohn Jojadas, an seiner Stelle über das Heer;* und den Priester Zadok* setzte der König an die Stelle Abjatars*.", footnotes: ["℘ Kap. 1,33.38; 1Chr 27,5", "℘ Kap. 1,26; Hes 40,46", "℘ Kap. 4,4; 1Sam 2,35"] },
      { number: 36, text: "Und der König sandte hin und ließ Schimi* rufen, und er sagte zu ihm: Baue dir ein Haus in Jerusalem und wohne dort und gehe nicht von dort hinaus, hierhin oder dorthin!", footnotes: ["℘ V. 8"] },
      { number: 37, text: "Und es soll geschehen, an dem Tag, an dem du hinausgehst und den Bach Kidron* überschreitest — das sollst du genau wissen* —, musst du sterben. Dein Blut wird auf deinem Kopf sein.", footnotes: ["℘ 2Sam 15,23", "o. erkennen"] },
      { number: 38, text: "Und Schimi sagte zu dem König: Das Wort ist gut*. Ganz wie mein Herr, der König, geredet hat, so wird dein Knecht tun. So wohnte Schimi eine lange Zeit* in Jerusalem.", footnotes: ["℘ Kap. 18,24; 2Kö 20,19", "w. viele Tage"] },
      { number: 39, text: "Es geschah aber am Ende von drei Jahren, da entliefen zwei Sklaven Schimis zu Achisch, dem Sohn Maachas, dem König von Gat*. Und man berichtete dem Schimi: Siehe, deine Sklaven sind in Gat!", footnotes: ["℘ 1Sam 27,2"] },
      { number: 40, text: "Da machte sich Schimi auf und sattelte seinen Esel und ging nach Gat zu Achisch, um seine Sklaven zu suchen. Und Schimi ging hin und brachte seine Sklaven aus Gat zurück." },
      { number: 41, text: "Es wurde aber dem Salomo berichtet, dass Schimi von Jerusalem nach Gat gegangen und <wieder> zurückgekommen sei." },
      { number: 42, text: "Da sandte der König hin und ließ Schimi rufen, und er sagte zu ihm: Habe ich dich nicht bei dem HERRN schwören lassen und dich gewarnt, indem ich sagte: An dem Tag, an dem du <aus Jerusalem> hinausgehst und hierhin oder dorthin gehst — das sollst du genau wissen* —, musst du sterben? Und du sagtest zu mir: Das Wort ist gut, ich habe <es> gehört.", footnotes: ["o. erkennen"] },
      { number: 43, text: "Warum hast du den beim HERRN <geleisteten> Schwur nicht gehalten und das Gebot, das ich dir geboten hatte?" },
      { number: 44, text: "Und der König sagte zu Schimi: Du selbst kennst all das Böse, dessen <auch> dein Herz sich bewusst ist*, das du meinem Vater David angetan hast. So wird der HERR deine Bosheit auf deinen Kopf zurückkommen lassen*.", footnotes: ["℘ Röm 2,15", "℘ V. 32.33"] },
      { number: 45, text: "Aber der König Salomo wird gesegnet sein, und der Thron Davids wird bis in Ewigkeit fest gegründet sein vor dem HERRN*.", footnotes: ["℘ 1Chr 17,27; Ps 21,4-7; Jes 9,6"] },
      { number: 46, text: "Und der König gab Benaja, dem Sohn Jojadas, Befehl; der ging hinaus und stieß ihn nieder; so starb er. Und das Königtum war in der Hand Salomos fest gegründet*.", footnotes: ["℘ V. 12; Spr 25,5"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "Und Salomo wurde Schwiegersohn des Pharao, des Königs von Ägypten*, und nahm die Tochter des Pharao* und brachte sie in die Stadt Davids*, bis er den Bau seines Hauses* und des Hauses des HERRN* und der Mauer rings um Jerusalem vollendet hatte*.", heading: "Salomos Heirat — Sein Gebet um Weisheit — Gottes Verheißung", footnotes: ["℘ 5Mo 23,8", "℘ Kap. 7,8; 9,16; 11,1; 2Kor 6,14", "℘ Kap. 2,10", "℘ Kap. 7,1", "℘ Kap. 9,1", "℘ Kap. 9,15"] },
      { number: 2, text: "Jedoch opferte das Volk auf den Höhen*; denn bis zu jenen Tagen war dem Namen des HERRN <noch> kein Haus gebaut worden.", footnotes: ["℘ Kap. 14,23; 15,14; 22,44; 3Mo 17,5; 1Sam 9,12; 2Kö 12,4; 2Chr 15,17"] },
      { number: 3, text: "Und Salomo liebte den HERRN, so dass er in den Ordnungen seines Vaters David lebte*. Jedoch brachte er auf den Höhen* Schlachtopfer und Rauchopfer dar.", footnotes: ["w. ging\n℘ V. 14; Kap. 8,25.61; 9,4; 11,4.6; 14,8; 15,3.5.11; 2Kö 14,3; 2Chr 17,3.4; Joh 14,21.23", "℘ Kap. 14,23; 15,14; 22,44; 3Mo 17,5; 1Sam 9,12; 2Kö 12,4; 2Chr 15,17"] },
      { number: 4, text: "*Und der König ging nach Gibeon*, um dort Schlachtopfer darzubringen*, denn das war »die große Höhe«; tausend Brandopfer opferte Salomo auf jenem Altar.", footnotes: ["℘ V. 4-15: 2Chr 1,2-13", "℘ 1Chr 16,39", "w. um dort zu schlachten"] },
      { number: 5, text: "In Gibeon erschien der HERR dem Salomo in einem Traum bei Nacht*. Und Gott sprach: Bitte, was ich dir geben soll*!", footnotes: ["℘ Kap. 9,2; 11,9; 4Mo 12,6", "℘ Mt 7,7; Joh 16,24"] },
      { number: 6, text: "Und Salomo sagte: Du selbst hast ja an deinem Knecht David, meinem Vater, große Gnade erwiesen, weil er vor dir gelebt hat* in Treue*, in Gerechtigkeit und in Aufrichtigkeit des Herzens gegen dich*; und du hast ihm diese große Gnade bewahrt und ihm einen Sohn gegeben, der auf seinem Thron sitzt, wie <es> am heutigen Tag ist*.", footnotes: ["w. gegangen ist", "o. in Wahrheit", "℘ 1Mo 24,40; 2Sam 22,21.25; 2Kö 20,3", "℘ Kap. 1,48"] },
      { number: 7, text: "Und nun, HERR, mein Gott, du selbst hast deinen Knecht zum König gemacht anstelle meines Vaters David. Ich aber bin ein kleiner Junge, ich weiß nicht aus- noch einzugehen*.", footnotes: ["o. ich habe nicht erkannt aus- und einzugehen\n℘ 1Chr 22,5; Spr 18,12"] },
      { number: 8, text: "Und dein Knecht ist inmitten deines Volkes, das du erwählt hast*, eines großen Volkes, das wegen <seiner> Menge nicht gezählt noch berechnet werden kann.*", footnotes: ["℘ 5Mo 7,6", "℘ Kap. 4,20; 3Mo 26,9"] },
      { number: 9, text: "So gib denn deinem Knecht ein hörendes* Herz*, dein Volk zu richten, zu unterscheiden zwischen Gut und Böse*. Denn wer vermag dieses dein gewaltiges* Volk zu richten*?", footnotes: ["o. gehorsames", "℘ Kol 1,9", "℘ 2Sam 14,17; Hebr 5,14", "o. schweres", "℘ 1Chr 22,12; Ps 72,1.2"] },
      { number: 10, text: "Und das Wort war gut in den Augen des HERRN, dass Salomo um diese Sache gebeten hatte." },
      { number: 11, text: "Und Gott sprach zu ihm: Weil du um diese Sache gebeten hast und hast dir nicht viele Tage erbeten und hast dir nicht Reichtum erbeten und hast nicht um das Leben* deiner Feinde gebeten, sondern hast dir Verständnis erbeten, um auf das Recht zu hören*,", footnotes: ["o. um die Seele", "o. um die Rechtssache anzuhören"] },
      { number: 12, text: "siehe, so tue ich nach deinen Worten*. Siehe, ich gebe dir ein weises und verständiges Herz*, so dass es vor dir keinen wie dich gegeben hat und nach dir keiner wie du aufstehen wird*.", footnotes: ["℘ 1Jo 5,14", "℘ 5Mo 34,9; Dan 1,17", "℘ Kap. 2,6; 5,9-14; 10,3; 1Chr 29,25"] },
      { number: 13, text: "Und auch das, was du nicht erbeten hast, gebe ich dir*, sowohl Reichtum* als auch Ehre*, so dass es unter den Königen keinen wie dich geben wird alle deine Tage*.", footnotes: ["℘ Lk 12,31", "℘ Kap. 10,14-29", "o. Herrlichkeit\n℘ Spr 3,16; 4,9", "℘ Neh 13,26; Mt 6,29"] },
      { number: 14, text: "Und wenn du auf meinen Wegen gehst, indem du meine Ordnungen und meine Gebote bewahrst, so, wie dein Vater David <auf ihnen> gegangen ist*, dann werde ich <auch> deine Tage verlängern*.", footnotes: ["℘ V. 3; Kap. 11,34; 1Chr 28,7", "℘ 5Mo 5,33; Ps 21,5"] },
      { number: 15, text: "Da erwachte Salomo, und siehe, es war ein Traum gewesen*. Und er ging nach Jerusalem, und er trat vor die Lade des Bundes des Herrn und opferte Brandopfer und bereitete Heilsopfer* und bereitete für alle seine Knechte ein <Fest>mahl*.", footnotes: ["℘ 1Mo 41,7", "o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer\n℘ 1Chr 16,1", "℘ 1Mo 40,20; 1Chr 16,3"] },
      { number: 16, text: "Damals kamen zwei Huren zum König und traten vor ihn.", heading: "Salomos weises Urteil" },
      { number: 17, text: "Und die eine Frau sagte: Bitte, mein Herr! Ich und diese Frau wohnen in ein <und demselben> Haus; und ich habe bei ihr im Haus geboren." },
      { number: 18, text: "Und es geschah am dritten Tag, nachdem ich geboren hatte, gebar auch diese Frau, und wir waren beieinander, kein Fremder war bei uns im Haus, nur wir beide waren im Haus." },
      { number: 19, text: "Da starb der Sohn dieser Frau eines Nachts, weil sie sich auf ihn gelegt hatte." },
      { number: 20, text: "Sie aber stand mitten in der Nacht* auf und nahm meinen Sohn von meiner Seite weg, während deine Sklavin schlief, und legte ihn an ihren Busen*; ihren toten Sohn aber legte sie an meinen Busen*.", footnotes: ["℘ Hi 24,13", "o. Schoß", "o. Schoß"] },
      { number: 21, text: "Als ich nun am Morgen aufstand, um meinen Sohn zu stillen, siehe, da war er tot. Am Morgen sah ich ihn mir genau an, und siehe, es war nicht mein Sohn, den ich geboren hatte." },
      { number: 22, text: "Da sagte die andere Frau: Nein, sondern mein Sohn ist der lebende, und dein Sohn ist der tote. Jene aber sagte: Nein, sondern dein Sohn ist der tote, und mein Sohn ist der lebende. So stritten* sie vor dem König.", footnotes: ["w. redeten"] },
      { number: 23, text: "Da sagte der König: Diese sagt: Das <hier> ist mein Sohn, der lebende, dein Sohn ist der tote. Und jene sagt: Nein, sondern dein Sohn ist der tote und mein Sohn der lebende." },
      { number: 24, text: "Und der König sprach: Holt mir ein Schwert! Und man brachte das Schwert vor den König." },
      { number: 25, text: "Und der König sprach: Zerschneidet das lebende Kind in zwei Teile und gebt der einen die <eine> Hälfte und der anderen die <andere> Hälfte!" },
      { number: 26, text: "Da sagte die Frau, deren Sohn der lebende war, zum König, denn ihr Innerstes* wurde erregt wegen ihres Sohnes*, sie sagte also: Bitte, mein Herr! Gebt ihr das lebende Kind, aber tötet es ja nicht! Jene aber sagte: Weder mir noch dir soll es gehören, zerschneidet <es>!", footnotes: ["o. ihr Mitleid; o. ihr Erbarmen", "℘ Jes 49,15"] },
      { number: 27, text: "Da antwortete der König und sprach: Gebt der Ersten* das lebende Kindchen* und tötet es ja nicht! Sie ist seine Mutter.", footnotes: ["w. ihr", "w. <Neu>geborene"] },
      { number: 28, text: "Und ganz Israel hörte das Urteil, das der König gefällt hatte, und sie fürchteten sich vor dem König*. Denn sie sahen, dass die Weisheit Gottes in ihm war*, <rechtes> Gericht zu halten*.", footnotes: ["℘ Jos 4,14", "℘ Esr 7,25", "℘ Kap. 10,9; Ps 72,2.4; Spr 8,15; 25,2; Jes 28,6"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "*So war der König Salomo König über ganz Israel*.", heading: "Salomos Beamte und Dienstleute", footnotes: ["℘ V. 1-6: 2Sam 8,15-18; 20,23-26", "℘ 2Chr 1,13; Neh 13,26"] },
      { number: 2, text: "Und das sind die obersten <Beamten>, die er hatte: Asarja, der Sohn des Zadok*, war der Priester;", footnotes: ["℘ 1Chr 5,34.35"] },
      { number: 3, text: "Elihoref und Ahia, die Söhne des Schischa, waren <Staats>schreiber; Joschafat, der Sohn des Ahilud, war Berater*;", footnotes: ["w. der Bekanntmachende"] },
      { number: 4, text: "Benaja, der Sohn des Jojada, war über das Heer <gesetzt>; und Zadok und Abjatar waren Priester*;", footnotes: ["℘ Kap. 2,27.35"] },
      { number: 5, text: "Asarja, der Sohn des Nathan*, war über die Vögte <gesetzt>; und Sabud, der Sohn Nathans, war Priester*, Freund des Königs*;", footnotes: ["℘ 2Sam 5,14", "Diese Angabe fehlt in LXX; »Priester« ist hier vielleicht ein Ehrentitel.", "»Freund des Königs« ist ein Amtstitel und dürfte so viel wie »Ratgeber« bedeuten.\n℘ Spr 22,11"] },
      { number: 6, text: "Ahischar war über das Haus* <gesetzt>, und Adoniram*, der Sohn des Abda, <war Aufseher> über die Zwangsarbeit.", footnotes: ["d. h. über den königlichen Palast", "℘ Kap. 5,28; 12,18"] },
      { number: 7, text: "Und Salomo hatte zwölf Vögte über ganz Israel, die versorgten den König und sein Haus. Einen Monat im Jahr oblag einem <von ihnen> die Versorgung*.", footnotes: ["℘ Kap. 5,7; 1Chr 27,1"] },
      { number: 8, text: "Und das sind ihre Namen: Der Sohn des Hur im Gebirge Ephraim*;", footnotes: ["℘ Jos 19,50"] },
      { number: 9, text: "der Sohn des Deker in Makaz und in Schaalbim* und Bet-Schemesch* und Elon <und> Bet-Hanan*;", footnotes: ["℘ Jos 19,42", "℘ 1Sam 6,12", "LXX: von Elon bis Bet-Hanan\n℘ Jos 19,43"] },
      { number: 10, text: "der Sohn des Hesed in Arubbot: Er hatte <dazu> Socho* und das ganze Land Hefer*.", footnotes: ["℘ Jos 15,35", "℘ Jos 12,17"] },
      { number: 11, text: "Der Sohn des Abinadab* hatte das ganze Hügelland von Dor*; Tafat, die Tochter Salomos, war seine Frau.", footnotes: ["℘ 1Sam 16,8", "℘ Jos 17,11"] },
      { number: 12, text: "Baana, der Sohn des Ahilud, <hatte> Taanach* und Megiddo* und ganz Bet-Schean, das neben Zaretan* <liegt>, unterhalb von Jesreel, von Bet-Schean* bis Abel-Mehola*, bis jenseits von Jokneam*.", footnotes: ["℘ Jos 17,11", "℘ Jos 17,11", "℘ Kap. 7,46; Jos 3,16", "℘ Kap. 7,46; Jos 3,16", "℘ Kap. 19,16; Ri 7,22; 1Sam 18,19", "℘ Jos 12,22"] },
      { number: 13, text: "Der Sohn des Geber war in Ramot-Gilead*: Er hatte die Zeltdörfer Jaïrs*, des Sohnes Manasses, die in Gilead sind, <und> er hatte den Landstrich Argob*, der in Baschan ist, sechzig große Städte* mit Mauern und bronzenen Riegeln.", footnotes: ["℘ Jos 21,38", "℘ 4Mo 32,41", "℘ 5Mo 3,4.13", "℘ 1Chr 2,23"] },
      { number: 14, text: "Ahinadab, der Sohn des Iddo, war in Mahanajim*;", footnotes: ["℘ Jos 21,38"] },
      { number: 15, text: "Ahimaaz in Naftali: Auch er hatte eine Tochter Salomos, die Basemat, zur Frau genommen;" },
      { number: 16, text: "Baana, der Sohn des Huschai, war in Asser und Bealot*;", footnotes: ["o. in Alot"] },
      { number: 17, text: "Joschafat, der Sohn des Paruach, in Issaschar;" },
      { number: 18, text: "Schimi*, der Sohn des Ela, in Benjamin;", footnotes: ["℘ Kap. 1,8"] },
      { number: 19, text: "Geber, der Sohn des Uri, im Land Gilead, dem Land Sihons, des Königs der Amoriter, und Ogs, des Königs von Baschan*; und <nur> einen Vogt gab es, der im Land Juda war*.", footnotes: ["℘ Jos 12,1-6", "so mit LXX; Mas. T.: und <nur> einen Vogt gab es, der in dem Land war"] },
      { number: 20, text: "Juda und Israel waren an Menge so zahlreich wie der Sand am Meer*. Sie aßen und tranken und waren fröhlich*.", footnotes: ["℘ Kap. 3,8; 5,9; 1Mo 22,17; Spr 14,28", "℘ Pred 2,24"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "Und Salomo war Herrscher über alle Königreiche, vom <Euphrat>strom* an <bis zu> dem Land der Philister und bis an die Grenze Ägyptens*; sie entrichteten Tribut* und dienten Salomo alle Tage seines Lebens*.", heading: "Salomos Macht und Weisheit", footnotes: ["℘ 1Mo 15,18; Ps 80,12", "℘ 2Mo 34,24; 2Chr 9,26; Hes 19,11", "℘ Kap. 10,25; 5Mo 20,11; 1Sam 10,27; 2Chr 17,11; Ps 72,8.10", "℘ 4Mo 24,7"] },
      { number: 2, text: "Und der tägliche Bedarf Salomos betrug* dreißig Kor Weizengrieß und sechzig Kor Mehl,", footnotes: ["w. Und es war das Brot Salomos für den Tag:"] },
      { number: 3, text: "zehn fette Rinder und zwanzig Weiderinder und hundert Schafe ohne die Hirsche und Gazellen und Damhirsche* und die gemästeten Vögel*.", footnotes: ["o. Rehböcke\n℘ 5Mo 14,5", "wahrscheinlich Kuckucke\n℘ 2Chr 9,4; Neh 5,17.18"] },
      { number: 4, text: "Denn er herrschte über das ganze <Gebiet> diesseits des <Euphrat>stromes, von Tifsach* bis Gaza*, über alle Könige diesseits des Stroms*; und er hatte Frieden von allen Seiten ringsumher.*", footnotes: ["Tapsakus, am westlichen Ufer des Euphrat", "℘ Jos 15,47", "℘ Esr 4,20", "℘ V. 18; 1Chr 22,9; Ps 72,7"] },
      { number: 5, text: "Und Juda und Israel wohnten in Sicherheit*, jeder unter seinem Weinstock und unter seinem Feigenbaum*, von Dan bis Beerscheba* alle Tage Salomos.", footnotes: ["℘ 3Mo 25,18; 5Mo 33,28", "℘ 2Kö 18,31; Mi 4,4; Sach 3,10", "℘ Ri 20,1"] },
      { number: 6, text: "Und Salomo hatte viertausend* Stallplätze für die Pferde seiner Streitwagen* und zwölftausend Pferde*.", footnotes: ["Diese Zahl liest LXX mit 2Chr 9,25; Mas. T.: 40 000", "Die zu einem Kampfwagen gehörenden Pferde (einschließlich eines Reservepferdes) waren an einem Stallplatz untergebracht.", "o. 12 000 <Mann> Wagenbesatzung\n℘ Kap. 9,19; 10,26; 5Mo 17,16; 2Chr 1,14"] },
      { number: 7, text: "Und die* Vögte versorgten den König Salomo und alle, die zum Tisch des Königs Salomo Zutritt hatten, jeder in seinem Monat; sie ließen es an nichts fehlen*.", footnotes: ["w. diese", "℘ Kap. 4,7"] },
      { number: 8, text: "Und die Gerste und das Stroh für die Pferde und für die Wagenpferde brachte man an den Ort, wo er* war, jeder nach seiner Vorschrift*.", footnotes: ["d. h. der König, o. der Vogt", "℘ 1Kor 4,2"] },
      { number: 9, text: "Und Gott gab Salomo Weisheit und sehr große Einsicht und Weite des Herzens* wie der Sand am Ufer des Meeres*.", footnotes: ["℘ V. 26; Kap. 3,12; Hi 32,8; Pred 1,16", "℘ Kap. 4,20"] },
      { number: 10, text: "Die Weisheit Salomos war größer als die Weisheit aller Söhne des Ostens* und als alle Weisheit Ägyptens*.", footnotes: ["℘ Ri 6,3", "℘ Jes 19,11.12; Apg 7,22"] },
      { number: 11, text: "Und er war weiser als alle Menschen*, als Etan, der Esrachiter*, und Heman* und Kalkol und Darda*, die Söhne Mahols. Und sein Name war <berühmt> unter allen Nationen ringsum.", footnotes: ["℘ 2Chr 9,22; Joh 7,46", "℘ 1Chr 6,29; Ps 89,1", "℘ Ps 88,1", "℘ 1Chr 2,6"] },
      { number: 12, text: "Und er verfasste* dreitausend Sprüche*, und die Zahl seiner Lieder* war 1 005.", footnotes: ["w. redete", "℘ Spr 1,1; Pred 12,9", "w. und sein Lied war 1 005\n℘ Ps 127,1; Hl 1,1"] },
      { number: 13, text: "Und er redete über die Bäume, <angefangen> von der Zeder, die auf dem Libanon <steht>, bis zum Ysop, der an der Mauer herauswächst; und er redete über das Vieh und über die Vögel und über das Gewürm und über die Fische." },
      { number: 14, text: "Und man kam aus allen Völkern, um die Weisheit Salomos zu hören, von allen Königen der Erde her*, die von seiner Weisheit gehört hatten.*", footnotes: ["LXX und die syr. Üs.: und er empfing Geschenke von allen Königen der Erde", "℘ Kap. 10,1.24"] },
      { number: 15, text: "*Und Hiram, der König von Tyrus*, sandte seine Knechte zu Salomo*, denn er hatte gehört, dass man ihn zum König gesalbt hatte anstelle seines Vaters; Hiram war nämlich allezeit ein Freund Davids gewesen*.", heading: "Salomos Vertrag mit Hiram — Vorbereitungen zum Tempelbau", footnotes: ["℘ 2Chr 2", "℘ Jos 19,29; Ps 45,13", "℘ 1Chr 14,1", "℘ 2Sam 5,11"] },
      { number: 16, text: "Und Salomo sandte zu Hiram und ließ <ihm> sagen:" },
      { number: 17, text: "Du weißt ja selbst, dass mein Vater David dem Namen des HERRN, seines Gottes, kein Haus bauen konnte wegen des Krieges*, mit dem seine Feinde* ihn umringten, bis der HERR sie unter die Sohlen seiner Füße legte*.", footnotes: ["℘ 2Sam 7,5; 1Chr 22,8", "w. mit dem sie", "℘ 2Sam 22,39"] },
      { number: 18, text: "Nun aber hat der HERR, mein Gott, mir Ruhe verschafft ringsum; kein Widersacher ist <mehr> da und kein schlimmes Geschick." },
      { number: 19, text: "Siehe, so gedenke ich, dem Namen des HERRN, meines Gottes, ein Haus zu bauen, so wie der HERR zu meinem Vater David geredet hat, als er sprach: Dein Sohn, den ich an deiner Stelle auf deinen Thron setzen werde, er soll meinem Namen das Haus bauen*.", footnotes: ["℘ Kap. 8,13.20; 2Sam 7,13; 1Chr 22,6.10"] },
      { number: 20, text: "So gib <nun> den Befehl, dass man mir Zedern vom Libanon schlägt. Meine Knechte sollen mit deinen Knechten zusammenarbeiten*. Und den Lohn für deine Knechte will ich dir geben, ganz wie du es sagen wirst. Denn du weißt ja, dass niemand unter uns ist, der <Bau>holz zu schlagen versteht wie die Sidonier.", footnotes: ["w. mit deinen Knechten sein"] },
      { number: 21, text: "Und es geschah, als Hiram die Worte Salomos hörte, da freute er sich sehr; und er sprach: Gepriesen sei heute der HERR, der David einen weisen Sohn <als Herrscher> über dieses große Volk gegeben hat*.", footnotes: ["℘ Kap. 10,9"] },
      { number: 22, text: "Und Hiram sandte zu Salomo und ließ <ihm> sagen: Ich habe <die Botschaft> gehört, die du mir gesandt hast; ich werde deinen Wunsch nach Zedernholz* und nach Wacholderholz ganz erfüllen.", footnotes: ["℘ Jes 60,13"] },
      { number: 23, text: "Meine Knechte sollen es vom Libanon ans Meer hinabbringen; ich werde dann auf dem Meer Flöße daraus machen <und sie> bis an den Ort <bringen lassen>, den du mir angeben wirst, und dort will ich sie auseinandernehmen lassen*. Und du kannst es <dort dann> abholen lassen. Du sollst aber meinen Wunsch erfüllen, Lebensmittel für mein Haus zu liefern.", footnotes: ["℘ Kap. 9,11; 1Chr 22,4"] },
      { number: 24, text: "So lieferte Hiram dem Salomo Zedernholz und Wacholderholz ganz nach seinem Wunsch." },
      { number: 25, text: "Salomo aber lieferte Hiram 20 000 Kor Weizen als Verpflegung für sein Haus und zwanzig Kor* reines* Öl*. Das lieferte Salomo dem Hiram Jahr für Jahr.", footnotes: ["LXX: 20 000 Bat", "w. gestoßenes; d. h. Öl aus zerstoßenen Oliven", "℘ Esr 3,7; Hes 27,17"] },
      { number: 26, text: "Der HERR aber hatte Salomo Weisheit gegeben, wie er ihm zugesagt hatte*. Und es war Friede zwischen Hiram und Salomo, und sie schlossen einen Bund miteinander*.", footnotes: ["℘ V. 9", "℘ Am 1,9"] },
      { number: 27, text: "Und der König Salomo hob aus ganz Israel Zwangsarbeiter* aus, und die <Zahl der> Zwangsarbeiter betrug 30 000 Mann.", footnotes: ["℘ Kap. 4,6; 9,15; 12,4"] },
      { number: 28, text: "Er schickte sie auf den Libanon, abwechselnd 10 000 <Mann> im Monat. Einen Monat waren sie auf dem Libanon, zwei Monate in ihrem Haus*; und Adoniram war <Aufseher> über die Zwangsarbeit*.", footnotes: ["so mit LXX; Mas. T.: in seinem Haus", "℘ Kap. 4,6; 9,15; 12,4"] },
      { number: 29, text: "Und Salomo hatte 70 000 Lastträger und 80 000 Steinhauer im Gebirge*,", footnotes: ["℘ 2Chr 8,7.8"] },
      { number: 30, text: "abgesehen von den Obersten der Vögte Salomos, die über die Arbeit <eingesetzt> waren, 3 300, die das Volk beaufsichtigten*, das mit der Arbeit beschäftigt war.", footnotes: ["w. die über das Volk herrschten"] },
      { number: 31, text: "Und der König ordnete an, dass man große Steine breche, wertvolle* Steine, um die Grundmauern des Hauses mit Quadern zu legen.", footnotes: ["o. schwere"] },
      { number: 32, text: "Und die Bauleute Salomos und die Bauleute Hirams und die Gebaliter* hieben sie zurecht* und richteten das Holz und die Steine zum Bau des Hauses zu*.", footnotes: ["℘ Jos 13,5", "℘ Kap. 6,7", "℘ Kap. 7,9-11"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "*Und es geschah im 480. Jahr nach dem Auszug der Söhne Israel aus dem Land Ägypten*, im vierten Jahr der Regierung Salomos über Israel, im Monat Siw, das ist der zweite Monat, da baute er das Haus für den HERRN*.", heading: "Salomos Tempelbau", footnotes: ["℘ V. 1-38: 2Chr 3; V. 1-20: Hes 41,1-26", "℘ 2Mo 12,51", "℘ V. 37.38; Esr 5,11; Apg 7,47"] },
      { number: 2, text: "Und das Haus, das der König Salomo für den HERRN baute: sechzig Ellen <betrug> seine Länge und zwanzig <Ellen> seine Breite und dreißig Ellen seine Höhe*.", footnotes: ["℘ Esr 6,3"] },
      { number: 3, text: "Und die Vorhalle vor dem Tempelraum* des Hauses: Zwanzig Ellen war ihre Länge vor der Breite des Hauses her; zehn Ellen war ihre Breite, in der Längsrichtung des Hauses* <gemessen>*.", footnotes: ["d. h. dem Heiligen", "w. vor dem Haus", "℘ Kap. 7,12.21; Hes 40,48; Joh 10,23; Apg 3,11"] },
      { number: 4, text: "Und er machte für das Haus Fenster mit Rahmen und Gitterwerk*.", footnotes: ["℘ Hes 40,16"] },
      { number: 5, text: "Und er baute an der Wand des Hauses einen Anbau* ringsumher, an den Wänden des Hauses rings um den Tempelraum und den Hinterraum*; und er machte Seiten<stockwerke>* ringsumher.", footnotes: ["o. Stockwerke", "d. i. das Allerheiligste\n℘ Ps 28,2", "o. Seitenkammern\n℘ 1Chr 28,11; Jer 35,2; Hes 40,17"] },
      { number: 6, text: "Der untere Anbau: fünf Ellen <betrug> seine Breite; und der mittlere: sechs Ellen seine Breite; und der dritte: sieben Ellen seine Breite. Denn er hatte dem Haus ringsum nach außen zu Absätze gegeben, um nicht in die Wände des Hauses einzugreifen*.", footnotes: ["nämlich durch die Balkenköpfe der einzelnen Stockwerke"] },
      { number: 7, text: "Und als das Haus gebaut wurde, wurde es aus Steinen erbaut, die vom Steinbruch her unbehauen waren. Hammer und Meißel <oder> irgendein <anderes> eisernes Werkzeug waren im Haus nicht zu hören, als es erbaut wurde*.", footnotes: ["℘ Kap. 5,31.32"] },
      { number: 8, text: "Der Eingang zum mittleren* Seiten<stockwerk> war an der rechten* Seite des Hauses; und mit <Hilfe von> Wendeltreppen* stieg man zum mittleren und vom mittleren zum dritten hinauf.", footnotes: ["LXX und die aram. Üs.: zum unteren", "Im Hebr. ist »rechts« oft gleichbedeutend mit »südlich«.", "o. durch Falltüren"] },
      { number: 9, text: "Und er baute das Haus und vollendete es*, und er deckte das Haus mit Balken und Bohlenreihen aus Zedern.", footnotes: ["℘ Kap. 7,51; 9,25; 2Mo 40,33"] },
      { number: 10, text: "Und er baute den Anbau* am ganzen Haus — fünf Ellen <betrug jeweils> seine Höhe — und fasste so das Haus mit Zedernbalken ein*.", footnotes: ["o. die Stockwerke", "o. und verband ihn mit dem Haus durch Zedernbalken"] },
      { number: 11, text: "Und das Wort des HERRN geschah zu Salomo, indem er sprach:" },
      { number: 12, text: "<Was> dieses Haus <betrifft>, das du baust<, so sollst du wissen>: Wenn du in meinen Ordnungen lebst* und meine Rechtsbestimmungen tust und alle meine Gebote bewahrst, dass du in ihnen lebst*, dann werde ich dir mein Wort aufrechterhalten*, das ich zu deinem Vater David geredet habe*.", footnotes: ["w. gehst", "w. gehst", "o. mein Wort an dir wahr machen", "℘ Kap. 2,4"] },
      { number: 13, text: "Und ich werde mitten unter den Söhnen Israel wohnen* und werde mein Volk Israel nicht verlassen*.", footnotes: ["℘ 2Mo 25,8; 2Kor 6,16; Offb 21,3", "℘ 5Mo 31,6"] },
      { number: 14, text: "Und Salomo baute das Haus und vollendete es*.", footnotes: ["℘ Kap. 7,51; 9,25; 2Mo 40,33"] },
      { number: 15, text: "Und er verkleidete* die Wände des Hauses innen mit Zedernbrettern; vom Fußboden des Hauses bis an die Balken* der Decke belegte er sie innen mit Holz; und er belegte den Fußboden des Hauses mit Wacholderbrettern.", footnotes: ["w. baute", "so mit LXX; Mas. T.: bis an die Wände"] },
      { number: 16, text: "Und er baute <einen Abschnitt> von zwanzig Ellen von der Rückseite des Hauses her mit Zedernbrettern vom Fußboden bis an die <Decken>balken*. So baute er <diesen Abschnitt> für das Haus* innen zum Hinterraum aus*, zum Allerheiligsten*.", footnotes: ["so mit LXX; Mas. T.: bis an die Wände", "w. für es", "Andere lesen mit Textänderung: So teilte er es innen ab für den Hinterraum", "℘ 2Mo 26,33; Hes 45,3"] },
      { number: 17, text: "Vierzig Ellen <lang> war das Haus, das ist der Tempelraum vor dem Hinterraum*.", footnotes: ["so mit Vulg.; Mas. T.: das ist der Tempelraum nach vorn zu"] },
      { number: 18, text: "Und Zedernholz war innen am Haus, Schnitzwerk von Koloquinten<blättern>* und Blumengewinden*. Alles war Zedernholz, kein Stein war zu sehen.", footnotes: ["Koloquinten sind eine Kürbisart, deren Blätter an Weinlaub erinnern und die deshalb als Motiv für Schnitzereien bevorzugt wurden.", "o. Blütenkelchen"] },
      { number: 19, text: "Den Hinterraum richtete er im Innersten des Hauses her, um die Lade des Bundes des HERRN dort hinzustellen." },
      { number: 20, text: "Und der Hinterraum war* zwanzig Ellen lang und zwanzig Ellen breit und zwanzig Ellen hoch. Und er überzog ihn mit gediegenem Gold*. *Auch den Zedernholz-Altar überzog er <damit>*.", footnotes: ["so mit Vulg.; Mas. T.: Und vor dem Hinterraum war es", "℘ 2Mo 26,29; Offb 21,18", "LXX: Und er machte einen Opferaltar vor dem Hinterraum und überzog ihn mit Gold", "℘ 2Mo 30,3"] },
      { number: 21, text: "Und Salomo überzog das Haus innen mit gediegenem Gold und zog goldene Ketten vor dem Hinterraum entlang und überzog ihn mit Gold*.", footnotes: ["LXX: Und er machte einen Opferaltar vor dem Hinterraum und überzog ihn mit Gold"] },
      { number: 22, text: "Das ganze Haus überzog er mit Gold*, das ganze Haus vollständig. Auch den ganzen Altar, der zum Hinterraum gehörte*, überzog er mit Gold*.", footnotes: ["℘ 2Mo 26,29; Offb 21,18", "℘ Hebr 9,4", "℘ Hebr 9,4"] },
      { number: 23, text: "Und er machte im Hinterraum zwei Cherubim* aus Ölbaumholz, zehn Ellen ihre Höhe.", footnotes: ["℘ 2Mo 25,18-20"] },
      { number: 24, text: "Fünf Ellen <maß> der eine Flügel des Cherubs und fünf Ellen der andere Flügel des Cherubs: zehn Ellen von dem einen Ende seiner Flügel bis zu dem andern Ende seiner Flügel." },
      { number: 25, text: "Zehn Ellen <maß> auch der andere Cherub: beide Cherubim hatten ein <und dasselbe> Maß und ein <und dieselbe> Gestalt." },
      { number: 26, text: "Die Höhe des einen Cherubs <betrug> zehn Ellen und ebenso <die> des andern Cherubs." },
      { number: 27, text: "Und er stellte die Cherubim in die Mitte des inneren Hauses; und die Cherubim breiteten die Flügel aus*, so dass der Flügel des einen <Cherubs> die <eine> Wand berührte und der Flügel des andern Cherubs die andere Wand berührte; ihre Flügel zur Mitte des Hauses hin aber berührten sich gegenseitig, Flügel an Flügel.", footnotes: ["w. und man breitete die Flügel der Cherubim aus\n℘ Kap. 8,6.7"] },
      { number: 28, text: "Und er überzog die Cherubim mit Gold." },
      { number: 29, text: "Und alle Wände des Hauses ringsum schnitzte er aus mit Schnitzwerkreliefs von Cherubim* und Palmen<ornamenten>* und Blumengewinden* im Inneren und im Äußeren.", footnotes: ["℘ 2Mo 26,1", "℘ Hes 40,16", "o. Blütenkelchen"] },
      { number: 30, text: "Und den Fußboden des Hauses überzog er mit Gold, im Inneren und im Äußeren." },
      { number: 31, text: "Und für den Eingang zum Hinterraum machte er Türflügel* aus Ölbaumholz; die Einfassung* <bildete> einen fünffach gestaffelten Türrahmen*.", footnotes: ["℘ Hes 41,23", "o. der Torpfeiler", "T.; Mas. T.: Die Einfassung <und> die Türrahmen waren fünfeckig; o. Die Torpfeiler, <das sind> die Türpfosten, waren fünfeckig"] },
      { number: 32, text: "Und in die beiden Türflügel aus Ölbaumholz, auf ihnen schnitzte er Schnitzwerk von Cherubim und Palmen<ornamenten>* und Blumengewinden* und überzog sie mit Gold*, und auf die Cherubim und auf die Palmen<ornamente> ließ er das Gold aufhämmern.", footnotes: ["℘ Hes 40,16", "o. Blütenkelchen", "℘ 2Chr 4,22"] },
      { number: 33, text: "Und ebenso machte er für den Eingang zum Tempelraum Türrahmen aus Ölbaumholz und <machte> vierfach gestaffelte Türrahmen*", footnotes: ["T. in Anlehnung an V. 31; Mas. T.: vonseiten des Viertels"] },
      { number: 34, text: "und zwei Türen aus Wacholderholz; die beiden Türflügel der einen Tür waren <bis an die Wand> drehbar, und die beiden Türflügel* der anderen Tür waren <bis an die Wand> drehbar.", footnotes: ["so mit LXX, der syr. und aram. Üs.; Mas. T.: die beiden Behänge"] },
      { number: 35, text: "Und er schnitzte Cherubim und Palmen<ornamente> und Blumengewinde* ein und überzog sie mit Gold*, das dem Eingeritzten genau angepasst war*.", footnotes: ["o. Blütenkelche", "℘ 2Chr 4,22", "w. überzog sie mit Gold, platt geschlagen über dem Eingeritzten"] },
      { number: 36, text: "Und er baute den inneren Vorhof* aus drei Lagen Quadern und aus einer Lage Zedernbalken*.", footnotes: ["℘ 2Chr 4,9; Hes 40,28", "℘ Kap. 7,12; Esr 6,4"] },
      { number: 37, text: "Im vierten Jahr wurde die Grundmauer des Hauses des HERRN gelegt, im Monat Siw*;", footnotes: ["℘ V. 1"] },
      { number: 38, text: "und im elften Jahr, im Monat Bul, das ist der achte Monat, war das Haus vollendet*, nach all seinen Teilen und nach all seinen Erfordernissen*; so hatte er sieben Jahre daran gebaut*.", footnotes: ["℘ 2Chr 8,16", "o. seiner Gebühr; w. seinem Recht\n℘ 2Mo 39,43; 1Chr 28,19.20", "℘ 1Chr 5,36; 2Chr 8,1; Joh 2,20"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "Und an seinem <eigenen> Haus baute Salomo dreizehn Jahre, und er vollendete sein ganzes Haus*.", heading: "Salomos Paläste", footnotes: ["℘ Kap. 3,1; 9,10; 2Chr 1,18; 8,1; Pred 2,4"] },
      { number: 2, text: "Und er baute das Libanonwaldhaus*; hundert Ellen <betrug> seine Länge, fünfzig Ellen seine Breite und dreißig Ellen seine Höhe; auf vier Reihen* von Zedernsäulen <stand es>, und Zedernbalken <lagen> auf den Säulen.", footnotes: ["℘ Kap. 10,17.21", "LXX: auf drei Reihen"] },
      { number: 3, text: "Und es war mit Zedernholz gedeckt oben über den Tragbalken*, die auf den Säulen waren, fünfundvierzig*, <jeweils> fünfzehn in einer Reihe.", footnotes: ["o. Kammern; w. Rippen", "LXX: und die Zahl der Säulen: 45"] },
      { number: 4, text: "Und <Fenster>rahmen in drei Reihen, Fenster gegenüber Fenster*, dreimal.", footnotes: ["o. Fenster neben Fenster"] },
      { number: 5, text: "Und alle Türen und Fenster* waren viereckig <und mit einem> Rahmen <versehen>* und Fenster gegenüber Fenster*, dreimal.", footnotes: ["so mit LXX; Mas. T.: Und alle Türen, und zwar die Pfosten", "o. waren viereckig<, was ihren> Rahmen <betraf>", "o. Fenster neben Fenster"] },
      { number: 6, text: "Er machte auch die Säulenvorhalle — fünfzig Ellen <betrug> ihre Länge und dreißig Ellen ihre Breite — und <noch> eine Halle vor dieser mit Säulen und einem Aufgang* vor ihnen.", footnotes: ["o. Gatter. — Die Bedeutung ist unsicher."] },
      { number: 7, text: "Und er machte die Thronvorhalle, wo er Gericht hielt, die Gerichtsvorhalle*. Sie war mit Zedernholz gedeckt, von Boden zu Boden*.", footnotes: ["℘ Ps 122,5", "Offenbar ist eine doppelte Dachbedeckung der Thronhalle gemeint."] },
      { number: 8, text: "Und sein Haus, in dem er wohnte, <im> anderen Hof einwärts von der Vorhalle war von derselben Bauart. Und Salomo baute <auch> für die Tochter des Pharao, die er <zur Frau> genommen hatte*, ein Haus wie diese Vorhalle*.", footnotes: ["℘ Kap. 3,1", "℘ Kap. 9,24; 2Chr 8,11"] },
      { number: 9, text: "Das alles war aus wertvollen* Steinen, im Maß von Quadern von innen und von außen mit der Säge gesägt, und zwar vom Fundament bis zum Gesims und von außen bis zum großen Hof.", footnotes: ["o. schweren"] },
      { number: 10, text: "Und das Fundament <bestand> aus wertvollen* Steinen, aus großen Steinen, Steinen von zehn Ellen und Steinen von acht Ellen.", footnotes: ["o. schweren"] },
      { number: 11, text: "Und darüber <lagen> wertvolle* Steine, Steine nach Maßen von Quadern, und Zedernholz*.", footnotes: ["o. schwere", "℘ Kap. 5,32"] },
      { number: 12, text: "Und der große Hof ringsum <hatte> drei Lagen Quader und eine Lage Zedernbalken*, und zwar dem inneren Hof des Hauses des HERRN entsprechend und entsprechend der Vorhalle des Hauses*.", footnotes: ["℘ Kap. 6,36; 2Chr 4,9", "℘ Kap. 6,3"] },
      { number: 13, text: "Und der König Salomo sandte hin und ließ Hiram von Tyrus holen.", heading: "Tempelausstattung" },
      { number: 14, text: "Der war der Sohn einer Witwe aus dem Stamm Naftali, sein Vater aber war ein Tyrer, ein Bronzeschmied. Er war voller Weisheit und Einsicht und Kenntnis, um jegliche Arbeit in Bronze auszuführen*. Und er kam zu dem König Salomo und führte <ihm> alle seine Arbeit aus.", footnotes: ["℘ 2Mo 31,2-6; 2Chr 2,6.13"] },
      { number: 15, text: "*Und er formte die beiden Säulen aus Bronze: achtzehn Ellen <betrug> die Höhe der einen Säule, und ein Faden von zwölf* Ellen *umspannte sie; ihre <Wand>stärke war vier Finger<breit>, und innen war sie hohl; ebenso war die andere Säule*.", footnotes: ["℘ V. 15-22: 2Chr 3,15-17; 4,12.13", "LXX: vierzehn", "so mit LXX und Jer 52,21; Mas. T.: umspannte die andere Säule", "so mit LXX und Jer 52,21; Mas. T.: umspannte die andere Säule\n℘ 2Kö 25,13.17; Jer 27,19"] },
      { number: 16, text: "Und er machte zwei Kapitelle, aus Bronze gegossen, um sie oben auf die Säulen zu setzen: fünf Ellen die Höhe des einen Kapitells und fünf Ellen die Höhe des anderen Kapitells." },
      { number: 17, text: "Geflecht in Flechtwerk, Schnüre in Kettenwerk waren an den Kapitellen, die oben auf den Säulen waren: sieben für das eine Kapitell und sieben für das andere Kapitell." },
      { number: 18, text: "Und er machte die Granatäpfel*, und zwar zwei Reihen ringsherum auf dem einen Geflecht zur Bedeckung der Kapitelle, die oben auf den Säulen* waren; und ebenso machte er es für das andere Kapitell.", footnotes: ["so mit 2 hebr. Handschr. und Jer 52,22; Mas. T.: die Säulen", "so mit vielen hebr. Handschr. und der syr. Üs.; Mas. T.: die auf den Granatäpfeln waren"] },
      { number: 19, text: "Und die Kapitelle, die oben auf den Säulen waren, *sie alle waren in Lilienarbeit*, vier Ellen <hoch>.", footnotes: ["T.; Mas. T.: waren <wie die> Lilienarbeit in der Vorhalle", "T.; Mas. T.: waren <wie die> Lilienarbeit in der Vorhalle"] },
      { number: 20, text: "Und Kapitelle waren auf den beiden Säulen auch oben darüber, dicht bei der Ausbuchtung, die hinter dem Geflecht war. Und zweihundert Granatäpfel waren in Reihen ringsum auf dem <einen Kapitell und ebenso auf dem> anderen Kapitell*.", footnotes: ["℘ Jer 52,21-23"] },
      { number: 21, text: "Und er stellte die Säulen an der Vorhalle* des Tempelraums* auf*. Er stellte die rechte Säule auf und gab ihr den Namen Jachin*, und er stellte die linke Säule auf und gab ihr den Namen Boas*.", footnotes: ["o. für die Vorhalle", "℘ Kap. 6,3", "℘ Hes 40,49", "d. h. er wird feststellen o. befestigen", "d. h. in der Stärke"] },
      { number: 22, text: "Und oben auf den Säulen war Lilienarbeit. So wurde das Werk der Säulen vollendet*.", footnotes: ["℘ V. 41.42"] },
      { number: 23, text: "*Und er machte das Meer*, gegossen, zehn Ellen von seinem <einen> Rand bis zu seinem <anderen> Rand, ringsum rund und fünf Ellen seine Höhe; und eine Messschnur von dreißig Ellen umspannte es ringsherum.", footnotes: ["℘ V. 23-39: 2Chr 4,2-6; vgl. 2Mo 30,17-21", "℘ 2Kö 25,13; Jer 27,19"] },
      { number: 24, text: "Unterhalb seines Randes umgaben es ringsum Koloquinten<blätter>*, dreißig Ellen lang*, das Meer ringsum einschließend. In zwei Reihen waren die Koloquinten bei seinem Guss <mit>gegossen worden.", footnotes: ["s. Anm. zu Kap. 6,18", "so mit V. 23; Mas. T.: zehn Ellen lang"] },
      { number: 25, text: "Es stand auf zwölf Rindern: Drei waren nach Norden gewandt, drei waren nach Westen gewandt, drei waren nach Süden gewandt, und drei waren nach Osten gewandt; und das Meer <stand> oben auf ihnen, und ihre Hinterteile waren alle nach innen <gekehrt>." },
      { number: 26, text: "Seine Dicke war eine Handbreit und sein Rand wie der Rand eines Bechers gearbeitet, als Lilienblüte; es fasste zweitausend Bat*.", footnotes: ["℘ Hes 45,11"] },
      { number: 27, text: "Und er machte die zehn Gestelle* aus Bronze: vier Ellen <betrug> die Länge eines Gestells und vier Ellen seine Breite und drei Ellen seine Höhe.", footnotes: ["℘ 2Kö 25,13; Jer 27,19"] },
      { number: 28, text: "Und dies war die Bauart der Gestelle: Sie hatten <Schluss>leisten und <außerdem> Leisten zwischen den Sprossen*;", footnotes: ["o. Verbindungsleisten; o. Querstäben"] },
      { number: 29, text: "und auf den Leisten, die zwischen den Sprossen* waren, <befanden sich> Löwen, Rinder und Cherubim* und auf den Sprossen* ebenso; <und> oberhalb* und unterhalb der Löwen und der Rinder waren Kränze in gehämmerter Arbeit*.", footnotes: ["o. Verbindungsleisten; o. Querstäben", "℘ Hes 41,18.19", "o. Verbindungsleisten; o. Querstäben", "so mit anderer Zeichensetzung; Mas. T.: und auf den Sprossen ebenso oberhalb", "o. Kränze als Gehänge gearbeitet"] },
      { number: 30, text: "Jedes Gestell hatte vier bronzene Räder* und bronzene Achsen, und seine vier Füße hatten Seitenstücke; unterhalb der Kessel waren die Seitenstücke angegossen; einem jeden gegenüber <waren> Kränze.", footnotes: ["℘ Hes 10,9"] },
      { number: 31, text: "Seine Öffnung war innerhalb der Seitenstücke* und <ragte> eine Elle darüber hinaus, und ihre Öffnung war rund, in Gestalt eines Untersatzes, eine Elle und eine halbe Elle; und auch an ihrer Öffnung war Schnitzwerk. Und ihre Leisten waren viereckig, nicht rund.", footnotes: ["T.; Mas. T.: Seine Öffnung war innerhalb des Kapitells"] },
      { number: 32, text: "Die vier Räder <befanden sich> unterhalb der Leisten; und die Halter der Räder waren am Gestell; und die Höhe eines Rades <betrug> eine Elle und eine halbe Elle;" },
      { number: 33, text: "und die Bauart der Räder war wie die Bauart eines Wagenrades; ihre Halter und ihre Felgen und ihre Speichen und ihre Naben, das alles war gegossen." },
      { number: 34, text: "Und vier Seitenstücke waren an den vier Ecken des einzelnen Gestells: Aus <einem Stück mit> dem Gestell waren seine Seitenstücke*.", footnotes: ["o. Von dem Gestell <gingen> seine Seitenstücke <aus>"] },
      { number: 35, text: "Und oben auf dem Gestell war ein <Untersatz>, eine halbe Elle hoch, rund ringsherum; und oben auf dem Gestell waren seine Halter und seine Leisten aus <einem Stück mit> ihm*.", footnotes: ["o. und oben auf dem Gestell <gingen> seine Halter und seine Leisten von ihm <aus>"] },
      { number: 36, text: "Und er gravierte auf den <Seiten>platten, <auf> seinen Haltern und auf seinen Feldern Cherubim, Löwen und Palmen ein nach der freien Fläche* eines jeden und Kränze ringsum.", footnotes: ["w. nach der Blöße"] },
      { number: 37, text: "In dieser Weise machte er die zehn Gestelle: Einen Guss, ein Maß, einen Zuschnitt hatten sie alle." },
      { number: 38, text: "Und er machte zehn Kessel aus Bronze. Vierzig Bat fasste der einzelne Kessel; vier Ellen war der einzelne Kessel <weit>; je ein Kessel <kam> auf je ein Gestell von den zehn Gestellen." },
      { number: 39, text: "Und er stellte die Gestelle auf: fünf auf die rechte Seite* des Hauses und fünf auf die linke Seite* des Hauses. Und das Meer stellte er an der rechten Seite des Hauses auf, ostwärts, in Richtung Süden*.", footnotes: ["d. i. die Südseite", "d. i. die Nordseite", "d. h. in südöstlicher Richtung\n℘ 2Chr 4,10; 2Chr 4,7-22; 5,1"] },
      { number: 40, text: "Und Hiram* machte die Töpfe* und die Schaufeln und die Sprengschalen*. Und so vollendete Hiram die Arbeit an dem ganzen Werk, das er dem König Salomo für das Haus des HERRN ausführte*:", footnotes: ["so mit LXX und Vulg.; Mas. T.: Hirom", "so mit vielen hebr. Handschr., LXX und Vulg.; Mas. T.: Kessel", "℘ 2Mo 27,3; 2Kö 25,14", "℘ 2Mo 39,32"] },
      { number: 41, text: "zwei Säulen und die kugelförmigen Kapitelle*, die oben auf den beiden Säulen waren; und die beiden Geflechte, um die beiden kugelförmigen Kapitelle*, die oben auf den Säulen waren, zu bedecken;", footnotes: ["w. die Becken der Kapitelle", "w. die Becken der Kapitelle"] },
      { number: 42, text: "und die vierhundert Granatäpfel für die beiden Geflechte: zwei Reihen Granatäpfel für das einzelne Geflecht, um die beiden kugelförmigen Kapitelle*, die auf der Oberseite der Säulen waren, zu bedecken;", footnotes: ["w. die Becken der Kapitelle"] },
      { number: 43, text: "und die zehn Gestelle und die zehn Kessel auf den Gestellen;" },
      { number: 44, text: "das eine Meer und die zwölf Rinder unter dem Meer;" },
      { number: 45, text: "und die Töpfe und die Schaufeln und die Sprengschalen*. Alle diese Geräte, die Hiram dem König Salomo für das Haus des HERRN machte, waren aus blanker Bronze.", footnotes: ["℘ 2Mo 27,3; 2Kö 25,14"] },
      { number: 46, text: "In der Jordanebene* ließ der König sie gießen in der Erdgießerei zwischen Sukkot* und Zaretan*.", footnotes: ["w. Im Umkreis des Jordan", "℘ 1Mo 33,17", "℘ Kap. 4,12"] },
      { number: 47, text: "Und Salomo ließ alle Geräte ungewogen* wegen der sehr, sehr großen Menge. Das Gewicht der Bronze war nicht feststellbar.*", footnotes: ["w. ließ alle Geräte liegen. — Andere üs.: stellte alle Geräte auf", "℘ 2Kö 25,16; 1Chr 22,3.14"] },
      { number: 48, text: "Und Salomo machte alle die Geräte, die das Haus des HERRN <braucht>: den goldenen Altar*; und den goldenen Tisch, auf dem die Schaubrote <liegen>*;", footnotes: ["℘ 2Mo 30,1.2", "℘ 2Mo 25,23.30.31.38"] },
      { number: 49, text: "und die Leuchter, fünf zur Rechten und fünf zur Linken vor dem Hinterraum*, aus gediegenem Gold*; und die Blüten, die Lampen und die Dochtscheren aus Gold;", footnotes: ["d. i. das Allerheiligste", "℘ 2Mo 25,23.30.31.38"] },
      { number: 50, text: "und die Becken und die Messer*, die Sprengschalen, die Schalen und die Feuerbecken* aus gediegenem Gold*; und die Angeln an den Türflügeln des inneren Hauses, des Allerheiligsten, <und> an den Türflügeln des Hauses, des Tempelraums, aus Gold.", footnotes: ["Das sind Messer zum Putzen der Leuchter.", "Das sind Gefäße zur Aufbewahrung oder zum Transport brennender Kohlen.", "℘ Sach 14,20"] },
      { number: 51, text: "So wurde das ganze Werk, das der König Salomo ausführte*, das Haus des HERRN, vollendet. Und Salomo brachte die heiligen Gaben* seines Vaters David hinein. Das Silber und das Gold und die Geräte legte er in die Schatzkammern des Hauses des HERRN.*", footnotes: ["℘ Kap. 6,14", "o. heiligen Dinge", "℘ 2Sam 8,11; 2Kö 25,15; 1Chr 28,12"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "*Damals versammelte Salomo die Ältesten von Israel* <und> alle Oberhäupter der Stämme, die Fürsten der Geschlechter* der Söhne Israel, zum König Salomo nach Jerusalem, um die Lade des Bundes des HERRN heraufzuholen aus der Stadt Davids*, das ist Zion.", heading: "Tempelweihe — Salomos Ansprache, Gebet und Festopfer", footnotes: ["℘ V. 8-11: 2Chr 5,2-14", "℘ Jos 23,2", "w. die Fürsten der Väter", "℘ Kap. 2,10; 1Chr 15,3"] },
      { number: 2, text: "Und alle Männer von Israel versammelten sich zum König Salomo im Monat Etanim*, das ist der siebte Monat, am Fest*.", footnotes: ["Sonst Tischri genannt, ein Teil von September und Oktober. Das Laubhüttenfest fand am 15. dieses Monats statt.", "℘ 3Mo 23,34; 2Chr 7,8.9"] },
      { number: 3, text: "Alle Ältesten von Israel kamen, und die Priester trugen die Lade*", footnotes: ["℘ 4Mo 4,15; 5Mo 31,9"] },
      { number: 4, text: "und brachten die Lade des HERRN hinauf, dazu das Zelt der Begegnung und alle heiligen Geräte, die im Zelt waren; die Priester und die Leviten brachten sie hinauf*.", footnotes: ["℘ 2Sam 6,12"] },
      { number: 5, text: "Und der König Salomo und die ganze Gemeinde Israel, die sich bei ihm eingefunden hatte <und> mit ihm vor der Lade <stand>, opferten Schafe und Rinder, die vor Menge nicht berechnet und nicht gezählt werden konnten.*", footnotes: ["℘ 2Sam 6,13.17"] },
      { number: 6, text: "Und die Priester brachten die Lade des Bundes des HERRN an ihren Platz in den Hinterraum des Hauses, in das Allerheiligste*, unter die Flügel der Cherubim*;", footnotes: ["℘ 2Mo 26,33", "℘ Kap. 6,19.23-27; 1Chr 22,19; Ps 80,2; Jes 37,16; Offb 11,19"] },
      { number: 7, text: "denn die Cherubim breiteten die Flügel aus über den Platz der Lade, und die Cherubim beschirmten die Lade und ihre Stangen von oben her." },
      { number: 8, text: "Und die Stangen waren so lang, dass die Enden der Stangen <nur> vom Heiligen aus, vor dem Hinterraum, zu sehen waren; aber nach außen waren sie nicht sichtbar. Und sie sind dort bis zum heutigen Tag*.", footnotes: ["℘ 2Mo 25,15"] },
      { number: 9, text: "Nichts war in der Lade als nur die beiden steinernen Tafeln, die Mose am Horeb dort hineingelegt hatte*, als der HERR mit den Söhnen Israel <einen Bund> schloss, als sie aus dem Land Ägypten zogen*.", footnotes: ["℘ 2Mo 25,21", "℘ V. 21; 5Mo 4,13; Hebr 9,4"] },
      { number: 10, text: "Und es geschah, als die Priester aus dem Heiligen hinausgingen, da erfüllte die Wolke* das Haus des HERRN*;", footnotes: ["℘ Mk 9,7", "℘ 2Mo 40,34.35; Jes 6,1.4; Hes 10,4; Hag 2,7"] },
      { number: 11, text: "und die Priester konnten wegen der Wolke nicht hinzutreten, um den Dienst zu verrichten; denn die Herrlichkeit des HERRN erfüllte das Haus des HERRN*.", footnotes: ["℘ 2Mo 40,34.35; Jes 6,1.4; Hes 10,4; Hag 2,7"] },
      { number: 12, text: "*Damals sprach Salomo: Der HERR hat gesagt, dass er im Dunkel wohnen will*.", footnotes: ["℘ V. 12-21: 2Chr 6,1-11", "LXX: Die Sonne hat der HERR am Himmel festgesetzt. Er <selbst aber> hat gesagt, dass er im Dunkeln wohnen will\n℘ 2Mo 20,21; Ps 97,2"] },
      { number: 13, text: "Gebaut, ja gebaut habe ich ein fürstliches Haus* für dich, eine Stätte, wo du thronen* sollst für Ewigkeiten*.*", footnotes: ["℘ Ps 132,14; Mt 23,21", "o. wohnen", "℘ Hes 43,7.9", "LXX überliefert hier außerdem: Ist das nicht geschrieben im Buch der Lieder?"] },
      { number: 14, text: "Darauf wandte der König sein Angesicht und segnete die ganze Versammlung Israels*, wobei die ganze Versammlung Israels dastand*;", footnotes: ["℘ V. 55; 2Sam 6,18", "℘ Neh 8,7"] },
      { number: 15, text: "und er sagte: Gepriesen sei der HERR, der Gott Israels*, der mit seinem Mund zu meinem Vater David geredet und mit seiner Hand erfüllt hat*, <was er verheißen hatte,> als er sprach:", footnotes: ["℘ 1Sam 25,32; 1Chr 29,10", "℘ Jos 21,45; Ps 138,2"] },
      { number: 16, text: "Von dem Tag an, da ich mein Volk Israel aus Ägypten herausführte, habe ich aus allen Stämmen Israels keine Stadt erwählt, um <darin> ein Haus zu bauen, damit mein Name dort sei*; aber ich habe David erwählt, dass er <König> über mein Volk Israel sei*.", footnotes: ["℘ 2Sam 7,6.7; 1Chr 17,6", "℘ Ps 78,70.71"] },
      { number: 17, text: "Nun lag es meinem Vater David am Herzen, dem Namen des HERRN, des Gottes Israels, ein Haus zu bauen*.", footnotes: ["℘ 1Chr 17,2; 28,2; Apg 7,46"] },
      { number: 18, text: "Doch der HERR sprach zu meinem Vater David: Dass dir <das> am Herzen lag, meinem Namen ein Haus zu bauen, <daran> hast du gut getan, dass dir <das> am Herzen lag*.", footnotes: ["℘ 2Sam 7,3"] },
      { number: 19, text: "Jedoch wirst du selbst das Haus nicht bauen, sondern dein Sohn, der aus deinen Lenden hervorkommt*, der wird meinem Namen das Haus bauen.*", footnotes: ["d. h. der von dir abstammt; die Lenden galten als Sitz der Zeugungskraft", "℘ 1Chr 17,11; 22,10"] },
      { number: 20, text: "Und der HERR hat sein Wort aufrechterhalten, das er geredet hat*. So bin ich denn an die Stelle meines Vaters David getreten und habe mich auf den Thron Israels gesetzt*, so wie der HERR zugesagt hat, und habe dem Namen des HERRN, des Gottes Israels, das Haus gebaut*;", footnotes: ["℘ Kap. 1,48", "℘ Kap. 1,48", "℘ 1Chr 28,6; Apg 7,47"] },
      { number: 21, text: "und ich habe dort einen Platz für die Lade hergerichtet, in der der Bund des HERRN ist, den er mit unseren Vätern geschlossen hat, als er sie aus dem Land Ägypten herausführte*.", footnotes: ["℘ V. 9; 2Mo 24,8"] },
      { number: 22, text: "*Und Salomo trat vor den Altar des HERRN angesichts der ganzen Versammlung Israels und breitete seine Hände zum Himmel aus*.", footnotes: ["℘ V. 22-61: 2Chr 6,12-42", "℘ 2Mo 9,29"] },
      { number: 23, text: "Und er sprach: HERR, Gott Israels! Kein Gott ist dir gleich im Himmel oben und auf der Erde unten*, der du den Bund und die Gnade deinen Knechten bewahrst, die vor dir leben* mit ihrem ganzen Herzen*;", footnotes: ["℘ 2Mo 15,11; 2Sam 7,22", "w. gehen", "℘ 5Mo 7,9; 2Kö 20,3"] },
      { number: 24, text: "der du deinem Knecht, meinem Vater David, gehalten hast, was du ihm zugesagt hast. Mit deinem Mund hast du es geredet, und mit deiner Hand hast du es erfüllt, wie es am heutigen Tag ist*.", footnotes: ["℘ Jos 21,45; Ps 138,2"] },
      { number: 25, text: "Und nun, HERR, Gott Israels, halte deinem Knecht, meinem Vater David, was du ihm zugesagt hast, als du sprachst: Es soll dir nicht an einem Mann fehlen vor meinem Angesicht*, der auf dem Thron Israels sitzt, wenn nur deine Söhne auf ihren Weg achten, dass sie vor mir leben*, wie du vor mir gelebt hast*.", footnotes: ["w. Nicht soll dir ausgerottet werden ein Mann von meinem Angesicht weg", "w. gehen/gegangen bist", "w. gehen/gegangen bist\n℘ Kap. 2,4; 3,3; Ps 132,12"] },
      { number: 26, text: "Und nun, Gott Israels, mögen sich doch deine Worte als zuverlässig erweisen, die du zu deinem Knecht, meinem Vater David, geredet hast!* —", footnotes: ["℘ 1Chr 17,23; Ps 119,38"] },
      { number: 27, text: "Ja, sollte Gott wirklich auf der Erde wohnen? Siehe, der Himmel und die Himmel der Himmel* können dich nicht fassen; wie viel weniger dieses Haus, das ich gebaut habe!*", footnotes: ["℘ 5Mo 10,14", "℘ 2Chr 2,5; Jes 66,1; Apg 7,48"] },
      { number: 28, text: "Doch wende dich zu dem Gebet deines Knechtes und zu seinem Flehen, HERR, mein Gott, dass du hörst auf das Rufen und auf das Gebet, das dein Knecht heute vor dir betet*,", footnotes: ["℘ Ps 5,2.3; Jes 37,15; Dan 9,17"] },
      { number: 29, text: "dass deine Augen Nacht und Tag geöffnet seien* über dieses Haus hin, über die Stätte, von der du gesagt hast: Mein Name soll dort sein*, dass du hörst auf das Gebet, das dein Knecht zu dieser Stätte hin betet*.", footnotes: ["℘ Sach 12,4", "℘ Kap. 9,3; 11,36; 14,21; 5Mo 12,5.11; 2Kö 21,4.7", "℘ 2Kö 19,16; 2Chr 7,15; Neh 1,6"] },
      { number: 30, text: "Und höre auf das Flehen deines Knechtes und deines Volkes Israel, das sie zu dieser Stätte hin richten werden.* Du selbst mögest es hören an der Stätte, wo du thronst, im Himmel*, ja, höre und vergib*!*", footnotes: ["℘ 2Chr 20,9; Ps 28,2", "℘ 2Chr 20,6; Ps 123,1", "o. Du selbst mögest es hören bis hin zum Ort deines Wohnens, bis hin zum Himmel; und wenn du es hörst, dann vergib", "℘ Dan 9,19"] },
      { number: 31, text: "Wenn jemand gegen seinen Nächsten sündigt und der einen Fluch auf ihn legt*, um ihn unter einen Fluch zu stellen, und er kommt <und> spricht den Fluch aus vor deinem Altar in diesem Haus,", footnotes: ["so mit hebr. Handschr. und LXX; Mas. T.: und <von> ihm einen <geleisteten> Fluch (o. Eid) einfordert"] },
      { number: 32, text: "dann höre du es im Himmel und handle und richte deine Knechte, indem du den Schuldigen schuldig sprichst, um seinen Weg auf sein Haupt zu bringen*, und indem du den Gerechten gerecht sprichst, um ihm nach seiner Gerechtigkeit zu geben*!", footnotes: ["℘ Kap. 2,32.33.44; 2Mo 34,7; Est 9,25; Hes 9,10; Joe 4,4; Apg 18,6", "℘ 1Sam 2,25; Ps 7,9"] },
      { number: 33, text: "Wenn dein Volk Israel vor dem Feind geschlagen wird, weil sie gegen dich gesündigt haben*, und sie kehren zu dir um und preisen deinen Namen und beten und flehen zu dir <um Gnade> in diesem Haus*,", footnotes: ["℘ 3Mo 26,17", "℘ V. 47"] },
      { number: 34, text: "dann höre du es im Himmel und vergib die Sünde deines Volkes Israel; und bring sie in das Land zurück, das du ihren Vätern gegeben hast!*", footnotes: ["℘ 5Mo 30,1-5; Ps 106,46"] },
      { number: 35, text: "Bleibt der Himmel verschlossen, so dass es keinen Regen gibt*, weil sie gegen dich gesündigt haben, und sie beten zu dieser Stätte hin und preisen deinen Namen und kehren um von ihrer Sünde, weil du sie demütigst,", footnotes: ["℘ Kap. 17,1; 3Mo 26,19; Hag 1,10; Sach 14,17"] },
      { number: 36, text: "dann höre du es im Himmel und vergib die Sünde deiner Knechte und deines Volkes Israel — denn du zeigst ihnen den guten Weg, auf dem sie gehen sollen* — und gib Regen auf dein Land*, das du deinem Volk zum Erbteil gegeben hast!", footnotes: ["℘ Ps 25,4; 32,8", "℘ Ps 68,10; Joe 2,23"] },
      { number: 37, text: "Wenn eine Hungersnot im Land herrscht, wenn eine Pest ausbricht, wenn es Getreidebrand, Vergilben <des Getreides>, Heuschrecken <oder> Heuschreckenlarven gibt, wenn sein Feind es im Land seiner Tore belagert, <wenn es also> irgendeine Plage, irgendeine Krankheit <gibt>*", footnotes: ["℘ 5Mo 28,22.42; 2Chr 20,9"] },
      { number: 38, text: "<und dann> irgendein Gebet, irgendein Flehen <aufsteigt>, was von irgendeinem Menschen <oder> von deinem ganzen Volk Israel geschehen mag — <je nachdem,> was einer als Plage seines Herzens erkennt —, und er zu diesem Haus hin seine Hände ausbreitet," },
      { number: 39, text: "dann höre du es im Himmel, der Stätte, wo du thronst*, und vergib und handle und gib jedem nach all seinen Wegen, da du sein Herz kennst — denn du, du allein kennst das Herz aller Menschenkinder* —,", footnotes: ["w. der Stätte deines Thronens o. Wohnens", "℘ Jos 22,22; 1Sam 16,7; 1Chr 28,9; Ps 139,1.2; Hebr 4,13"] },
      { number: 40, text: "damit sie dich fürchten* all die Tage, die sie in dem Land leben, das du unsern Vätern gegeben hast!", footnotes: ["℘ 5Mo 6,2; Ps 130,4"] },
      { number: 41, text: "Und auch auf den Ausländer, der nicht von deinem Volk Israel ist*, aber wegen deines Namens aus fernem Land kommt* —", footnotes: ["℘ Jes 56,6.7", "℘ Jer 3,17; Joh 12,20; Apg 8,27"] },
      { number: 42, text: "denn sie werden von deinem großen Namen* hören und von deiner starken Hand* und deinem ausgestreckten Arm* —, wenn er nun kommt und betet zu diesem Haus hin*,", footnotes: ["℘ Ps 8,10", "℘ Jos 4,24", "℘ 2Mo 6,6; 2Kö 17,36; Jes 63,12; Jer 27,5; Hes 20,33.34", "℘ 4Mo 15,14-16"] },
      { number: 43, text: "<dann> höre du es im Himmel, der Stätte, wo du thronst*, und handle nach allem, worum der Ausländer zu dir ruft, damit alle Völker der Erde deinen Namen erkennen*, damit sie dich fürchten wie dein Volk Israel und damit sie erkennen, dass dein Name ausgerufen ist über diesem Haus, das ich gebaut habe!", footnotes: ["w. der Stätte deines Thronens o. Wohnens\n℘ 5Mo 26,15", "℘ 2Kö 19,19"] },
      { number: 44, text: "Wenn dein Volk zum Krieg gegen seinen Feind auszieht* auf dem Weg, den du sie sendest, und <wenn> sie <dann> zum HERRN beten in Richtung auf die Stadt, die du erwählt hast, und <auf> das Haus, das ich deinem Namen gebaut habe,", footnotes: ["℘ 2Chr 20,5.6"] },
      { number: 45, text: "dann höre im Himmel ihr Gebet und ihr Flehen und schaffe <ihnen> ihr Recht!*", footnotes: ["℘ Ps 9,4.5"] },
      { number: 46, text: "Wenn sie gegen dich sündigen — denn es gibt keinen Menschen, der nicht sündigt* — und du über sie erzürnst und sie vor dem Feind dahingibst und ihre Bezwinger* sie gefangen wegführen in das Land des Feindes, <in> ein fernes oder ein nahes*,", footnotes: ["℘ Hi 15,14; Spr 20,9; Pred 7,20; 1Jo 1,10", "w. Fänger, o. Wegführer", "℘ 3Mo 26,33; 2Kö 17,6; 25,21"] },
      { number: 47, text: "und sie nehmen es sich zu Herzen in dem Land, wohin sie gefangen weggeführt worden sind, und kehren um* und flehen zu dir im Land ihrer Bezwinger*, indem sie sagen: Wir haben gesündigt und haben uns schuldig gemacht, wir haben gottlos gehandelt*;", footnotes: ["℘ V. 33; 3Mo 26,40", "w. Fänger, o. Wegführer", "℘ 1Sam 7,6; Esr 9,6.7; Ps 106,6; Lk 15,18.21"] },
      { number: 48, text: "und sie kehren zu dir um* mit ihrem ganzen Herzen* und mit ihrer ganzen Seele im Land ihrer Feinde, die sie gefangen weggeführt haben, und sie beten zu dir in Richtung auf ihr Land, das du ihren Vätern gegeben hast*, <auf> die Stadt, die du erwählt hast, und <auf> das Haus, das ich deinem Namen gebaut habe,", footnotes: ["℘ V. 33; 3Mo 26,40", "℘ 1Sam 7,3; 2Kö 23,25; Jer 29,13", "℘ Dan 6,11"] },
      { number: 49, text: "dann höre im Himmel, der Stätte, wo du thronst*, ihr Gebet und ihr Flehen und schaffe <ihnen> ihr Recht!", footnotes: ["w. der Stätte deines Thronens o. Wohnens"] },
      { number: 50, text: "Und vergib* deinem Volk, worin sie gegen dich gesündigt haben, und alle ihre Vergehen, mit denen sie sich gegen dich vergangen haben*; und lass sie Erbarmen finden vor ihren Bezwingern*, dass die sich über sie erbarmen*!", footnotes: ["℘ 2Chr 33,13; Ps 32,5", "o. ihre <Treue>brüche, durch die sie <den Bund> mit dir gebrochen haben", "w. ihren Fängern o. Wegführern", "℘ 2Chr 30,9; Ps 106,46"] },
      { number: 51, text: "Denn sie sind dein Volk und dein Erbteil, das du aus Ägypten*, mitten aus dem Eisenschmelzofen*, herausgeführt hast.", footnotes: ["℘ 5Mo 9,29", "℘ 5Mo 4,20"] },
      { number: 52, text: "So lass deine Augen offen sein für das Flehen deines Knechtes und für das Flehen deines Volkes Israel, dass du auf sie hörst, sooft sie zu dir rufen!" },
      { number: 53, text: "Denn du, du hast sie für dich zum Erbteil ausgesondert* aus allen Völkern der Erde, so wie du durch deinen Knecht Mose geredet hast, als du unsere Väter aus Ägypten herausführtest*, Herr, HERR!", footnotes: ["℘ 2Sam 20,19", "℘ 2Mo 19,5.6"] },
      { number: 54, text: "*Und es geschah, als Salomo dieses ganze Gebet und Flehen zu dem HERRN zu Ende gebetet hatte, stand er auf von <der Stelle> vor dem Altar des HERRN, wo er auf den Knien gelegen hatte, seine Hände zum Himmel ausgebreitet.", footnotes: ["℘ V. 54-66: 2Chr 7,1-10"] },
      { number: 55, text: "Und er trat hin und segnete die ganze Versammlung Israels* mit lauter Stimme und sprach:", footnotes: ["℘ V. 14; 2Mo 39,43; 1Chr 16,2"] },
      { number: 56, text: "Gepriesen sei der HERR, der seinem Volk Israel Ruhe gegeben hat*, nach allem, was er geredet hat*! Nicht ein einziges Wort ist dahingefallen von all seinen guten Worten, die* er durch seinen Knecht Mose geredet hat.", footnotes: ["℘ 1Chr 22,9", "℘ Jos 21,45", "w. von seinem ganzen guten Wort, das"] },
      { number: 57, text: "Der HERR, unser Gott, sei mit uns, so wie er mit unseren Vätern gewesen ist. Er verlasse uns nicht und verstoße uns nicht*,", footnotes: ["℘ 5Mo 31,6"] },
      { number: 58, text: "um so unser Herz zu ihm zu neigen, damit wir auf all seinen Wegen gehen und seine Gebote und seine Ordnungen und seine Rechtsbestimmungen einhalten, die er unseren Vätern geboten hat*!", footnotes: ["℘ Ps 119,36"] },
      { number: 59, text: "Möchten diese meine Worte, mit denen ich vor dem HERRN um Gnade gefleht habe, dem HERRN, unserm Gott, nahe sein, Tag und Nacht*, dass er das Recht seines Knechtes und das Recht seines Volkes Israel ausführe — die Sache eines <jeden> Tages an ihrem Tag —,", footnotes: ["℘ Jes 27,3"] },
      { number: 60, text: "damit alle Völker der Erde erkennen, dass der HERR Gott ist und sonst keiner!*", footnotes: ["℘ 2Mo 6,7; Jes 37,20"] },
      { number: 61, text: "Und euer Herz sei ungeteilt mit dem HERRN*, unserem Gott, in seinen Ordnungen zu leben* und seine Gebote zu halten, wie es am heutigen Tag ist!", footnotes: ["℘ Kap. 3,3; 15,14; 1Chr 28,9", "w. zu gehen"] },
      { number: 62, text: "Und der König und ganz Israel mit ihm brachten vor dem HERRN Schlachtopfer dar*.*", footnotes: ["w. schlachteten vor dem HERRN Schlachtopfer", "℘ 1Chr 16,1"] },
      { number: 63, text: "Und Salomo schlachtete als Heilsopfer*, das er dem HERRN darbrachte*, 22 000 Rinder und 120 000 Schafe. So weihten der König und alle Söhne Israel das Haus des HERRN ein*.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; d. i. ein Gemeinschaftsopfer wie das Schlachtopfer", "w. schlachtete", "℘ 4Mo 7,10; Esr 6,16.17; Ps 30,1"] },
      { number: 64, text: "An jenem Tag heiligte der König die Mitte des Vorhofes, der vor dem Haus des HERRN <lag>; denn dort bereitete er das Brandopfer zu und das Speisopfer und die Fettstücke der Heilsopfer*; denn der bronzene Altar*, der vor dem HERRN <stand>, war zu klein, um das Brandopfer und das Speisopfer und die Fettstücke der Heilsopfer* zu fassen.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; d. i. ein Gemeinschaftsopfer wie das Schlachtopfer", "℘ 2Chr 4,1", "o. Friedensopfer; o. Abschlussopfer; d. i. ein Gemeinschaftsopfer wie das Schlachtopfer"] },
      { number: 65, text: "Und Salomo veranstaltete zu jener Zeit das Fest* und ganz Israel mit ihm, eine große Versammlung, von da, wo man nach Hamat hineinkommt*, bis an den Bach Ägyptens*, vor dem HERRN, unserm Gott, sieben Tage lang und <weitere> sieben Tage, <zusammen> vierzehn Tage*.", footnotes: ["d. i. das Laubhüttenfest", "o. von Lebo-Hamat", "℘ 4Mo 34,5.8; Jos 15,1; Jes 27,12", "nämlich deshalb, weil das Laubhüttenfest im Anschluss an das Tempelweihfest gefeiert wurde\n℘ 2Chr 30,23"] },
      { number: 66, text: "Am achten Tag entließ er das Volk*. Und sie segneten den König* und gingen zu ihren Zelten, fröhlich und guten Mutes über all das Gute, das der HERR seinem Knecht David und seinem Volk Israel erwiesen hatte*.", footnotes: ["℘ Jos 22,6", "o. sie dankten dem König; o. sie priesen den König", "℘ Neh 8,10"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "*Und es geschah, als Salomo den Bau des Hauses des HERRN und des Hauses des Königs vollendet hatte*, dazu alles, was Salomo gefiel, <alles,> was er auszuführen wünschte,", heading: "Gottes Antwort auf Salomos Gebet", footnotes: ["℘ 2Chr 7,11-22", "℘ V. 10; Kap. 3,1; 6,37-7,8; 2Chr 8,1"] },
      { number: 2, text: "da erschien der HERR dem Salomo zum zweiten Mal, wie er ihm in Gibeon erschienen war*.", footnotes: ["℘ Kap. 3,5"] },
      { number: 3, text: "Und der HERR sprach zu ihm: Ich habe dein Gebet und dein Flehen gehört*, das du vor mir gefleht hast. Ich habe dieses Haus, das du gebaut hast, geheiligt*, um meinen Namen dort niederzulegen* für ewig; und meine Augen und mein Herz sollen allezeit dort <gegenwärtig> sein*.", footnotes: ["℘ 2Kö 20,5; Ps 65,3; 66,19.20; 116,1; Apg 10,31", "℘ 2Mo 29,44", "℘ Kap. 8,29; Ps 132,14; Jer 7,10; Joh 4,20", "℘ 5Mo 11,12"] },
      { number: 4, text: "Und du, wenn du vor mir lebst, ebenso wie dein Vater David gelebt hat* in Lauterkeit des Herzens und in Aufrichtigkeit, indem du nach allem handelst, was ich dir geboten habe, und <wenn> du meine Ordnungen und meine Rechtsbestimmungen einhältst,", footnotes: ["w. wenn du vor mir gehst, ebenso wie dein Vater David gegangen ist\n℘ Kap. 3,3; 2Sam 22,22; 2Chr 17,4; Hes 18,9"] },
      { number: 5, text: "dann werde ich den Thron deines Königtums über Israel festigen für ewig, so wie ich über deinen Vater David geredet habe, als ich sprach: Es soll dir nicht an einem Mann auf dem Thron Israels fehlen*.", footnotes: ["w. Nicht soll dir ein Mann ausgerottet werden vom Thron Israels hinweg\n℘ Kap. 2,4"] },
      { number: 6, text: "Wenn ihr euch aber von mir abwendet*, ihr und eure Kinder, und meine Gebote <und> meine Ordnungen, die ich euch vorgelegt habe, nicht einhaltet, sondern hingeht und anderen Göttern dient und euch vor ihnen niederwerft*,", footnotes: ["w. Wenn ihr euch aber abwendet, ja abwendet von <der Nachfolge> hinter mir her", "℘ Kap. 11,10; Ps 89,31.32"] },
      { number: 7, text: "dann werde ich Israel ausrotten aus dem Land*, das ich ihnen gegeben habe*; und das Haus, das ich meinem Namen geheiligt habe, werde ich von meinem Angesicht wegstoßen*. So wird Israel zum Sprichwort und zur Spottrede unter allen Völkern werden.*", footnotes: ["w. ausrotten von der Fläche des Landes", "℘ Jos 23,16; 2Kö 17,23; Hos 9,3", "℘ 2Kö 25,9; Jer 7,12-15; Hes 24,21; Mt 23,38", "℘ 5Mo 28,37; Ps 44,15; Kla 1,8; 2,17; Hes 5,15"] },
      { number: 8, text: "Und dieses Haus wird eine Trümmerstätte werden*; jeder, der an ihm vorübergeht, wird sich entsetzen und pfeifen. Und man wird sagen: Warum hat der HERR an diesem Land und an diesem Haus so gehandelt?*", footnotes: ["So lesen die alte lat., die syr. und arab. Üs.; Mas. T.: dieses Haus wird erhaben sein", "℘ 5Mo 29,23-28; 2Kö 22,17; 2Chr 29,8; Jer 22,8; Kla 2,15.17"] },
      { number: 9, text: "Dann wird man sagen: Weil sie den HERRN, ihren Gott, der ihre Väter aus dem Land Ägypten herausgeführt hat, verlassen und sich an andere Götter gehalten haben und sich vor ihnen niedergeworfen und ihnen gedient haben, darum hat der HERR all dieses Unheil über sie gebracht*.", footnotes: ["℘ 5Mo 29,23-28; 2Kö 22,17; 2Chr 29,8; Jer 22,8; Kla 2,15.17"] },
      { number: 10, text: "*Und es geschah am Ende der zwanzig Jahre, in denen Salomo die beiden Häuser, das Haus des HERRN und das Haus des Königs, gebaut hatte* —", heading: "Salomos Gabe an Hiram — Salomos Zwangsarbeiter, Festungsbauten, Vorratsstädte und Schifffahrt", footnotes: ["℘ 2Chr 8", "℘ V. 1; Kap. 7,1; Esr 5,11"] },
      { number: 11, text: "Hiram, der König von Tyrus, hatte Salomo unterstützt* mit Zedernholz, mit Wacholderholz und mit Gold ganz nach seinem Wunsch —, damals gab der König Salomo dem Hiram zwanzig Städte im Land Galiläa.", footnotes: ["℘ Kap. 5,22-24"] },
      { number: 12, text: "Und Hiram zog von Tyrus aus, um <sich> die Städte anzusehen, die Salomo ihm gegeben hatte; und sie waren nicht recht in seinen Augen." },
      { number: 13, text: "Und er sagte: Was sind das für Städte, die du mir gegeben hast, mein Bruder! Und er nannte sie »Land Kabul*«<, und so heißen sie> bis zum heutigen Tag.", footnotes: ["Das kann heißen: Land wie nichts, o. das gefesselte Land"] },
      { number: 14, text: "Hiram hatte nämlich dem König 120 Talente Gold gesandt." },
      { number: 15, text: "Und dies ist die Sache <mit> den Zwangsarbeitern, die der König Salomo aushob*, um das Haus des HERRN zu bauen sowie sein <eigenes> Haus und den Millo* und die Mauer von Jerusalem* und Hazor* und Megiddo und Geser —", footnotes: ["℘ Kap. 5,27.28", "Der Millo diente zur Befestigung der Stadt.\n℘ Kap. 11,27; 2Sam 5,9", "℘ Kap. 3,1; Jos 11,1", "℘ Jos 16,10"] },
      { number: 16, text: "der Pharao, der König von Ägypten, war heraufgezogen und hatte Geser eingenommen und es mit Feuer verbrannt und die Kanaaniter, die in der Stadt wohnten*, erschlagen* und hatte es seiner Tochter, der Frau des Salomo*, als Mitgift gegeben!", footnotes: ["w. den Kanaaniter, der . . . wohnte", "℘ Jos 16,10", "℘ Kap. 3,1"] },
      { number: 17, text: "Und Salomo baute Geser und das untere Bet-Horon*", footnotes: ["℘ Jos 16,3"] },
      { number: 18, text: "und Baalat* und Tamar* in der Wüste im Land <Juda>", footnotes: ["℘ Jos 19,44", "so mit der Schreibform des Mas. T.; mit der Leseform und 2Chr 8,4: Tadmor\n℘ Hes 47,19"] },
      { number: 19, text: "und alle Vorratsstädte, die Salomo hatte, und die Wagenstädte und die Pferdestädte und <alles,> was Salomo sonst noch zu bauen wünschte* in Jerusalem und auf dem Libanon und im ganzen Land seiner Herrschaft* —:", footnotes: ["w. und die Lust Salomos, die er zu bauen Lust hatte", "℘ Kap. 5,6"] },
      { number: 20, text: "alles Volk, das übrig geblieben war von den Amoritern, den Hetitern, den Perisitern, den Hewitern und den Jebusitern, die nicht von den Söhnen Israel waren*,", footnotes: ["℘ Ri 3,3-5"] },
      { number: 21, text: "deren Söhne, die nach ihnen im Land übrig geblieben waren, weil die Söhne Israel an ihnen den Bann nicht hatten vollstrecken können*, die hob Salomo als Sklaven zur Zwangsarbeit <für seine Bauten> aus; <und so ist es> bis zum heutigen Tag*.", footnotes: ["℘ Ri 1,27-36", "℘ Jos 16,10"] },
      { number: 22, text: "Aber von den Söhnen Israel machte Salomo keine Sklaven*, sondern sie waren Kriegsleute und seine Knechte und seine Obersten und seine Wagenkämpfer* und Oberste über seine Streitwagen und seine Pferde.", footnotes: ["℘ 3Mo 25,39", "w. seine Dritten; d. i. der dritte Mann auf einem Kriegswagen"] },
      { number: 23, text: "Dies sind die Obersten der Vögte, die über die Bauarbeiten* Salomos <gesetzt> waren: 550, die über das Volk herrschten, das mit der Arbeit beschäftigt war.", footnotes: ["w. über die Arbeit"] },
      { number: 24, text: "Sobald die Tochter des Pharao aus der Stadt Davids in ihr Haus hinaufgezogen war*, das er für sie erbaut hatte, da baute er den Millo*.", footnotes: ["℘ Kap. 7,8", "Der Millo diente zur Befestigung der Stadt.\n℘ Kap. 11,27; 2Sam 5,9"] },
      { number: 25, text: "Und Salomo opferte dreimal im Jahr* Brandopfer und Heilsopfer* auf dem Altar, den er für den HERRN gebaut hatte, und brachte Rauchopfer auf ihm dar, der vor dem HERRN <stand>. Und er vollendete das Haus*.", footnotes: ["℘ 2Mo 23,14", "o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer", "o. So erfüllte er <den Zweck> des Hauses\n℘ Kap. 6,9.14"] },
      { number: 26, text: "Und der König Salomo baute eine Flotte in Ezjon-Geber*, das bei Elat* am Ufer des Schilfmeeres im Land Edom <liegt>.", footnotes: ["℘ Kap. 22,49; 4Mo 33,35", "℘ 2Kö 14,22"] },
      { number: 27, text: "Und Hiram schickte auf der Flotte seine Knechte <mit>, seekundige Schiffsleute<, die> mit den Knechten Salomos <fuhren>*.", footnotes: ["℘ Kap. 10,11"] },
      { number: 28, text: "Und sie gelangten nach Ofir* und holten von dort Gold*, 420 Talente, und brachten <es> zum König Salomo.", footnotes: ["℘ 1Mo 10,29; 1Chr 29,4", "℘ Kap. 10,14; 22,49; Hi 22,24; Ps 45,10; Pred 2,8"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "*Und die Königin von Saba* hörte von Salomos Ruf <und von dem Haus, das er gebaut hatte> für den Namen des HERRN. Da kam sie, um ihn mit Rätsel<frage>n zu prüfen*.", heading: "Die Königin von Saba bei Salomo", footnotes: ["℘ 2Chr 9,1-12", "℘ Hi 6,19", "℘ V. 24; Kap. 5,14; Ri 14,12; Mt 12,42"] },
      { number: 2, text: "Und sie kam nach Jerusalem mit einem sehr zahlreichen Gefolge*, mit Kamelen, die Balsamöle und Gold trugen in sehr großer Menge* und Edelsteine. Und sie kam zu Salomo und redete zu ihm alles, was in ihrem Herzen war.", footnotes: ["o. mit sehr reichen Schätzen", "℘ Ps 72,10.15; Hes 27,22"] },
      { number: 3, text: "Und Salomo beantwortete ihr all ihre Fragen*. Nichts war vor dem König verborgen, das er ihr nicht hätte beantworten können*.", footnotes: ["w. Und Salomo teilte ihr alle ihre Worte mit", "w. das er ihr nicht mitteilte\n℘ Kap. 3,12"] },
      { number: 4, text: "Und als die Königin von Saba all die Weisheit Salomos sah und das Haus, das er gebaut hatte," },
      { number: 5, text: "und die Speise <auf> seiner Tafel und die Sitzordnung* seiner Knechte und die Aufwartung seiner Diener und ihre Kleidung und seine Getränke* und sein Brandopfer, das er im Haus des HERRN opferte, da geriet sie vor Staunen außer sich*", footnotes: ["w. das Sitzen, o. den Sitzplatz", "o. seine Mundschenken", "w. da hatte sie keinen Atem mehr"] },
      { number: 6, text: "und sagte zum König: Das Wort ist Wahrheit gewesen, das ich in meinem Land über deine Taten* und über deine Weisheit gehört habe!", footnotes: ["o. Sachen; o. Worte"] },
      { number: 7, text: "Ich habe den Worten nicht geglaubt, bis ich gekommen bin und meine Augen es gesehen haben*. Doch siehe, nicht die Hälfte ist mir berichtet worden! Du hast an Weisheit und Gütern die Kunde übertroffen, die ich gehört habe.", footnotes: ["℘ Ps 48,9"] },
      { number: 8, text: "Glücklich sind deine Männer*, glücklich diese deine Knechte, die ständig vor dir stehen, die deine Weisheit hören*!", footnotes: ["LXX, die alte lat. Üs. und die syr. Üs.: deine Frauen", "℘ Kap. 12,6; Spr 8,34; Mt 13,16.17"] },
      { number: 9, text: "Gepriesen sei der HERR, dein Gott, der Gefallen an dir gehabt hat, dich auf den Thron Israels zu setzen!* Weil der HERR Israel ewig liebt*, hat er dich als König eingesetzt, damit du Recht und Gerechtigkeit übst*.", footnotes: ["℘ Kap. 5,21", "℘ 5Mo 7,8; Jer 31,3; Mal 1,2", "℘ Kap. 3,28; 2Sam 5,12; 8,15; Ps 72,2; Jes 9,6"] },
      { number: 10, text: "Und sie gab dem König 120 Talente Gold und Balsamöle in sehr großer Menge und Edelsteine. Nie wieder kam so viel Balsamöl <ins Land> wie dieses, das die Königin von Saba dem König Salomo gab. —" },
      { number: 11, text: "Auch die Flotte Hirams, die Gold aus Ofir holte*, brachte aus Ofir Almuggimhölzer* in sehr großer Menge und Edelsteine.", footnotes: ["℘ Kap. 9,27.28", "℘ 2Chr 2,7"] },
      { number: 12, text: "Und der König machte von den Almuggimhölzern ein Geländer* für das Haus des HERRN und für das Haus des Königs und Zithern und Harfen* für die Sänger. Nie <mehr> kam so <viel> Almuggimholz <ins Land>, noch wurde <jemals wieder so viel> gesehen bis zum heutigen Tag. —", footnotes: ["In 2Chr 9,11 steht stattdessen: Treppen. — Die Bedeutung des hebr. Wortes ist ungewiss.", "℘ 1Chr 25,1.6"] },
      { number: 13, text: "Der König Salomo aber gab der Königin von Saba alles, was sie sich wünschte*, was sie erbeten hatte, abgesehen von dem, was er ihr <schon> gegeben hatte nach der Freigebigkeit* des Königs Salomo*. Und sie wandte sich und zog in ihr Land, sie und ihre Knechte.", footnotes: ["w. jeden Wunsch von ihr", "w. dem Vermögen, o. der Hand", "℘ Eph 3,20"] },
      { number: 14, text: "*Und das Gewicht des Goldes, das bei Salomo in einem einzigen Jahr einging, betrug 666 Talente Gold*", heading: "Salomos Reichtum", footnotes: ["℘ V. 14-29: 2Chr 9,13-28", "℘ Kap. 9,28"] },
      { number: 15, text: "außer dem, was von den Handelsleuten und dem Gewinn* der Händler und von allen Königen Arabiens* und den Statthaltern des Landes <einging>.", footnotes: ["so mit anderer Vokalisierung — Das Wort im Mas. T. findet sich nur hier und wird gewöhnlich mit »Handel« übersetzt.", "So lesen 2 griech., die syr. und lat. Üs.; Mas. T.: von allen Königen des <Völker>gemischs\n℘ Jer 25,24"] },
      { number: 16, text: "Und der König Salomo machte zweihundert Langschilde* aus legiertem Gold* — <mit> sechshundert <Schekel> Gold überzog er jeden Langschild —", footnotes: ["℘ Kap. 14,26; 2Sam 8,7", "o. aus gehämmertem Gold"] },
      { number: 17, text: "und dreihundert Kleinschilde aus legiertem Gold*, <mit> drei Minen Gold überzog er jeden Kleinschild. Und der König gab sie in das Libanonwaldhaus*.", footnotes: ["o. aus gehämmertem Gold", "℘ Kap. 7,2; Jes 22,8"] },
      { number: 18, text: "Und der König machte einen großen Thron aus Elfenbein und überzog ihn mit reinem Gold." },
      { number: 19, text: "Sechs Stufen hatte der Thron, und einen runden Kopf* hatte der Thron auf seiner Rückseite; und Armlehnen waren auf dieser und auf jener Seite am Sitzplatz, und zwei Löwen standen neben den Armlehnen;", footnotes: ["LXX: und Stierköpfe"] },
      { number: 20, text: "und zwölf Löwen standen da auf den sechs Stufen, auf dieser und auf jener Seite. Niemals ist so <etwas> gemacht worden für irgendwelche <anderen> Königreiche." },
      { number: 21, text: "Und alle Trinkgefäße des Königs Salomo waren aus Gold*, und alle Geräte des Libanonwaldhauses waren aus gediegenem Gold. Silber galt in den Tagen Salomos überhaupt nichts*.", footnotes: ["℘ Est 1,7", "℘ 5Mo 17,17"] },
      { number: 22, text: "Denn der König hatte Tarsisschiffe auf dem Meer*<, die fuhren> mit den Schiffen Hirams. Einmal in drei Jahren kamen die Tarsisschiffe, beladen mit Gold und Silber, Elfenbein und Affen und Pavianen*.", footnotes: ["℘ Kap. 22,49; 2Chr 20,36; Hes 27,12.15", "o. Pfauen"] },
      { number: 23, text: "So war der König Salomo größer als alle Könige der Erde an Reichtum und an Weisheit.*", footnotes: ["℘ Kap. 3,12.13; Pred 2,9"] },
      { number: 24, text: "Und die ganze Erde suchte das Angesicht Salomos, um seine Weisheit zu hören*, die Gott in sein Herz gegeben hatte*.", footnotes: ["℘ V. 1", "℘ Kap. 3,9-12; 2Chr 1,11.12; Spr 2,6"] },
      { number: 25, text: "Und sie brachten jeder sein Geschenk: Geräte aus Silber und Geräte aus Gold und Gewänder und Waffen und Balsamöle, Pferde und Maultiere; so geschah es Jahr für Jahr*.", footnotes: ["w. die Sache des Jahres geschah in <ihrem> Jahr\n℘ Ps 72,10"] },
      { number: 26, text: "*Und Salomo brachte Streitwagen und Pferde* zusammen, und er hatte 1 400 Streitwagen und 12 000 Pferde; und er legte sie* in die Wagenstädte und zu dem König nach Jerusalem.", footnotes: ["℘ V. 26-29: 2Chr 1,14-17", "℘ Kap. 5,6", "so mit LXX, der syr. und aram. Üs.; Mas. T.: er führte sie"] },
      { number: 27, text: "Und der König machte das Silber in Jerusalem <an Menge> den Steinen gleich, und die Zedern machte er an Menge den Maulbeerfeigenbäumen gleich, die in der Niederung* <wachsen>.", footnotes: ["hebr. Schefelah; d. i. der Küstenstreifen zwischen Jafo und Gaza"] },
      { number: 28, text: "Und die Ausfuhr der Pferde für Salomo <erfolgte> aus Ägypten *und aus Koe. Die Aufkäufer des Königs holten <sie> aus Koe* gegen Bezahlung.", footnotes: ["T.; Koe ist ein Ort in Ägypten. Andere ändern in Kuwe, das in Kleinasien liegt. Mas. T.: und eine Ansammlung der Aufkäufer des Königs holte eine Ansammlung von <Pferden>", "T.; Koe ist ein Ort in Ägypten. Andere ändern in Kuwe, das in Kleinasien liegt. Mas. T.: und eine Ansammlung der Aufkäufer des Königs holte eine Ansammlung von <Pferden>"] },
      { number: 29, text: "Bei der Ausfuhr aus Ägypten wurde ein Wagen für 600 <Schekel> Silber gehandelt* und ein Pferd für 150. Und so führte man <sie> für alle Könige der Hetiter* und für die Könige von Aram durch die Aufkäufer* <wieder> aus.", footnotes: ["w. Und ein Wagen kam herauf und zog aus Ägypten für 600 <Schekel> Silber", "℘ Jos 1,4; 2Kö 7,6", "w. durch ihre Hand"] },
    ]},
    { number: 11, verses: [
      { number: 1, text: "Der König Salomo aber liebte viele ausländische Frauen, und zwar neben der Tochter des Pharao* moabitische, ammonitische*, edomitische, sidonische, hetitische*,", heading: "Salomos Vielweiberei und Götzendienst", footnotes: ["℘ Kap. 3,1", "℘ Kap. 14,21", "℘ Esr 9,1.2"] },
      { number: 2, text: "von den Nationen, von denen der HERR zu den Söhnen Israel gesagt hatte: Ihr sollt nicht zu ihnen eingehen, und sie sollen nicht zu euch eingehen*; fürwahr, sie würden euer Herz ihren Göttern zuneigen*! An diesen hing Salomo mit Liebe.", footnotes: ["o. Ihr sollt euch nicht mit ihnen einlassen, und sie sollen sich nicht mit euch einlassen", "w. sie würden euer Herz neigen hinter ihren Göttern her\n℘ 1Kor 15,33; Offb 2,4"] },
      { number: 3, text: "Und er hatte siebenhundert vornehme Frauen und dreihundert Nebenfrauen*; und seine Frauen neigten sein Herz*.", footnotes: ["℘ Pred 2,8", "℘ 5Mo 17,17; Ri 3,6.7"] },
      { number: 4, text: "Und es geschah zur Zeit, als Salomo alt geworden war, da neigten seine Frauen sein Herz anderen Göttern zu*. So war sein Herz nicht ungeteilt mit dem HERRN, seinem Gott, wie das Herz seines Vaters David*.", footnotes: ["w. sein Herz anderen Göttern hinterher\n℘ 1Kor 15,33; Offb 2,4", "℘ V. 33.38; Kap. 3,3"] },
      { number: 5, text: "Und Salomo folgte der Astarte nach, der Göttin der Sidonier, und dem Milkom, dem Scheusal der Ammoniter*.", footnotes: ["℘ Ri 2,13.14; 10,6"] },
      { number: 6, text: "Und Salomo tat, was böse war in den Augen des HERRN, und er folgte dem HERRN nicht so treu nach wie* sein Vater David*.", footnotes: ["w. und er erfüllte nicht <die Nachfolge> hinter dem HERRN her wie", "℘ V. 33.38; Kap. 3,3"] },
      { number: 7, text: "Damals baute Salomo eine Höhe für Kemosch*, das Scheusal der Moabiter, auf dem Berg, der Jerusalem gegenüber<liegt>, und für Moloch*, das Scheusal der Söhne Ammon.", footnotes: ["℘ Ri 11,24; 2Kö 23,13", "℘ 3Mo 20,2; Jer 32,35"] },
      { number: 8, text: "Ebenso machte er <es> für all seine ausländischen Frauen, die ihren Göttern Rauchopfer und Schlachtopfer darbrachten*.", footnotes: ["℘ Kap. 15,12; Neh 13,26"] },
      { number: 9, text: "Da wurde der HERR zornig über Salomo, weil er sein Herz von dem HERRN, dem Gott Israels, abgewandt hatte*, der ihm zweimal erschienen war*", footnotes: ["℘ 1Sam 15,11", "℘ Kap. 3,5; 9,2"] },
      { number: 10, text: "und ihm in dieser Sache geboten hatte, nicht anderen Göttern nachzufolgen*. Aber er hatte nicht beachtet, was der HERR <ihm> geboten hatte.", footnotes: ["℘ Kap. 9,6"] },
      { number: 11, text: "Da sprach der HERR zu Salomo: Weil dir dies bewusst war* und du meinen Bund nicht beachtet hast und meine Ordnungen, die ich dir geboten habe, werde ich das Königreich ganz bestimmt von dir wegreißen und es einem Knecht von dir geben*.", footnotes: ["w. Weil dies bei dir war", "℘ V. 31; 1Sam 15,28"] },
      { number: 12, text: "Doch in deinen Tagen will ich es nicht tun* deines Vaters David wegen*, <sondern> aus der Hand deines Sohnes werde ich es reißen.", footnotes: ["℘ Kap. 21,29; 2Kö 20,19", "℘ V. 32.34; 2Kö 8,19"] },
      { number: 13, text: "Doch will ich nicht das ganze Königreich wegreißen: Einen Stamm will ich deinem Sohn geben* wegen meines Knechtes David* und Jerusalems wegen, das ich erwählt habe*.", footnotes: ["℘ Kap. 12,19.20; 2Sam 7,15", "℘ V. 32.34; 2Kö 8,19", "℘ Ps 132,13"] },
      { number: 14, text: "Und der HERR ließ Salomo einen Widersacher* erstehen, den Edomiter Hadad; der war vom königlichen Geschlecht* in Edom.", heading: "Salomos Widersacher und Tod", footnotes: ["hebr. satan", "w. Samen"] },
      { number: 15, text: "Es geschah nämlich, als David Edom geschlagen hatte*, als der Heeroberste Joab hinaufgezogen war, um die Erschlagenen <Israels> zu begraben, und er alles Männliche in Edom umbrachte* —", footnotes: ["so mit LXX und der syr. Üs.; Mas. T.: als David mit Edom <im Kampf> war\n℘ 2Sam 8,14", "℘ 4Mo 24,18; 5Mo 20,13"] },
      { number: 16, text: "denn sechs Monate waren Joab und ganz Israel dort geblieben, bis er alles Männliche in Edom ausgerottet hatte —," },
      { number: 17, text: "da floh Hadad, er und <einige> edomitische Männer von den Knechten seines Vaters mit ihm, um nach Ägypten zu <ent>kommen; Hadad aber war <damals> ein sehr junger Mann." },
      { number: 18, text: "Und sie machten sich aus Midian* auf und kamen nach Paran* und nahmen Männer aus Paran mit sich und kamen nach Ägypten zum Pharao, dem König von Ägypten. Und er gab ihm ein Haus und wies ihm <sein> Brot zu und gab ihm Land.", footnotes: ["℘ 2Mo 2,15", "℘ 4Mo 10,12"] },
      { number: 19, text: "Und Hadad fand reichlich Gunst in den Augen des Pharao, und der gab ihm die Schwester seiner Frau, die Schwester der Königin Tachpenes, zur Frau." },
      { number: 20, text: "Und die Schwester der Tachpenes gebar ihm Genubat, seinen Sohn; und Tachpenes entwöhnte ihn im Haus des Pharao. Und Genubat blieb im Haus des Pharao unter den Söhnen des Pharao." },
      { number: 21, text: "Als aber Hadad in Ägypten hörte, dass David sich zu seinen Vätern gelegt hatte und dass der Heeroberste Joab tot war*, da sagte Hadad zum Pharao: Entlass mich, dass ich in mein Land ziehe!", footnotes: ["℘ Kap. 2,10.34"] },
      { number: 22, text: "Und der Pharao sagte zu ihm: Was fehlt dir bei mir? Nun aber suchst du in dein Land zu ziehen? Er jedoch sagte: Nicht doch — aber entlass mich, bitte*!", footnotes: ["℘ Spr 27,8"] },
      { number: 23, text: "Und Gott ließ Salomo* <noch> einen Widersacher* erstehen, <nämlich> Reson, den Sohn Eljadas, der von seinem Herrn Hadad-Eser*, dem König von Zoba, geflohen war.", footnotes: ["w. ihm", "hebr. satan", "℘ 2Sam 8,8"] },
      { number: 24, text: "Der sammelte Männer um sich und wurde Oberster einer Räuberschar, *als David die Aramäer umbrachte*. Und sie zogen nach Damaskus* und ließen sich darin nieder, und sie herrschten in Damaskus wie Könige.", footnotes: ["T.; Mas. T.: als David sie umbrachte. — Dieses Stück fehlt in LXX.", "T.; Mas. T.: als David sie umbrachte. — Dieses Stück fehlt in LXX.\n℘ 2Sam 8,3.4; 10,6.8", "℘ Kap. 15,18"] },
      { number: 25, text: "Und er war für Israel ein Widersacher* alle Tage Salomos, und <zwar zusätzlich> zu dem Unheil, das Hadad <bedeutete>; und er* verabscheute Israel; und er wurde König über Aram.", footnotes: ["hebr. satan", "d. i. Reson"] },
      { number: 26, text: "Und Jerobeam, der Sohn des Nebat*, ein Efratiter* von Zereda — und der Name seiner Mutter, einer Witwe, war Zerua —, ein Beamter* Salomos, auch er erhob die Hand gegen den König*.", footnotes: ["℘ Kap. 12,2; 2Chr 9,29", "d. i. eine Kurzform für Ephraimiter\n℘ Ri 12,5", "w. Knecht", "℘ 2Chr 13,6"] },
      { number: 27, text: "Und dies war der Anlass <dafür>, dass er die Hand gegen den König erhob: Salomo baute den Millo* <und> schloss die Lücke <in> der Stadt seines Vaters David.", footnotes: ["℘ Kap. 9,15.24"] },
      { number: 28, text: "Der Mann Jerobeam aber war ein vermögender* Mann; und als Salomo sah, dass der junge Mann <gute> Arbeit leistete, da bestellte er ihn zur Aufsicht über alle Last<arbeiter> des Hauses Josef.", footnotes: ["o. angesehener; o. tüchtiger"] },
      { number: 29, text: "Und es geschah in jener Zeit, als Jerobeam <einmal> aus Jerusalem hinausging, da traf ihn der Prophet Ahija*, der Siloniter, auf dem Weg. Der hatte sich mit einem neuen Mantel bekleidet*. Als sie nun beide allein auf dem <freien> Feld waren,", footnotes: ["℘ Kap. 12,2; 2Chr 9,29", "w. bedeckt"] },
      { number: 30, text: "da fasste Ahija den neuen Mantel, den er anhatte, und zerriss ihn in zwölf Stücke," },
      { number: 31, text: "und er sagte zu Jerobeam: Nimm dir zehn Stücke! Denn so spricht der HERR, der Gott Israels: Siehe, ich will das Königreich aus der Hand Salomos reißen und will dir die zehn Stämme geben*. —", footnotes: ["℘ V. 11; Kap. 12,15; 14,2; 2Chr 10,15"] },
      { number: 32, text: "Aber der eine Stamm soll ihm <weiterhin> gehören wegen meines Knechtes David und Jerusalems wegen, der Stadt, die ich erwählt habe aus allen Stämmen Israels*. —", footnotes: ["℘ V. 13"] },
      { number: 33, text: "Denn sie haben mich verlassen und haben sich niedergeworfen vor Astarte, der Göttin der Sidonier, vor Kemosch, dem Gott der Moabiter, und vor Milkom, dem Gott der Söhne Ammon, und sind nicht auf meinen Wegen gegangen, dass sie getan hätten, was recht ist in meinen Augen. Und meine Ordnungen und meine Rechtsbestimmungen <hat er nicht bewahrt>* wie sein Vater David.*", footnotes: ["℘ 2Kö 21,22", "℘ V. 4-7; Jer 2,11-13"] },
      { number: 34, text: "Doch will ich nicht aus seiner Hand das ganze Königreich nehmen, sondern will ihn zum Fürsten einsetzen alle Tage seines Lebens wegen meines Knechtes David, den ich erwählt habe, der meine Gebote und meine Ordnungen bewahrt hat*.", footnotes: ["℘ V. 12; Kap. 3,14"] },
      { number: 35, text: "Aber aus der Hand seines Sohnes will ich das Königreich nehmen* und es dir geben, die zehn Stämme*;", footnotes: ["℘ Kap. 12,16.17", "℘ Kap. 12,20; 14,7"] },
      { number: 36, text: "und seinem Sohn will ich einen Stamm geben, damit mein Knecht David alle Tage eine Leuchte vor mir hat in Jerusalem*, der Stadt, die ich mir erwählt habe, um meinen Namen dort niederzulegen*.", footnotes: ["℘ Kap. 15,4; 2Sam 21,17; 2Kö 8,19; 2Chr 21,7", "℘ Kap. 2,4; 8,29; 2Chr 12,13"] },
      { number: 37, text: "Dich aber will ich nehmen, dass du als König über alles herrschst, was deine Seele begehrt, und du sollst König über Israel werden*.", footnotes: ["℘ Kap. 12,20; 14,7"] },
      { number: 38, text: "Und es wird geschehen, wenn du auf alles, was ich dir gebiete, hörst und auf meinen Wegen gehst und tust, was recht ist in meinen Augen, indem du meine Ordnungen und meine Gebote bewahrst, wie mein Knecht David getan hat*, dann werde ich mit dir sein und dir ein beständiges Haus bauen*, wie ich es für David gebaut habe. Und ich werde dir Israel geben", footnotes: ["℘ V. 4.6", "℘ 2Sam 7,11.27"] },
      { number: 39, text: "und werde die Nachkommenschaft Davids wegen dieser <Sache> demütigen, doch nicht für immer*.", footnotes: ["℘ Ps 89,34; Kla 3,31"] },
      { number: 40, text: "Und Salomo suchte Jerobeam zu töten*. Jerobeam aber machte sich auf und floh nach Ägypten* zu Schischak*, dem König von Ägypten; und er war in Ägypten bis zum Tod Salomos.", footnotes: ["℘ 1Sam 20,33", "℘ Kap. 12,2; 2Chr 10,2; Mt 2,13", "℘ Kap. 14,25"] },
      { number: 41, text: "*Die übrige Geschichte* Salomos und alles, was er getan hat, und seine Weisheit, ist die nicht geschrieben in dem Buch der Geschichte* Salomos?", footnotes: ["℘ V. 41-43: 2Chr 9,29-31", "w. Der Rest der Begebenheiten", "w. der Begebenheiten"] },
      { number: 42, text: "Und die Tage, die Salomo in Jerusalem über ganz Israel als König herrschte*, <betrugen> vierzig Jahre.", footnotes: ["℘ Pred 1,1"] },
      { number: 43, text: "Und Salomo legte sich zu seinen Vätern und wurde in der Stadt seines Vaters David begraben*. Und sein Sohn Rehabeam* wurde an seiner Stelle König.*", footnotes: ["℘ Kap. 2,10.11; 22,40", "℘ 1Chr 3,10; Mt 1,7", "℘ Kap. 14,21; Pred 2,19"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "*Und Rehabeam ging nach Sichem*; denn ganz Israel war nach Sichem gekommen, um ihn zum König zu machen.", heading: "Rehabeams Torheit — Teilung des Reiches — Jerobeam", footnotes: ["℘ V. 1-24: 2Chr 10; 11,1-4", "℘ V. 25; Jos 20,7"] },
      { number: 2, text: "Und es geschah, als Jerobeam, der Sohn des Nebat, <das> hörte — er war aber noch in Ägypten*, wohin er vor dem König Salomo geflohen war —, da kehrte Jerobeam aus Ägypten zurück*.", footnotes: ["℘ Kap. 11,26.40", "so mit LXX, Vulg. und der syr. Üs.; Mas. T.: da blieb Jerobeam in Ägypten"] },
      { number: 3, text: "Und sie sandten hin und ließen ihn rufen. Da kamen Jerobeam und die ganze Versammlung Israels. Und sie redeten zu Rehabeam und sagten:" },
      { number: 4, text: "Dein Vater hat unser Joch hart gemacht*. Du aber erleichtere nun den harten Dienst deines Vaters und sein schweres Joch, das er auf uns gelegt hat! Dann wollen wir dir dienen*.", footnotes: ["℘ Kap. 5,27.28; Mt 20,25", "℘ 1Sam 8,17"] },
      { number: 5, text: "Er sagte zu ihnen: Geht hin, noch drei Tage, dann kommt wieder zu mir! Und das Volk ging hin." },
      { number: 6, text: "Und der König Rehabeam beriet sich mit den Alten, die vor seinem Vater Salomo gestanden hatten, als er <noch> am Leben war*, und sagte: Wie ratet ihr, diesem Volk Antwort zu geben?", footnotes: ["℘ Kap. 10,8; Hi 12,12"] },
      { number: 7, text: "Und sie redeten zu ihm und sagten: Wenn du heute diesem Volk zum Knecht wirst und ihnen dienst und sie erhörst und gute Worte zu ihnen redest*, dann werden sie alle Tage deine Knechte sein.", footnotes: ["℘ Spr 15,1"] },
      { number: 8, text: "Doch er verwarf den Rat der Alten, den sie ihm geraten hatten, und beriet sich mit den Jüngeren*, die mit ihm groß geworden waren <und> die vor ihm standen.", footnotes: ["w. mit den Kindern"] },
      { number: 9, text: "Und er sagte zu ihnen: Was ratet ihr, dass wir diesem Volk zur Antwort geben, das zu mir geredet und gesagt hat: Erleichtere das Joch, das dein Vater auf uns gelegt hat?" },
      { number: 10, text: "Und die Jüngeren*, die mit ihm groß geworden waren, redeten zu ihm und sagten: So sollst du zu diesem Volk sprechen, das zu dir geredet und gesagt hat: »Dein Vater hat unser Joch schwer gemacht, du aber erleichtere es uns« — so sollst du zu ihnen reden: Mein kleiner <Finger> ist dicker als die Hüften meines Vaters.", footnotes: ["w. Kinder"] },
      { number: 11, text: "Nun denn, mein Vater hat euch ein schweres Joch aufgeladen, ich aber will euer Joch noch schwerer machen*. Mein Vater hat euch mit Peitschen gezüchtigt, ich aber will euch mit Skorpionen* züchtigen*.", footnotes: ["w. ich will auf euer Joch hinzufügen", "o. Geißeln <mit Widerhaken>", "℘ Pred 10,16"] },
      { number: 12, text: "Und Jerobeam und das ganze Volk kamen am dritten Tag zu Rehabeam, wie der König geredet hatte, als er sagte: Kommt am dritten Tag wieder zu mir!" },
      { number: 13, text: "Und der König antwortete dem Volk hart und verwarf den Rat der Alten, den sie ihm geraten hatten;" },
      { number: 14, text: "und er redete zu ihnen nach dem Rat der Jüngeren*: Mein Vater hat euer Joch schwer gemacht, ich aber will euer Joch noch schwerer machen*. Mein Vater hat euch mit Peitschen gezüchtigt, ich aber will euch mit Skorpionen* züchtigen.", footnotes: ["w. Kinder\n℘ Spr 5,13", "w. ich will auf euer Joch hinzufügen", "o. Geißeln <mit Widerhaken>"] },
      { number: 15, text: "So hörte der König nicht auf das Volk; denn es war eine Wendung vonseiten des HERRN*, damit er sein Wort aufrechthielt, das der HERR durch Ahija, den Siloniter, zu Jerobeam, dem Sohn des Nebat, geredet hatte*.", footnotes: ["℘ 1Mo 24,50; Ri 14,4; 2Chr 22,7", "℘ Kap. 11,31"] },
      { number: 16, text: "Und als ganz Israel sah, dass der König nicht auf sie hörte, da gab das Volk dem König <zur> Antwort: Was für einen Anteil haben wir an David? Wir haben kein Erbteil am Sohn Isais! Zu deinen Zelten, Israel!* Nun sieh nach deinem Haus, David! — Und Israel ging zu seinen Zelten.", footnotes: ["℘ Ri 9,28; 2Sam 20,1; Spr 15,1"] },
      { number: 17, text: "Die Söhne Israel aber, die in den Städten Judas wohnten, über sie wurde Rehabeam König*.", footnotes: ["℘ Kap. 11,13.35.36; 14,21"] },
      { number: 18, text: "Und der König Rehabeam schickte Adoram*, den <Aufseher> über die Zwangsarbeit, aus. Aber ganz Israel steinigte ihn, so dass er starb. Der König Rehabeam aber bestieg eilends den Wagen*, um nach Jerusalem zu fliehen.", footnotes: ["℘ Kap. 4,6", "o. Dem König Rehabeam aber gelang es <gerade noch>, den Wagen zu besteigen"] },
      { number: 19, text: "So brach Israel mit dem Haus Davids bis zum heutigen Tag.*", footnotes: ["℘ 2Kö 17,21; Jes 7,17; Hes 37,16"] },
      { number: 20, text: "Und es geschah, als ganz Israel hörte, dass Jerobeam zurückgekehrt war, da sandten sie hin und ließen ihn zur Gemeinde rufen und machten ihn zum König über ganz Israel*. Niemand folgte dem Haus David außer dem Stamm Juda allein*.", footnotes: ["℘ Kap. 11,37", "℘ Kap. 11,13; 2Sam 20,2"] },
      { number: 21, text: "Und Rehabeam kam nach Jerusalem und versammelte das ganze Haus Juda und den Stamm Benjamin, 180 000 auserlesene Krieger, um mit dem Haus Israel zu kämpfen und <so> das Königtum an Rehabeam, den Sohn Salomos, zurückzubringen." },
      { number: 22, text: "Da geschah das Wort Gottes zu Schemaja, dem Mann Gottes*:", footnotes: ["℘ Kap. 17,24; 2Chr 12,5"] },
      { number: 23, text: "Sage zu Rehabeam, dem Sohn Salomos, dem König von Juda, und zum ganzen Haus Juda und Benjamin und zum Rest des Volkes:" },
      { number: 24, text: "So spricht der HERR: Ihr sollt nicht hinaufziehen und sollt nicht mit euren Brüdern, den Söhnen Israel, kämpfen*! Kehrt um, jeder in sein Haus! Denn von mir ist diese Sache ausgegangen*. Da hörten sie auf das Wort des HERRN und wandten sich — nach dem Wort des HERRN — zur Heimkehr*.", footnotes: ["℘ Kap. 14,30", "℘ 1Mo 24,50; Ri 14,4; 2Chr 22,7", "o. und kehrten zurück, um nach dem Wort des HERRN zu gehen o. um sich nach dem Wort des HERRN zu verhalten"] },
      { number: 25, text: "Und Jerobeam baute Sichem* auf dem Gebirge Ephraim aus und wohnte darin. Und von dort zog er fort und baute Pnuël* aus.", footnotes: ["℘ V. 1", "℘ 1Mo 32,31"] },
      { number: 26, text: "Und Jerobeam sprach in seinem Herzen*: Jetzt wird das Königtum an das Haus David zurückkommen.", heading: "Jerobeams Götzendienst", footnotes: ["℘ 1Sam 27,1; Spr 14,12"] },
      { number: 27, text: "Wenn dieses Volk hinaufzieht, um im Haus des HERRN in Jerusalem Schlachtopfer zuzubereiten*, dann wird sich das Herz dieses Volkes zu ihrem Herrn zurückwenden, zu Rehabeam, dem König von Juda. Mich aber werden sie erschlagen und sich zu Rehabeam, dem König von Juda, zurückwenden.", footnotes: ["℘ 5Mo 12,5.6"] },
      { number: 28, text: "So beschloss denn der König*, zwei goldene Kälber* anzufertigen*. Zum Volk* aber sagte er: Es ist zu viel für euch, nach Jerusalem hinaufzugehen. Siehe da, Israel, deine Götter, die dich aus dem Land Ägypten heraufgeführt haben!*", footnotes: ["℘ 1Sam 27,1; Spr 14,12", "Das Wort Kalb ist hier eine verächtliche Bezeichnung für ein Stierbild.", "℘ 2Mo 20,4.5; 2Kö 17,8.16; Hes 16,26; Hos 10,10", "w. Zu ihnen", "℘ 2Mo 32,4.8"] },
      { number: 29, text: "Und er stellte das eine in Bethel* auf, und das andere gab er nach Dan*.", footnotes: ["℘ Kap. 13,4; 1Mo 28,19; Jer 48,13; Hos 4,15", "℘ Ri 18,29; 2Kö 10,29; 2Chr 13,8; Am 8,14"] },
      { number: 30, text: "Diese Sache aber wurde zur Sünde*. Und das Volk zog vor dem einen her bis nach Dan.", footnotes: ["℘ Kap. 13,34; 14,16; 2Chr 17,4; Hos 10,8"] },
      { number: 31, text: "Auch baute er Höhenheiligtümer* und machte Priester aus dem gesamten Volk, die nicht von den Söhnen Levi waren*.", footnotes: ["w. Und er machte das Höhenhaus\n℘ Kap. 14,23", "℘ Kap. 13,33; 4Mo 3,10; 2Chr 11,14.15; Am 7,10"] },
      { number: 32, text: "Und Jerobeam machte ein Fest im achten Monat, am fünfzehnten Tag des Monats, wie das Fest, das in Juda <stattfand>*; und er stieg <selbst> auf den Altar*; so tat er es in Bethel, um den Kälbern zu opfern, die er gemacht hatte. Und er stellte in Bethel die Höhenpriester an*, die er gemacht hatte*.", footnotes: ["℘ 3Mo 23,34", "o. er opferte <selbst> auf dem Altar", "o. Und er ließ <dazu> in Bethel die Höhenpriester antreten", "℘ Ri 17,5"] },
      { number: 33, text: "Und er stieg <selbst> auf den Altar*, den er in Bethel gemacht hatte*, am fünfzehnten Tag im achten Monat, in dem Monat, den er aus seinem Herzen erdacht hatte; und er veranstaltete für die Söhne Israel ein Fest und stieg auf den Altar*, um Rauchopfer darzubringen.", footnotes: ["o. er opferte <selbst> auf dem Altar", "℘ Kap. 13,1; 2Kö 17,32", "℘ 2Kö 16,12"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "Und siehe, ein Mann Gottes* kam aus Juda auf das Wort des HERRN hin nach Bethel, als Jerobeam auf dem Altar stand, um Rauchopfer darzubringen*.", heading: "Weissagung gegen Jerobeam durch den Mann Gottes aus Juda — Ungehorsam und Tod des Propheten", footnotes: ["℘ 1Sam 2,27", "℘ Kap. 12,32.33; Am 7,13"] },
      { number: 2, text: "Und er rief gegen den Altar auf das Wort des HERRN hin und sagte: Altar, Altar, so spricht der HERR: Siehe, ein Sohn wird dem Haus David geboren werden, sein Name ist Josia. Der wird auf dir die Höhenpriester schlachten, die auf dir räuchern; und Menschengebeine wird man auf dir verbrennen*!", footnotes: ["℘ 2Kö 23,15-20; 2Chr 34,4.5"] },
      { number: 3, text: "Und er gab an jenem Tag ein Wunderzeichen* und sagte: Dies ist das Wunderzeichen* dafür, dass der HERR geredet hat: Siehe, der Altar wird zerbersten, und die Fettasche, die darauf ist, wird verschüttet werden.", footnotes: ["o. Wahrzeichen\n℘ Jes 7,11.14; Mt 12,38; Joh 2,11.18", "o. Wahrzeichen"] },
      { number: 4, text: "Und es geschah, als der König das Wort des Mannes Gottes hörte, das er gegen den Altar in Bethel* ausgerufen hatte, da streckte Jerobeam vom Altar herab seine Hand aus und sagte: Packt ihn!* Da verdorrte seine Hand, die er gegen ihn ausgestreckt hatte, und er konnte sie nicht wieder an sich ziehen*.", footnotes: ["℘ Kap. 12,29", "℘ Kap. 22,27; 2Chr 16,10; Jer 20,2", "℘ Ps 105,15"] },
      { number: 5, text: "Und der Altar zerbarst, und die Fettasche wurde vom Altar verschüttet nach dem Wunderzeichen*, das der Mann Gottes auf das Wort des HERRN hin gegeben hatte*.", footnotes: ["o. Wahrzeichen", "℘ Am 3,14"] },
      { number: 6, text: "Da hob der König an und sagte zu dem Mann Gottes: Besänftige doch das Angesicht des HERRN, deines Gottes, und bete für mich, dass ich meine Hand wieder an mich ziehen kann*! Und der Mann Gottes besänftigte das Angesicht des HERRN*, und die Hand des Königs wurde ihm wiedergegeben und wurde wie vorher*.", footnotes: ["w. dass meine Hand zu mir zurückkehrt", "℘ 4Mo 12,13", "℘ 2Mo 8,4-9; Lk 6,10; Jak 5,16"] },
      { number: 7, text: "Und der König redete zu dem Mann Gottes: Komm mit mir ins Haus und stärke dich, und ich will dir ein Geschenk geben*!", footnotes: ["℘ 1Sam 9,7; 2Kö 5,15"] },
      { number: 8, text: "Der Mann Gottes aber sagte zum König: <Selbst> wenn du mir die Hälfte deines Hauses gäbest, so würde ich nicht mit dir hineingehen*. Ich werde an diesem Ort kein Brot essen und kein Wasser trinken*.", footnotes: ["℘ 4Mo 22,18", "℘ Ps 141,4"] },
      { number: 9, text: "Denn so ist es mir durch das Wort des HERRN befohlen worden: Du sollst kein Brot essen und kein Wasser trinken, und du sollst nicht auf dem Weg zurückkehren, den du hingegangen bist!" },
      { number: 10, text: "So ging er auf einem anderen Weg <fort> und kehrte nicht auf dem Weg zurück, auf dem er nach Bethel gekommen war." },
      { number: 11, text: "Ein alter Prophet wohnte in Bethel; und seine Söhne kamen und erzählten ihm alles*, was der Mann Gottes an dem Tag in Bethel getan hatte; die Worte, die er zum König geredet hatte, die erzählten sie ihrem Vater.", footnotes: ["so mit LXX, Vulg. und der syr. Üs.; Mas. T.: und sein Sohn kam und erzählte ihm alles. — Als »Söhne des Propheten« werden häufig seine Jünger bezeichnet."] },
      { number: 12, text: "Da sagte ihr Vater zu ihnen: Welchen Weg ist er gegangen? Und seine Söhne zeigten ihm den Weg*, den der Mann Gottes gegangen war, der aus Juda gekommen war.", footnotes: ["so mit LXX und der aram. Üs.; Mas. T.: Und seine Söhne sahen den Weg"] },
      { number: 13, text: "Da sagte er zu seinen Söhnen: Sattelt mir den Esel! Und sie sattelten ihm den Esel, und er bestieg ihn." },
      { number: 14, text: "Und er folgte dem Mann Gottes und fand ihn unter der Terebinthe sitzen. Und er sagte zu ihm: Bist du der Mann Gottes, der aus Juda gekommen ist? Und er sagte: Ich bin es." },
      { number: 15, text: "Da sagte er zu ihm: Komm mit mir in <mein> Haus und iss Brot!" },
      { number: 16, text: "Er aber sagte: Ich kann nicht* mit dir umkehren, um mit dir hineinzugehen, und an diesem Ort werde ich kein Brot essen und kein Wasser mit dir trinken.", footnotes: ["o. Ich darf nicht"] },
      { number: 17, text: "Denn durch das Wort des HERRN ist ein Befehl* an mich <ergangen>: Du sollst dort kein Brot essen und kein Wasser trinken! Du sollst nicht wieder auf dem Weg <zurück>gehen, auf dem du hingegangen bist!", footnotes: ["w. ein Wort"] },
      { number: 18, text: "Da sagte er zu ihm: Auch ich bin ein Prophet wie du, und ein Engel hat zu mir geredet durch das Wort des HERRN und gesagt: Bring ihn mit dir in dein Haus zurück, dass er Brot esse und Wasser trinke! Er belog ihn <aber>*.", footnotes: ["℘ Kap. 22,22; 1Mo 3,13; 27,24; 1Jo 4,1"] },
      { number: 19, text: "Da kehrte er mit ihm zurück und aß in seinem Haus Brot und trank Wasser*.", footnotes: ["℘ 1Mo 3,6"] },
      { number: 20, text: "Und es geschah, während sie <noch> zu Tisch saßen, da geschah das Wort des HERRN zu dem Propheten, der ihn zurückgebracht hatte." },
      { number: 21, text: "Und er rief dem Mann Gottes, der aus Juda gekommen war, zu: So spricht der HERR: Dafür, dass du gegen den Befehl des HERRN widerspenstig gewesen bist und das Gebot, das der HERR, dein Gott, dir geboten hat, nicht beachtet hast" },
      { number: 22, text: "und umgekehrt bist und Brot gegessen und Wasser getrunken hast an dem Ort, von dem er zu dir geredet hat: Iss kein Brot und trinke kein Wasser! — <darum> soll deine Leiche nicht in das Grab deiner Väter kommen!" },
      { number: 23, text: "Und es geschah, nachdem er Brot gegessen und nachdem er getrunken hatte, da sattelte man für ihn den Esel des Propheten, der ihn zurückgebracht hatte." },
      { number: 24, text: "Und er zog fort. Da fand ihn ein Löwe auf dem Weg und tötete ihn*. Und seine Leiche blieb hingestreckt auf dem Weg liegen, und der Esel stand daneben, und der Löwe stand neben der Leiche.", footnotes: ["℘ Kap. 20,36"] },
      { number: 25, text: "Und siehe, da kamen Männer vorbei und sahen die Leiche auf dem Weg hingestreckt liegen und den Löwen neben der Leiche stehen. Und sie kamen und sagten es in der Stadt, in der der alte Prophet wohnte." },
      { number: 26, text: "Als nun der Prophet, der ihn von dem Weg zurückgeführt hatte, <das> hörte, sagte er: Das ist der Mann Gottes, der gegen den Befehl des HERRN widerspenstig gewesen ist; <darum> hat der HERR ihn dem Löwen preisgegeben: Der hat ihn zerrissen und getötet nach dem Wort des HERRN, das er zu ihm geredet hat." },
      { number: 27, text: "Und er redete zu seinen Söhnen und sagte: Sattelt mir den Esel! Und sie sattelten <ihn>." },
      { number: 28, text: "Und er ging hin und fand seine Leiche auf dem Weg hingestreckt liegen und den Esel und den Löwen neben der Leiche stehen; der Löwe hatte die Leiche nicht gefressen und den Esel nicht zerrissen." },
      { number: 29, text: "Da hob der Prophet die Leiche des Mannes Gottes auf und legte ihn auf den Esel und brachte ihn zurück. Und er kam in die Stadt des alten Propheten, um ihm die Totenklage zu halten und ihn zu begraben." },
      { number: 30, text: "Und er legte seine Leiche in sein eigenes Grab; und man hielt die Totenklage über ihn: Ach, mein Bruder*!", footnotes: ["℘ Jer 22,18"] },
      { number: 31, text: "Und es geschah, nachdem er ihn begraben hatte, sagte er zu seinen Söhnen: Wenn ich gestorben bin, dann begrabt mich in dem Grab, in dem der Mann Gottes begraben ist! Neben seine Gebeine legt meine Gebeine*!", footnotes: ["℘ 2Kö 23,17.18"] },
      { number: 32, text: "Denn das Wort wird ganz gewiss geschehen, das er auf das Wort des HERRN hin ausgerufen hat gegen den Altar, der in Bethel ist, und gegen alle Höhenheiligtümer*, die in den Städten Samarias sind.", footnotes: ["w. Häuser der Höhen"] },
      { number: 33, text: "Nach dieser Begebenheit kehrte Jerobeam von seinem bösen Weg nicht um*, sondern machte weiter <Leute> aus dem gesamten Volk zu Höhenpriestern; wer Lust hatte, den weihte er*, dass er ein Priester der Höhen wurde*.", footnotes: ["℘ 2Chr 28,22; Spr 27,22; Jer 5,3; Mt 23,37; Offb 16,9", "w. dem füllte er seine Hand", "℘ Kap. 12,31"] },
      { number: 34, text: "Und diese Sache wurde zur Sünde des Hauses Jerobeam* und zum <Anlass, es> auszutilgen und zu vernichten von der Oberfläche der Erde hinweg.*", footnotes: ["℘ Kap. 12,30", "℘ Kap. 14,7-11; 15,25-30; Spr 13,6"] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "In dieser Zeit erkrankte Abija, der Sohn Jerobeams.", heading: "Gerichtsandrohung Ahijas gegen Jerobeam und dessen Ende" },
      { number: 2, text: "Und Jerobeam sagte zu seiner Frau: Mach dich doch auf und verstell dich, damit man nicht erkennt, dass du die Frau Jerobeams bist, und geh nach Silo! Siehe, dort ist der Prophet Ahija; er ist es, der über mich geredet hat, dass ich König über dieses Volk sein sollte*.", footnotes: ["so mit LXX, Vulg. und der syr. Üs.; Mas. T.: der über mich als König über dieses Volk geredet hat\n℘ Kap. 11,29-31"] },
      { number: 3, text: "Und nimm zehn Brote mit dir* und Gebäck und einen Krug Honig und geh zu ihm*! Er wird dir mitteilen, was dem Jungen geschehen wird*.", footnotes: ["w. nimm in deine Hand", "℘ 1Sam 9,7.8; 2Kö 4,42", "℘ 2Kö 8,8.9"] },
      { number: 4, text: "Die Frau Jerobeams machte es so: Sie machte sich auf und ging nach Silo und kam in Ahijas Haus. Ahija aber konnte nicht <mehr> sehen, denn seine Augen waren wegen seines Alters starr geworden*.", footnotes: ["℘ 1Mo 27,1"] },
      { number: 5, text: "Der HERR aber hatte zu Ahija gesagt: Siehe, die Frau Jerobeams kommt herein, um ein Wort von dir zu erfragen wegen ihres Sohnes, denn er ist krank. So und so sollst du zu ihr reden. Es wird aber geschehen, wenn sie hereinkommt, wird sie sich unkenntlich gemacht haben." },
      { number: 6, text: "Und es geschah, als Ahija das Geräusch ihrer Füße hörte, als sie zum Eingang hereinkam, da sagte er: Komm herein, Frau Jerobeams! Wozu eigentlich hast du dich unkenntlich gemacht*? Ich bin mit einer harten <Botschaft> zu dir gesandt*.", footnotes: ["℘ Spr 21,30", "℘ 1Sam 15,16"] },
      { number: 7, text: "Geh hin, sage zu Jerobeam: So spricht der HERR, der Gott Israels: Weil ich dich mitten aus dem Volk heraus erhoben und dich zum Fürsten über mein Volk Israel gemacht habe*", footnotes: ["℘ Kap. 11,37; 16,2"] },
      { number: 8, text: "und das Königtum vom Haus David weggerissen und es dir gegeben habe, du aber nicht gewesen bist wie mein Knecht David, der meine Gebote bewahrt hat und mir nachgefolgt ist mit seinem ganzen Herzen, dass er nur tat, was recht ist in meinen Augen*,", footnotes: ["℘ Kap. 3,3"] },
      { number: 9, text: "und <weil> du es <noch> schlimmer getrieben hast als alle, die vor dir gewesen sind*, und hingegangen bist und dir andere Götter und gegossene Bilder gemacht hast, um mich zum Zorn zu reizen*, und mich hinter deinen Rücken geworfen hast*,", footnotes: ["℘ Kap. 16,25.30.33; 3Mo 19,4; Jer 7,26", "℘ Kap. 15,30; 5Mo 32,16", "℘ Neh 9,26; Ps 50,17"] },
      { number: 10, text: "darum, siehe, ich werde Unglück über das Haus Jerobeam bringen, und ich werde von Jerobeam ausrotten <alles>, was männlich ist*, den Unmündigen und den Mündigen* in Israel. Und ich werde hinter dem Haus Jerobeam her ausfegen, so, wie man Kot ausfegt, bis es ganz mit ihm aus ist.", footnotes: ["w. was an die Wand pisst", "o. den Verheirateten und den Unverheirateten; o. den Sklaven und den Freien; w. den Festgehaltenen und den Losgelassenen\n℘ Kap. 21,21; 5Mo 32,36; 2Kö 9,8"] },
      { number: 11, text: "Wer von Jerobeam in der Stadt stirbt, den werden die Hunde fressen*, und wer auf dem Feld stirbt, den werden die Vögel des Himmels fressen; denn der HERR hat es geredet*.", footnotes: ["℘ Kap. 13,34; 16,3.4; 21,24", "℘ Kap. 15,29; 4Mo 23,19; Jes 40,5; Joe 4,8"] },
      { number: 12, text: "Und du, mach dich auf, geh in dein Haus! Wenn deine Füße die Stadt betreten, wird das Kind sterben." },
      { number: 13, text: "Und ganz Israel wird ihm die Totenklage halten und ihn begraben; denn dieser allein vom <Haus> Jerobeam wird in ein Grab kommen, weil sich im Haus Jerobeam an ihm etwas Gutes in <seinem> Verhältnis zum HERRN, dem Gott Israels, gefunden hat*.", footnotes: ["℘ 2Chr 12,12"] },
      { number: 14, text: "Und der HERR wird für sich einen König über Israel erstehen lassen, der das Haus Jerobeam ausrotten wird *an jenem Tag*. Doch wie steht es schon jetzt*?", footnotes: ["w. dies ist der Tag; und was ist auch jetzt", "℘ Kap. 15,27-29; Spr 2,22", "w. dies ist der Tag; und was ist auch jetzt"] },
      { number: 15, text: "Und der HERR wird Israel schlagen, <dass es schwankt,> wie das Rohr im Wasser schwankt. Und er wird Israel ausreißen aus diesem guten Land*, das er ihren Vätern gegeben hat, und wird sie zerstreuen* jenseits des Stromes*, weil sie ihre Ascherim gemacht haben <und> damit den HERRN zum Zorn reizen*.", footnotes: ["℘ Jos 23,15; Jer 24,10", "℘ 5Mo 29,27; Am 5,27", "d. i. des Euphrats", "℘ 2Kö 17,11.17"] },
      { number: 16, text: "Und er wird Israel dahingeben um der Sünden Jerobeams willen, die er begangen* und mit denen er Israel zur Sünde verführt hat*.", footnotes: ["℘ 5Mo 32,30; 2Kö 17,23; Hos 9,17", "℘ Kap. 12,30; 15,26.30.34; 16,2.13.19.26; 21,22; 22,53; 2Kö 3,3; 10,31; 2Chr 28,19"] },
      { number: 17, text: "Und die Frau Jerobeams machte sich auf, ging <fort> und kam nach Tirza*. Als sie die Schwelle des Hauses betrat, starb der Junge.", footnotes: ["℘ Kap. 15,21.33; 16,6; Jos 12,24; 2Kö 15,14; Hl 6,4"] },
      { number: 18, text: "Und ganz Israel begrub ihn und hielt ihm die Totenklage nach dem Wort des HERRN, das er durch seinen Knecht, den Propheten Ahija, geredet hatte." },
      { number: 19, text: "Und die übrige Geschichte* Jerobeams, wie er Krieg geführt* und wie er regiert hat, siehe, das ist aufgeschrieben im Buch der Geschichte* der Könige von Israel*.", footnotes: ["w. der Rest der Begebenheiten", "℘ 2Chr 13,2-20", "w. im Buch der Begebenheiten der Tage", "℘ Kap. 15,31; 16,5.14.20.27; 22,39; 2Kö 1,18; 1Chr 9,1; 2Chr 20,34; 33,18"] },
      { number: 20, text: "Und die Tage, die Jerobeam regierte, <betrugen> 22 Jahre; und er legte sich zu seinen Vätern*. Und sein Sohn Nadab wurde an seiner Stelle König*.", footnotes: ["℘ 2Chr 13,2-20", "℘ Kap. 15,25"] },
      { number: 21, text: "*Und Rehabeam, der Sohn Salomos, war König in Juda*. 41 Jahre war Rehabeam alt, als er König wurde*, und er regierte siebzehn Jahre in Jerusalem, der Stadt, die der HERR aus allen Stämmen Israels erwählt hatte, um seinen Namen dort niederzulegen*. Und der Name seiner Mutter war Naama, die Ammoniterin*.", heading: "Rehabeam von Juda", footnotes: ["℘ 2Chr 12,1-16", "℘ Kap. 12,17.20", "℘ Kap. 11,43", "℘ Kap. 8,29", "℘ Kap. 11,1"] },
      { number: 22, text: "Und Juda tat, was böse war in den Augen des HERRN.* Und sie reizten ihn zur Eifersucht durch ihre Sünden, die sie begingen*, mehr als alles, was ihre Väter getan hatten*.", footnotes: ["℘ 2Kö 17,19", "w. Sünden, mit denen sie sündigten", "℘ 5Mo 32,16; Jer 7,26"] },
      { number: 23, text: "Und auch sie bauten sich Höhen* und Gedenksteine* und Ascherim* auf jedem hohen Hügel und unter jedem grünen Baum*.", footnotes: ["℘ Kap. 3,3; 12,31; Hes 16,24", "hebr. mazzebot; das sind aufrecht hingestellte Steine, die zu Ehren eines Gottes kultisch verehrt wurden\n℘ Hes 6,3-6", "℘ 2Chr 24,18", "℘ Kap. 15,12; 5Mo 12,2; 2Kö 16,4; 17,10; 2Chr 28,4; Jer 2,20; Hes 6,13"] },
      { number: 24, text: "Und es waren auch Tempelhurer* im Land. Sie taten nach allen Gräueln der Nationen, die der HERR vor den Söhnen Israel vertrieben hatte*.", footnotes: ["w. Geweihte\n℘ Kap. 15,12; 5Mo 23,18; 2Kö 23,7", "℘ 3Mo 18,26-30"] },
      { number: 25, text: "Und es geschah im fünften Jahr des Königs Rehabeam, da zog Schischak*, der König von Ägypten, gegen Jerusalem herauf.", footnotes: ["℘ Kap. 11,40"] },
      { number: 26, text: "Und er nahm die Schätze des Hauses des HERRN weg und die Schätze des Hauses des Königs, das alles nahm er weg; und er nahm alle goldenen Schilde weg, die Salomo gemacht hatte*.", footnotes: ["℘ Kap. 10,16.17; 2Kö 14,14"] },
      { number: 27, text: "Und der König Rehabeam machte an ihrer Stelle bronzene Schilde, und er vertraute <sie> der Hand der Obersten der Leibwächter* an, die den Eingang des Hauses des Königs bewachten.", footnotes: ["℘ 2Kö 11,4.19"] },
      { number: 28, text: "Und es geschah: sooft der König in das Haus des HERRN hineinging, trugen die Leibwächter die Schilde* und brachten sie dann wieder in das Wachzimmer der Leibwächter zurück.", footnotes: ["w. sie"] },
      { number: 29, text: "Und die übrige Geschichte* Rehabeams und alles, was er getan hat, ist das nicht geschrieben in dem Buch der Geschichte* der Könige von Juda?*", footnotes: ["w. der Rest der Begebenheiten", "w. im Buch der Begebenheiten der Tage", "℘ Kap. 15,7.23; 22,46; 2Kö 8,23; 15,36; 2Chr 25,26"] },
      { number: 30, text: "Und es war Krieg zwischen Rehabeam und Jerobeam alle <ihre> Tage*.", footnotes: ["℘ Kap. 12,24; 15,6.16"] },
      { number: 31, text: "Und Rehabeam legte sich zu seinen Vätern, und er wurde begraben bei seinen Vätern in der Stadt Davids*. Und der Name seiner Mutter war Naama, die Ammoniterin*. Und sein Sohn Abija* wurde an seiner Stelle König*.", footnotes: ["℘ Kap. 2,10", "℘ Kap. 11,1", "℘ 1Chr 3,10", "℘ Kap. 15,1; Mt 1,7"] },
    ]},
    { number: 15, verses: [
      { number: 1, text: "*Und im achtzehnten Jahr des Königs Jerobeam, des Sohnes Nebats, wurde Abija König über Juda*.", heading: "Abija von Juda", footnotes: ["℘ 2Chr 13", "℘ Kap. 14,31"] },
      { number: 2, text: "Er regierte drei Jahre in Jerusalem. Und der Name seiner Mutter war Maacha, die Tochter Abischaloms*.", footnotes: ["℘ V. 10; 2Chr 11,20-22"] },
      { number: 3, text: "Und er lebte* in allen Sünden seines Vaters, die der vor ihm getan hatte; und sein Herz war nicht ungeteilt* mit dem HERRN, seinem Gott, wie das Herz seines Vaters David*.", footnotes: ["w. ging", "w. vollständig", "℘ Kap. 3,3; 5Mo 17,20; 1Sam 25,28; Lk 1,6; Apg 13,22"] },
      { number: 4, text: "Doch Davids wegen gab ihm der HERR, sein Gott, eine Leuchte in Jerusalem, indem er seinen Sohn nach ihm <als König> aufstehen ließ und indem er Jerusalem bestehen ließ*,", footnotes: ["℘ Kap. 11,32.36; Ps 132,17; Röm 11,29"] },
      { number: 5, text: "weil David getan hatte, was recht war in den Augen des HERRN, und von allem, was er ihm geboten hatte, nicht abgewichen war alle Tage seines Lebens*, außer in der Sache mit Uria, dem Hetiter.*", footnotes: ["℘ Kap. 3,3; 5Mo 17,20; 1Sam 25,28; Lk 1,6; Apg 13,22", "℘ 2Sam 12,9"] },
      { number: 6, text: "Und es war Krieg zwischen Rehabeam* und Jerobeam alle Tage seines Lebens*.", footnotes: ["Einige hebr. Handschr. und die syr. Üs. lesen: Abija", "℘ Kap. 14,29.30"] },
      { number: 7, text: "Und die übrige Geschichte* Abijas und alles, was er getan hat, ist das nicht geschrieben in dem Buch der Geschichte* der Könige von Juda?* Und es war Krieg zwischen Abija und Jerobeam.*", footnotes: ["w. der Rest der Begebenheiten", "w. im Buch der Begebenheiten der Tage", "℘ Kap. 14,29.30", "℘ Kap. 14,29.30"] },
      { number: 8, text: "Und Abija legte sich zu seinen Vätern, und man begrub ihn in der Stadt Davids*. Und sein Sohn Asa* wurde an seiner Stelle König.", footnotes: ["℘ Kap. 2,10", "℘ 1Chr 3,10; Mt 1,7"] },
      { number: 9, text: "*Und im zwanzigsten Jahr Jerobeams, des Königs von Israel, wurde Asa König über Juda.", heading: "Asa von Juda", footnotes: ["℘ V. 9-15: 2Chr 14,1-5; 15,8-19"] },
      { number: 10, text: "Und er regierte 41 Jahre in Jerusalem; und der Name seiner Mutter war Maacha, die Tochter Abischaloms*.", footnotes: ["℘ V. 2"] },
      { number: 11, text: "Und Asa tat, was recht war in den Augen des HERRN, wie sein Vater David*.", footnotes: ["℘ Kap. 3,3; 22,43; 2Kö 12,3; 14,3; 15,3.34"] },
      { number: 12, text: "Und er schaffte die Tempelhurer* aus dem Land* und tat alle Götzen* weg, die seine Väter gemacht hatten*.", footnotes: ["w. die Geweihten", "℘ Kap. 14,24; 22,47", "w. Mistkugeln, o. Klötze; ein verächtlicher Ausdruck", "℘ Kap. 11,7.8; 14,23"] },
      { number: 13, text: "Auch seine Mutter Maacha entfernte er aus <ihrer Stellung als> Gebieterin, weil sie der Aschera ein Schandbild gemacht hatte; und Asa rottete ihr Schandbild aus und verbrannte es im Tal Kidron*.", footnotes: ["℘ 5Mo 9,21; 2Kö 10,26"] },
      { number: 14, text: "Die Höhen aber wichen nicht*; doch war das Herz Asas ungeteilt* mit dem HERRN alle seine Tage*.", footnotes: ["℘ Kap. 3,3", "w. vollständig", "℘ Kap. 8,61"] },
      { number: 15, text: "Und er brachte die heiligen Gaben* seines Vaters und seine <eigenen> heiligen Gaben* ins Haus des HERRN: Silber und Gold und Geräte.", footnotes: ["o. heiligen Dinge", "o. heiligen Dinge"] },
      { number: 16, text: "*Und es war Krieg zwischen Asa und Bascha, dem König von Israel, all ihre Tage*.", footnotes: ["℘ V. 16-24: 2Chr 16,1-6.11-14", "℘ V. 32; Kap. 14,30"] },
      { number: 17, text: "Bascha, der König von Israel, zog gegen Juda herauf und baute Rama* aus, um bei Asa, dem König von Juda, niemanden aus- und eingehen zu lassen.", footnotes: ["℘ Jos 18,25"] },
      { number: 18, text: "Da nahm Asa alles Silber und Gold, das in den Schätzen des Hauses des HERRN <noch> übrig geblieben war, und die Schätze des Hauses des Königs und gab sie in die Hand seiner Knechte; und der König Asa sandte sie zu Ben-Hadad, dem Sohn des Tabrimmon, des Sohnes Hesjons, dem König von Aram*, der in Damaskus wohnte*, und ließ <ihm> sagen:", footnotes: ["℘ 2Kö 12,19", "℘ Kap. 11,23.24"] },
      { number: 19, text: "Ein Bund <sei> zwischen mir und dir, zwischen meinem Vater und deinem Vater! Siehe, ich sende dir als Geschenk Silber und Gold. Auf, mach deinen Bund mit Bascha, dem König von Israel, ungültig, dass er von mir abzieht!" },
      { number: 20, text: "Und Ben-Hadad hörte auf den König Asa, und er sandte seine Heerobersten gegen die Städte Israels und schlug Ijon* und Dan* und Abel-Bet-Maacha* und ganz Kinneret* samt dem ganzen Land Naftali*.", footnotes: ["℘ 2Sam 20,15", "℘ Ri 18,29", "℘ Kap. 14,29.30", "℘ Jos 11,2", "℘ Kap. 20,34; Jos 19,39"] },
      { number: 21, text: "Und es geschah, als Bascha das hörte, da ließ er davon ab, Rama auszubauen, und blieb in Tirza*.", footnotes: ["℘ Kap. 14,17"] },
      { number: 22, text: "Der König Asa aber bot ganz Juda auf, keiner war frei <vom Dienst>; und sie trugen die Steine und das Bauholz von Rama weg, mit denen Bascha gebaut hatte. Und der König Asa baute damit Geba <in> Benjamin* und Mizpa* aus.", footnotes: ["℘ Jos 18,24", "℘ Jos 18,26; Jer 41,9.10"] },
      { number: 23, text: "Und die übrige ganze Geschichte* Asas und alle seine Machttaten* und alles, was er getan hat, und die Städte, die er gebaut hat, ist das nicht geschrieben im Buch der Geschichte* der Könige von Juda?* Doch zur Zeit seines Alters war er an seinen Füßen krank.", footnotes: ["w. der Rest der Begebenheiten", "℘ 2Chr 14,7-14", "w. im Buch der Begebenheiten der Tage", "℘ Kap. 14,29"] },
      { number: 24, text: "Und Asa legte sich zu seinen Vätern und wurde bei seinen Vätern in der Stadt seines Vaters David* begraben. Und sein Sohn Joschafat* wurde an seiner Stelle König*.", footnotes: ["℘ Kap. 2,10", "℘ 1Chr 3,10", "℘ Kap. 22,41; 2Chr 17,1"] },
      { number: 25, text: "Und Nadab, der Sohn Jerobeams, wurde König über Israel im zweiten Jahr Asas, des Königs von Juda*; und er regierte zwei Jahre über Israel.", heading: "Nadab von Israel", footnotes: ["℘ Kap. 14,20"] },
      { number: 26, text: "Und er tat, was böse war in den Augen des HERRN, und ging auf dem Weg seines Vaters und <lebte> in dessen Sünde, mit der er Israel zur Sünde verführt hatte*.", footnotes: ["℘ V. 34; Kap. 14,16; 3Jo 11"] },
      { number: 27, text: "Gegen ihn verschwor sich* Bascha, der Sohn Ahijas, vom Haus Issaschar. Und Bascha erschlug ihn* bei Gibbeton, während Nadab und ganz Israel Gibbeton belagerten*, das den Philistern gehörte.", footnotes: ["℘ Kap. 16,9.16; 2Kö 9,14; 2Chr 24,25", "℘ Kap. 16,10", "℘ Kap. 16,15; Jos 19,44"] },
      { number: 28, text: "Und Bascha tötete ihn im dritten Jahr Asas, des Königs von Juda, und wurde an seiner Stelle König." },
      { number: 29, text: "Und es geschah, sobald er König geworden war, erschlug er das ganze Haus Jerobeam*; er ließ von Jerobeam nichts übrig, was Odem hatte, bis er es ausgetilgt hatte nach dem Wort des HERRN, das er durch seinen Knecht Ahija, den Siloniter, geredet hatte*", footnotes: ["℘ Kap. 13,34", "℘ Kap. 14,10-14; 16,3.7.11; 2Kö 9,9"] },
      { number: 30, text: "wegen der Sünden Jerobeams, die er begangen und mit denen er Israel zur Sünde verführt hatte, durch den Zorn*, zu dem er den HERRN, den Gott Israels, gereizt hatte*.", footnotes: ["w. durch seinen Zorn; d. i. kraft des Zorns des HERRN", "℘ Kap. 14,9; 21,21.22"] },
      { number: 31, text: "Und die übrige Geschichte* Nadabs und alles, was er getan hat, ist das nicht geschrieben im Buch der Geschichte* der Könige von Israel?*", footnotes: ["w. der Rest der Begebenheiten", "w. im Buch der Begebenheiten der Tage", "℘ Kap. 14,19"] },
      { number: 32, text: "Und es war Krieg zwischen Asa und Bascha, dem König von Israel, alle ihre Tage*.", footnotes: ["℘ V. 16"] },
      { number: 33, text: "Im dritten Jahr Asas, des Königs von Juda, wurde Bascha, der Sohn Ahijas, König über ganz Israel in Tirza* <und regierte> 24 Jahre <lang>.", heading: "Bascha von Israel", footnotes: ["℘ Kap. 14,17"] },
      { number: 34, text: "Und er tat, was böse war in den Augen des HERRN, und ging auf dem Weg Jerobeams und in dessen Sünde, mit der er Israel zur Sünde verführt hatte*.", footnotes: ["℘ V. 26"] },
    ]},
    { number: 16, verses: [
      { number: 1, text: "Und es geschah das Wort des HERRN zu Jehu, dem Sohn des Hanani*, gegen Bascha:", footnotes: ["℘ 2Kö 17,13; 2Chr 16,7"] },
      { number: 2, text: "Weil ich dich aus dem Staub erhoben und dich zum Fürsten über mein Volk Israel gemacht habe*, du aber auf dem Weg Jerobeams gegangen bist und mein Volk Israel zur Sünde verführt hast, so dass sie mich durch ihre Sünden zum Zorn reizen*,", footnotes: ["℘ Kap. 14,7; Ps 113,7.8", "℘ Kap. 14,16"] },
      { number: 3, text: "siehe, so werde ich hinter Bascha und hinter seinem Haus her ausfegen lassen und werde dein Haus machen wie das Haus Jerobeams, des Sohnes Nebats*.", footnotes: ["℘ Kap. 15,29.30"] },
      { number: 4, text: "Wer von Bascha in der Stadt stirbt, den werden die Hunde fressen, und wer von ihm auf <freiem> Feld stirbt, den werden die Vögel des Himmels fressen*.", footnotes: ["℘ Kap. 14,11"] },
      { number: 5, text: "Und die übrige Geschichte* Baschas und <alles,> was er getan hat, und seine Machttaten, ist das nicht geschrieben im Buch der Geschichte* der Könige von Israel?*", footnotes: ["w. der Rest der Begebenheiten", "w. im Buch der Begebenheiten der Tage", "℘ Kap. 14,19"] },
      { number: 6, text: "Und Bascha legte sich zu seinen Vätern und wurde in Tirza* begraben. Und sein Sohn Ela wurde an seiner Stelle König*.", footnotes: ["℘ Kap. 14,17", "℘ V. 8.28"] },
      { number: 7, text: "Auch durch den Propheten Jehu, den Sohn des Hanani*, war das Wort des HERRN gegen Bascha und gegen sein Haus ergangen, und zwar wegen all des Bösen, das er in den Augen des HERRN getan hatte, um ihn durch das Tun seiner Hände zum Zorn zu reizen, so dass er dem Haus Jerobeam gleich werden sollte, und <auch> deswegen, weil er dieses* erschlagen hatte*.", footnotes: ["℘ 2Kö 17,13; 2Chr 16,7", "nämlich das Haus, d. h. die Familie Jerobeams", "℘ Kap. 15,29"] },
      { number: 8, text: "Im 26. Jahr Asas, des Königs von Juda, wurde Ela, der Sohn Baschas, König über Israel* in Tirza <und regierte> zwei Jahre.", heading: "Ela von Israel und die Verschwörung Simris — Simris Ende", footnotes: ["℘ V. 6"] },
      { number: 9, text: "Gegen ihn verschwor sich* sein Knecht Simri, der Oberste über die Hälfte der Kriegswagen. Er aber hatte getrunken und sich berauscht* in Tirza, im Haus Arzas, der über das Haus in Tirza <gesetzt war>.", footnotes: ["℘ Kap. 15,27", "℘ Kap. 20,16; Spr 23,34"] },
      { number: 10, text: "Da kam Simri herein und erschlug ihn; er tötete ihn* im 27. Jahr Asas, des Königs von Juda, und wurde an seiner Stelle König*.", footnotes: ["℘ Kap. 15,27; 2Kö 9,31", "℘ V. 15; 2Kö 15,10"] },
      { number: 11, text: "Und es geschah, als er König war, sobald er auf seinem Thron saß, erschlug er das ganze Haus Baschas; er ließ nichts von ihm übrig, was männlich war*, weder seine Blutsverwandten noch seine Freunde*.", footnotes: ["w. was an die Wand pisst", "℘ Kap. 15,29; Ps 109,13"] },
      { number: 12, text: "So tilgte Simri das ganze Haus Baschas aus nach dem Wort des HERRN, das er durch den Propheten Jehu gegen Bascha geredet hatte," },
      { number: 13, text: "wegen all der Sünden Baschas und der Sünden seines Sohnes Ela, die sie begangen und mit denen sie Israel zur Sünde verführt hatten, den HERRN, den Gott Israels, durch ihre nichtigen Götzen* zum Zorn zu reizen*.", footnotes: ["w. durch ihre Nichtigkeiten", "℘ V. 26; Kap. 14,16"] },
      { number: 14, text: "Und die übrige Geschichte* Elas und alles, was er getan hat, ist das nicht geschrieben im Buch der Geschichte* der Könige von Israel?*", footnotes: ["w. der Rest der Begebenheiten", "w. im Buch der Begebenheiten der Tage", "℘ V. 27; Kap. 14,19"] },
      { number: 15, text: "Im 27. Jahr Asas, des Königs von Juda, wurde Simri <für> sieben Tage König in Tirza*, während das Volk gegen Gibbeton*, das den Philistern gehörte, das Kriegslager aufgeschlagen hatte.", footnotes: ["℘ V. 10", "℘ Kap. 15,27"] },
      { number: 16, text: "Und als das Volk im Kriegslager* sagen hörte: Simri hat eine Verschwörung gemacht* und hat auch den König erschlagen, da machte ganz Israel den Heerobersten Omri an demselben Tag im Lager zum König über Israel.", footnotes: ["w. das Volk, das das Kriegslager aufgeschlagen hatte,", "℘ Kap. 15,27"] },
      { number: 17, text: "Und Omri zog herauf und ganz Israel mit ihm von Gibbeton, und sie belagerten Tirza." },
      { number: 18, text: "Und es geschah, als Simri sah, dass die Stadt eingenommen war, ging er in den Palast des Königshauses und verbrannte das Königshaus über sich mit Feuer und starb*", footnotes: ["℘ 2Sam 17,23; 2Kö 9,31"] },
      { number: 19, text: "wegen seiner Sünden, die er begangen hatte, indem er tat, was böse war in den Augen des HERRN, indem er auf dem Weg Jerobeams und in seiner Sünde lebte*, die der getan hatte, um Israel zur Sünde zu verführen*.", footnotes: ["w. ging", "℘ Kap. 14,16"] },
      { number: 20, text: "Und die übrige Geschichte* Simris und seine Verschwörung, die er gemacht hat, ist das nicht geschrieben im Buch der Geschichte* der Könige von Israel?*", footnotes: ["w. der Rest der Begebenheiten", "w. im Buch der Begebenheiten der Tage", "℘ V. 27; Kap. 14,19"] },
      { number: 21, text: "Damals teilte sich das Volk Israel in <zwei> Hälften: Die eine Hälfte des Volkes folgte Tibni, dem Sohn des Ginat, um ihn zum König zu machen; und die andere Hälfte folgte Omri*.", heading: "Omri von Israel", footnotes: ["℘ Spr 28,2; Jes 9,18"] },
      { number: 22, text: "Aber das Volk, das Omri folgte, war dem Volk, das Tibni, dem Sohn des Ginat, folgte, überlegen. Und Tibni starb, und Omri wurde König." },
      { number: 23, text: "Im 31. Jahr Asas, des Königs von Juda, wurde Omri* König über Israel* <und regierte> zwölf Jahre; in Tirza war er sechs Jahre König.", footnotes: ["℘ 2Kö 8,26", "℘ V. 27; Kap. 14,19"] },
      { number: 24, text: "Und er kaufte den Berg Samaria* von Schemer für zwei Talente Silber. Und er bebaute den Berg und gab der Stadt, die er gebaut hatte, den Namen Samaria nach dem Namen Schemers, des <ehemaligen> Besitzers des Berges.", footnotes: ["℘ Am 6,1; Mi 1,5.6"] },
      { number: 25, text: "Und Omri tat, was böse war in den Augen des HERRN, und zwar schlimmer als alle, die vor ihm gewesen waren*.", footnotes: ["℘ V. 30.33; Kap. 14,9; 21,25.26; 2Kö 17,2; Mi 6,16; 2Tim 3,13"] },
      { number: 26, text: "Und er ging auf dem ganzen Weg Jerobeams, des Sohnes Nebats, und <lebte> in dessen Sünden, mit denen er Israel zur Sünde verführt hatte, den HERRN, den Gott Israels, durch ihre nichtigen Götzen* zum Zorn zu reizen*.", footnotes: ["w. durch ihre Nichtigkeiten", "℘ V. 13"] },
      { number: 27, text: "Und die übrige Geschichte* Omris, was er getan und seine Machttaten, die er vollführt hat, ist das nicht geschrieben im Buch der Geschichte* der Könige von Israel?*", footnotes: ["w. der Rest der Begebenheiten", "w. im Buch der Begebenheiten der Tage", "℘ V. 14.20; Kap. 12,30; 14,16"] },
      { number: 28, text: "Und Omri legte sich zu seinen Vätern* und wurde in Samaria begraben. Und sein Sohn Ahab wurde an seiner Stelle König*.", footnotes: ["℘ V. 6.8", "℘ V. 27; Kap. 14,19"] },
      { number: 29, text: "Und Ahab, der Sohn Omris, wurde König über Israel im 38. Jahr Asas, des Königs von Juda; und Ahab, der Sohn Omris, regierte über Israel in Samaria 22 Jahre.", heading: "Ahab von Israel — Sein Götzendienst und Elias Gerichtsandrohung" },
      { number: 30, text: "Und Ahab, der Sohn Omris, tat, was böse war in den Augen des HERRN, mehr als alle, die vor ihm gewesen waren." },
      { number: 31, text: "Und es geschah — war es zu wenig, dass er in den Sünden Jerobeams, des Sohnes Nebats, lebte*? —, dass er Isebel*, die Tochter Etbaals, des Königs der Sidonier*, zur Frau nahm. Und er ging hin und diente dem Baal und warf sich vor ihm nieder*.", footnotes: ["w. ging", "℘ Offb 2,20", "℘ Ri 1,31; 2Kö 9,34", "℘ 5Mo 7,3.4; Hos 2,15"] },
      { number: 32, text: "Und er errichtete dem Baal einen Altar im Haus des Baal*, das er in Samaria gebaut hatte*.", footnotes: ["℘ Kap. 18,18; 2Kö 10,18.21", "℘ 2Kö 3,2"] },
      { number: 33, text: "Auch machte Ahab die Aschera*. Und Ahab fuhr fort, den HERRN, den Gott Israels, zum Zorn zu reizen, mehr als alle Könige von Israel, die vor ihm gewesen waren*.", footnotes: ["℘ 2Kö 13,6; 2Chr 21,13", "℘ V. 25; 2Chr 33,6"] },
      { number: 34, text: "In seinen Tagen baute Hiël, der Betheliter, <die Stadt> Jericho <wieder> auf. Um <den Preis von> seinem Erstgeborenen, Abiram, legte er ihren Grund, und um <den Preis von> Segub, seinem Jüngsten, setzte er ihre Tore ein nach dem Wort des HERRN, das er durch Josua, den Sohn des Nun, geredet hatte.*", footnotes: ["℘ Jos 6,26"] },
    ]},
    { number: 17, verses: [
      { number: 1, text: "Und Elia*, der Tischbiter, aus Tischbe <in> Gilead*, sagte zu Ahab: So wahr der HERR, der Gott Israels, lebt, vor dem ich stehe*, wenn es in diesen Jahren Tau und Regen geben wird*, es sei denn auf mein Wort!*", footnotes: ["hebr. elijahu; d. h. Jah ist mein Gott\n℘ 2Kö 1,3; 2Chr 21,12; Mal 3,23; Mt 11,14; 17,3", "so mit LXX; Mas. T.: aus Tosabe in Gilead, o. von den Beisassen Gileads", "d. h. dem ich diene\n℘ Kap. 18,15; 2Kö 3,14", "Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde.\n℘ Kap. 8,35; Lk 4,25", "℘ 2Kö 4,38; Jak 5,17; Offb 11,6"] },
      { number: 2, text: "Und es geschah das Wort des HERRN zu ihm:", heading: "Elia am Bach Krit und in Zarpat" },
      { number: 3, text: "Geh von hier fort, wende dich nach Osten und verbirg dich am Bach Krit, der vor dem* Jordan ist!", footnotes: ["d. h. östlich vom"] },
      { number: 4, text: "Und es soll geschehen: Aus dem Bach wirst du trinken, und ich habe den Raben geboten*, dich dort zu versorgen*.", footnotes: ["℘ Jon 2,1.2.11", "℘ Kap. 19,6; Mt 6,26; Lk 4,26"] },
      { number: 5, text: "Da ging er und tat nach dem Wort des HERRN: Er ging hin und blieb am Bach Krit, der vor dem* Jordan ist.", footnotes: ["d. h. östlich vom"] },
      { number: 6, text: "Und die Raben brachten ihm Brot und Fleisch am Morgen und Brot und Fleisch am Abend*, und aus dem Bach trank er*.", footnotes: ["LXX: Und die Raben brachten ihm Brot am Morgen und Fleisch am Abend", "℘ Ps 33,18.19"] },
      { number: 7, text: "Und es geschah nach einiger Zeit*, da vertrocknete der Bach, denn es war kein Regen im Land*.", footnotes: ["w. am Ende von Tagen", "℘ 5Mo 28,22; Hi 12,15; Joe 1,20"] },
      { number: 8, text: "Da geschah das Wort des HERRN zu ihm:" },
      { number: 9, text: "Mache dich auf, geh nach Zarpat*, das zu Sidon gehört, und bleib dort! Siehe, ich habe dort einer Witwe befohlen, dich zu versorgen*.", footnotes: ["℘ Ob 20", "℘ Kap. 19,6; Mt 6,26; Lk 4,26"] },
      { number: 10, text: "Da machte er sich auf und ging nach Zarpat. Und als er an den Eingang der Stadt kam, siehe, da war dort eine Witwe, die gerade Holz sammelte. Und er rief sie an und sagte: Hole mir doch ein wenig Wasser im Gefäß, dass ich trinke!*", footnotes: ["℘ Joh 4,7"] },
      { number: 11, text: "Und als sie hinging, um es zu holen, rief er ihr zu und sagte: Hole mir doch <auch noch> einen Bissen Brot in deiner Hand!" },
      { number: 12, text: "Da sagte sie: So wahr der HERR, dein Gott, lebt, wenn ich einen Vorrat habe außer einer Handvoll Mehl im Topf und ein wenig Öl im Krug*!* Siehe, ich sammle eben ein paar Holzstücke auf, dann will ich hineingehen und es mir und meinem Sohn zubereiten, damit wir es essen und <dann> sterben.", footnotes: ["Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde.", "℘ 2Kö 4,2"] },
      { number: 13, text: "Da sagte Elia zu ihr: Fürchte dich nicht! Geh hinein, tu nach deinem Wort! Doch zuerst bereite mir davon einen kleinen Kuchen* zu und bring ihn mir heraus! Dir aber und deinem Sohn magst du danach etwas zubereiten.", footnotes: ["d. i. ein Brotfladen, der in heißer Asche schnell gebacken werden konnte"] },
      { number: 14, text: "Denn so spricht der HERR, der Gott Israels: Das Mehl im Topf soll nicht ausgehen und das Öl im Krug nicht abnehmen* bis auf den Tag, an dem der HERR Regen geben wird auf den Erdboden.", footnotes: ["w. der Mehltopf soll nicht ausgehen, und der Ölkrug soll nicht abnehmen; so auch V. 16"] },
      { number: 15, text: "Da ging sie hin und tat nach dem Wort Elias. Und sie aß, er und sie und ihr Haus, Tag für Tag*.", footnotes: ["℘ Mt 10,41"] },
      { number: 16, text: "Das Mehl im Topf ging nicht aus, und das Öl im Krug nahm nicht ab nach dem Wort des HERRN, das er durch Elia geredet hatte*.", footnotes: ["℘ Kap. 22,38; 2Kö 1,17; 5,14"] },
      { number: 17, text: "Und es geschah nach diesen Ereignissen, da wurde der Sohn der Frau, der Hausherrin, krank. Und seine Krankheit wurde sehr heftig, so dass kein Odem mehr in ihm blieb*.", footnotes: ["℘ 2Kö 4,20; Joh 11,3.11"] },
      { number: 18, text: "Da sagte sie zu Elia: Was habe ich mit dir <zu tun>, Mann Gottes*? Du bist zu mir gekommen, um meine Schuld <vor Gott> in Erinnerung zu bringen* und meinen Sohn zu töten.", footnotes: ["℘ Ri 13,6; Mt 8,29", "℘ 1Mo 44,16; Hi 13,26"] },
      { number: 19, text: "Er aber sagte zu ihr: Gib mir deinen Sohn! Und er nahm ihn von ihrem Schoß und brachte ihn hinauf ins Obergemach, wo er wohnte, und legte ihn auf sein Bett." },
      { number: 20, text: "Und er rief zum HERRN und sprach: HERR, mein Gott, tust du nun auch der Witwe, bei der ich mich aufhalte, Böses an, indem du ihren Sohn sterben lässt*?", footnotes: ["℘ 1Mo 38,7.10; 2Kö 4,33"] },
      { number: 21, text: "Und er streckte sich dreimal über das Kind hin* und rief zum HERRN und sprach: HERR, mein Gott, lass doch das Leben dieses Kindes wieder zu ihm* zurückkehren!", footnotes: ["℘ 2Kö 4,34.35; Apg 20,10", "w. in sein Leibesinneres"] },
      { number: 22, text: "Und der HERR hörte auf die Stimme Elias, und das Leben des Kindes kehrte zu ihm* zurück, und es wurde <wieder> lebendig*.", footnotes: ["w. in sein Leibesinneres", "℘ 1Sam 2,6; Mt 9,25"] },
      { number: 23, text: "Da nahm Elia das Kind und brachte es vom Obergemach ins Haus hinab und gab es seiner Mutter; und Elia sagte: Siehe, dein Sohn lebt!*", footnotes: ["℘ 2Kö 4,36.37"] },
      { number: 24, text: "Da sagte die Frau zu Elia: Jetzt erkenne ich, dass du ein Mann Gottes bist und dass das Wort des HERRN in deinem Mund Wahrheit ist*.", footnotes: ["℘ Kap. 12,22; 2Kö 4,9.16; Joh 3,2"] },
    ]},
    { number: 18, verses: [
      { number: 1, text: "Und es vergingen viele Tage, da geschah das Wort des HERRN zu Elia im dritten Jahr <der Dürre>: Geh hin, zeige dich Ahab! Ich will Regen geben auf den Erdboden*.", heading: "Elias Begegnung mit Obadja und Ahab", footnotes: ["℘ Jer 14,22"] },
      { number: 2, text: "Da ging Elia hin*, um sich Ahab zu zeigen*. Die Hungersnot in Samaria aber war schwer*.", footnotes: ["℘ 2Kö 1,4", "℘ Ps 56,5", "℘ 3Mo 26,20; 2Kö 6,25; Lk 4,25"] },
      { number: 3, text: "Und Ahab rief Obadja, der über das Haus <gesetzt> war — Obadja aber fürchtete den HERRN sehr*.", footnotes: ["w. war sehr Jahwe-fürchtig\n℘ Neh 7,2; Ps 112,1"] },
      { number: 4, text: "Es geschah nämlich, als Isebel die Propheten des HERRN ausrottete*, da nahm Obadja hundert Propheten und versteckte sie, je fünfzig Mann in einer Höhle, und versorgte sie mit Brot und Wasser —*.", footnotes: ["℘ 2Kö 9,7", "℘ Gal 6,10"] },
      { number: 5, text: "Und Ahab sagte zu Obadja: Geh durch das Land zu allen Wasserquellen und zu allen Bächen! Vielleicht findet sich <noch etwas> Gras, dass wir Pferde und Maultiere am Leben erhalten können und nichts von dem Vieh umkommen lassen müssen." },
      { number: 6, text: "Dann teilten sie das Land unter sich, um es zu durchziehen. Ahab ging für sich auf einem Weg, und Obadja ging für sich auf einem Weg." },
      { number: 7, text: "Und als Obadja auf dem Weg war, siehe, da kam ihm Elia entgegen. Und er erkannte ihn und fiel auf sein Angesicht und sagte: Bist du es, mein Herr Elia?" },
      { number: 8, text: "Und er sagte zu ihm: Ich bin es. Geh hin, sage deinem Herrn: Siehe, Elia ist da!" },
      { number: 9, text: "Er aber sagte: Worin habe ich gesündigt, dass du deinen Knecht in die Hand Ahabs geben willst, damit er mich tötet?" },
      { number: 10, text: "So wahr der HERR, dein Gott, lebt, wenn es eine Nation oder ein Königreich gibt, wohin mein Herr nicht gesandt hat, um dich zu suchen*!* Und sagten sie: Er ist nicht <hier>, dann ließ er das Königreich und die Nation schwören, dass man dich nicht gefunden habe.", footnotes: ["s. letzte Anm. zu Kap. 17,1", "℘ 1Sam 23,23; Jer 26,20-23"] },
      { number: 11, text: "Und nun sagst du: Geh hin, sage deinem Herrn: Siehe, Elia ist da!" },
      { number: 12, text: "Und es wird geschehen, wenn ich von dir weggehe, dann wird dich der Geist des HERRN <davon>tragen, ich weiß nicht wohin*; wenn ich <dann> komme, Ahab zu berichten, und er findet dich nicht, wird er mich umbringen*. Und dein Knecht fürchtet <doch> den HERRN von meiner Jugend an*.", footnotes: ["℘ 2Kö 2,16; Hes 3,12; Apg 8,39", "℘ 1Sam 16,2", "℘ Ps 71,5"] },
      { number: 13, text: "Ist meinem Herrn nicht berichtet worden, was ich getan habe, als Isebel die Propheten des HERRN umbrachte? Dass ich von den Propheten des HERRN hundert Mann versteckte, fünfzig <hier und> fünfzig <da>, jeweils in einer Höhle, und dass ich sie mit Brot und Wasser versorgte*?", footnotes: ["℘ Spr 28,12; Hebr 6,10; 11,38"] },
      { number: 14, text: "Und nun sagst du: Geh hin, sage deinem Herrn: Siehe, Elia ist da! Dann wird er mich umbringen*.", footnotes: ["℘ 1Sam 16,2"] },
      { number: 15, text: "Elia aber sagte: So wahr der HERR der Heerscharen lebt, vor dem ich stehe*, heute werde ich mich ihm zeigen!", footnotes: ["℘ Kap. 17,1"] },
      { number: 16, text: "Da ging Obadja hin, Ahab entgegen, und berichtete es ihm*. Und Ahab ging Elia entgegen.", footnotes: ["℘ Jer 39,17.18"] },
      { number: 17, text: "Und es geschah, als Ahab Elia sah, da sagte Ahab zu ihm: Bist du da, der Israel ins Unglück gebracht hat*?", footnotes: ["℘ Am 7,10"] },
      { number: 18, text: "Er aber sagte: Nicht ich habe Israel ins Unglück gebracht, sondern du* und das Haus deines Vaters, indem ihr die Gebote des HERRN verlassen habt* und du den Baalim nachgelaufen bist*.", footnotes: ["℘ 2Chr 28,19", "℘ Jer 2,19", "℘ Kap. 16,31.32"] },
      { number: 19, text: "Und nun sende hin, versammle ganz Israel zu mir an den Berg Karmel* und die 450 Propheten des Baal* und die 400 Propheten der Aschera, die am Tisch Isebels essen!", footnotes: ["℘ Jos 19,26; Hl 7,6", "℘ 2Kö 3,13"] },
      { number: 20, text: "Da sandte Ahab unter allen Söhnen Israel umher und versammelte die Propheten* an den Berg Karmel.", footnotes: ["℘ Kap. 22,6; Jer 23,13"] },
      { number: 21, text: "Und Elia trat zum ganzen Volk hin und sagte: Wie lange hinkt* ihr auf beiden Seiten*?* Wenn der HERR der <wahre> Gott ist, dann folgt ihm nach; wenn aber der Baal, dann folgt ihm nach!* Aber das Volk antwortete ihm kein Wort.", heading: "Elia und die Propheten des Baal auf dem Karmel", footnotes: ["o. hüpft. — Damit wird auf den kultischen Tanz der Baalspriester in V. 26 angespielt, wo dasselbe Wort steht.", "o. auf zwei Krücken", "℘ 2Kö 17,41; Mt 6,24; Offb 3,15", "℘ Jos 24,15"] },
      { number: 22, text: "Da sagte Elia zum Volk: Ich allein bin übrig geblieben* als Prophet des HERRN, aber die Propheten des Baal sind 450 Mann.", footnotes: ["℘ Kap. 19,10.14"] },
      { number: 23, text: "Man gebe uns nun zwei Stiere! Sie sollen sich den einen von den Stieren auswählen, ihn in Stücke zerschneiden und aufs Holz legen, aber sie sollen kein Feuer daran legen. Und ich, ich werde den anderen Stier zurichten und aufs Holz legen, und <auch> ich werde kein Feuer daran legen." },
      { number: 24, text: "Dann ruft ihr den Namen eures Gottes an, und ich, ich werde den Namen des HERRN anrufen. Und der Gott, der mit Feuer antwortet, der ist der <wahre> Gott*. Da antwortete das ganze Volk und sagte: Das Wort ist gut*.", footnotes: ["℘ V. 38.39", "℘ Kap. 2,38"] },
      { number: 25, text: "Und Elia sagte zu den Propheten des Baal: Wählt euch den einen Stier aus und richtet ihn zuerst zu! Denn ihr seid viele. Dann ruft den Namen eures Gottes an! Aber Feuer legt nicht daran!" },
      { number: 26, text: "So nahmen sie den Stier, den man ihnen überlassen hatte, und richteten ihn zu. Darauf riefen sie vom Morgen bis zum Mittag den Namen des Baal an: Baal, antworte uns! Aber da war kein Laut, keine Antwort*. Und sie hüpften* um den Altar, den man gemacht hatte.", footnotes: ["w. kein Laut, keiner, der antwortete\n℘ 2Mo 8,14; Ps 115,4-8; Jes 46,7", "d. i. eine verächtliche Bezeichnung für kultischen Tanz"] },
      { number: 27, text: "Und es geschah am Mittag, da verspottete Elia sie und sagte: Ruft mit lauter Stimme, denn er ist <ja> ein Gott! Er ist sicher in Gedanken*, oder er ist austreten gegangen*, oder er ist auf der Reise; vielleicht schläft er, dann wird er aufwachen.", footnotes: ["o. Er hat sicher eine Beschäftigung", "w. er hat sicher seine Ausscheidung"] },
      { number: 28, text: "Da riefen sie mit lauter Stimme und ritzten sich, wie <es> bei ihnen Brauch <war>, mit Messern und mit Spießen, bis das Blut an ihnen herabfloss*.", footnotes: ["w. bis zum Blutvergießen an ihnen\n℘ Jer 47,5; Sach 13,6"] },
      { number: 29, text: "Und es geschah, als der Mittag vorüber war, da weissagten* sie bis <zur Zeit, da> man das Speisopfer opfert*; aber da war kein Laut, keine Antwort*, kein Aufhorchen*.", footnotes: ["Das Wort kann auch bedeuten: »<von einem Geist> in Erregung o. Raserei versetzt werden«, vgl. 1Sam 18,10.\n℘ 1Sam 10,5; Mt 6,7", "℘ 2Mo 29,41; Dan 9,21", "w. kein Laut, keiner, der antwortete", "℘ 2Mo 8,14; Ps 115,4-8; Jes 46,7"] },
      { number: 30, text: "Da sagte Elia zum ganzen Volk: Tretet her zu mir! Und das ganze Volk trat zu ihm hin. Dann stellte er den niedergerissenen Altar des HERRN wieder her*.", footnotes: ["℘ Kap. 19,10"] },
      { number: 31, text: "Und Elia nahm zwölf Steine nach der Zahl der Stämme der Söhne Jakobs*, zu dem das Wort des HERRN geschehen war, als er gesagt hatte: Israel soll dein Name sein!*", footnotes: ["℘ 2Mo 24,4", "℘ 1Mo 32,29"] },
      { number: 32, text: "Und er baute von den Steinen einen Altar* im Namen des HERRN; und er zog rings um den Altar einen Graben so breit wie für zwei Maß Saat.", footnotes: ["℘ 1Mo 12,7.8; Ri 6,24"] },
      { number: 33, text: "Dann schichtete er das Holz auf und zerschnitt den Stier in Stücke und legte ihn auf das Holz*.", footnotes: ["℘ 3Mo 1,6-8"] },
      { number: 34, text: "Und er sagte: Füllt vier Eimer mit Wasser und gießt es auf das Brandopfer und auf das Holz! Und er sagte: Tut es zum zweiten Mal! Und sie taten es zum zweiten Mal. Und er sagte: Tut es zum dritten Mal! Und sie taten es zum dritten Mal." },
      { number: 35, text: "Da lief das Wasser rings um den Altar; und auch den Graben füllte er mit Wasser." },
      { number: 36, text: "Und es geschah <zur Zeit>, da man das Speisopfer opfert*, da trat der Prophet Elia herzu und sprach: HERR, Gott Abrahams, Isaaks und Israels!* Heute soll man erkennen, dass du Gott in Israel bist* und ich dein Knecht und dass ich nach deinem Wort das alles getan habe*.", footnotes: ["℘ 2Mo 29,41; Dan 9,21", "℘ 2Mo 3,6; 2Chr 30,6", "℘ Kap. 20,28; 1Sam 17,46; 2Sam 7,26; 2Kö 19,19", "℘ Kap. 22,28; 4Mo 16,28; 2Kö 5,8"] },
      { number: 37, text: "Antworte mir, HERR, antworte mir, damit dieses Volk erkennt, dass du, HERR, der <wahre> Gott bist* und dass du selbst ihr Herz wieder zurückgewandt hast*!", footnotes: ["℘ Kap. 20,28; 1Sam 17,46; 2Sam 7,26; 2Kö 19,19", "℘ Ps 109,27; Lk 1,16.17"] },
      { number: 38, text: "Da fiel Feuer vom HERRN herab* und verzehrte das Brandopfer und das Holz und die Steine und die Erde*; und das Wasser, das im Graben war, leckte es auf.", footnotes: ["℘ Offb 13,13", "℘ 3Mo 9,24; 2Chr 7,1"] },
      { number: 39, text: "Als das ganze Volk das sah, da fielen sie auf ihr Angesicht und sagten: Der HERR, er ist Gott! Der HERR, er ist Gott!*", footnotes: ["℘ V. 24; 2Mo 20,2.3; 2Chr 33,13; Ps 50,7; Hes 20,5.7"] },
      { number: 40, text: "Und Elia sagte zu ihnen: Packt die Propheten des Baal, keiner von ihnen soll entkommen! Und sie packten sie. Und Elia führte sie hinab an den Bach Kischon* und schlachtete sie dort*.", footnotes: ["℘ Ri 4,7.13", "℘ Kap. 19,1.17; 5Mo 13,6.10; 2Kö 10,25; 2Chr 23,15"] },
      { number: 41, text: "Und Elia sagte zu Ahab: Geh hinauf, iss und trink! Denn da ist ein Geräusch vom Rauschen des Regens." },
      { number: 42, text: "Da ging Ahab hinauf, um zu essen und zu trinken. Elia aber stieg auf den Gipfel des Karmel*. Und er beugte sich zur Erde und legte sein Gesicht zwischen seine Knie*.", footnotes: ["℘ Jer 46,18", "℘ 1Sam 12,18; Hi 37,11-13; Jak 5,18"] },
      { number: 43, text: "Und er sagte zu seinem Diener: Geh doch hinauf, halte Ausschau auf das Meer hin! Und er ging hinauf und hielt Ausschau und sagte: Es ist nichts da. Und er sagte: Geh wieder hin! So siebenmal*.", footnotes: ["℘ Jos 6,4; 2Kö 4,35"] },
      { number: 44, text: "Und es geschah beim siebten Mal, da sagte er: Siehe, eine Wolke, <so> klein wie die Hand eines Mannes, steigt aus dem Meer herauf. Da sagte Elia*: Geh hinauf, sag zu Ahab: Spanne an und fahre hinab, damit der Regen dich nicht aufhält!", footnotes: ["w. er"] },
      { number: 45, text: "Und es geschah unterdessen, da wurde der Himmel schwarz von Wolken und Wind, und es kam ein starker Regen. Und Ahab bestieg <den Wagen> und fuhr nach Jesreel*.", footnotes: ["℘ Kap. 21,1.23; Jos 17,16"] },
      { number: 46, text: "Und die Hand des HERRN kam über Elia*; und er gürtete seine Hüften* und lief vor Ahab her bis nach Jesreel hin*.", footnotes: ["℘ 2Kö 3,15; Hes 1,3", "℘ 2Kö 1,8", "w. bis man nach Jesreel kommt"] },
    ]},
    { number: 19, verses: [
      { number: 1, text: "Und Ahab berichtete der Isebel alles, was Elia getan hatte, und den ganzen <Hergang>, wie er alle Propheten mit dem Schwert umgebracht hatte*.", heading: "Elias Flucht vor Isebel und Begegnung mit Gott am Horeb", footnotes: ["℘ Kap. 18,40"] },
      { number: 2, text: "Da sandte Isebel einen Boten zu Elia und ließ <ihm> sagen: So sollen <mir> die Götter tun*, und so sollen sie hinzufügen*!* Ja, morgen um diese Zeit mache ich dein Leben dem Leben eines von ihnen gleich!*", footnotes: ["LXX: Wenn du Elia bist, so bin ich Isebel. So sollen mir die Götter tun", "eine hebr. Schwurformel", "℘ Kap. 2,23", "℘ 2Kö 6,31; Apg 23,12"] },
      { number: 3, text: "Da fürchtete er sich*; und er machte sich auf und lief um sein Leben* und kam nach Beerscheba*, das zu Juda gehört; und er ließ seinen Diener dort zurück.", footnotes: ["so mit den meisten hebr. Handschr., LXX und Vulg.; Mas. T.: Und er sah es", "℘ 1Sam 27,1", "℘ 1Mo 21,31"] },
      { number: 4, text: "Er selbst aber ging in die Wüste eine Tagereise weit und kam und ließ sich unter einem einzelnen Ginsterstrauch nieder. Da wünschte er sich, sterben zu können*, und sagte: Es ist genug. Nun, HERR, nimm mein Leben hin! Denn ich bin nicht besser als meine Väter.", footnotes: ["w. Da wünschte er seiner Seele zu sterben\n℘ 4Mo 11,15; Hi 6,8.9; Jer 20,18; Jon 4,3.8"] },
      { number: 5, text: "Dann legte er sich nieder und schlief unter dem einen Ginsterstrauch ein. Und siehe da, ein Engel rührte ihn an* und sprach zu ihm: Steh auf*, iss!", footnotes: ["℘ Hebr 1,14", "℘ Lk 22,43; Apg 12,7"] },
      { number: 6, text: "Und als er aufblickte, siehe, da <lagen> neben seinem Kopf ein Brotfladen, auf heißen Steinen <gebacken>, und ein Krug Wasser. Und er aß und trank* und legte sich wieder hin.", footnotes: ["℘ Kap. 17,6"] },
      { number: 7, text: "Und der Engel des HERRN kehrte zurück, <kam> zum zweiten Mal und rührte ihn an und sprach: Steh auf, iss! Denn der Weg ist zu weit für dich." },
      { number: 8, text: "Da stand er auf und aß und trank*, und er ging in der Kraft dieser Speise vierzig Tage und vierzig Nächte* bis an den Berg Gottes, den Horeb*.", footnotes: ["℘ Kap. 17,6", "℘ 2Mo 24,18; Mt 4,2", "℘ 2Mo 3,1"] },
      { number: 9, text: "Dort ging er in die Höhle und übernachtete da. Und siehe, das Wort des HERRN <geschah> zu ihm, und er sprach zu ihm: Was tust du hier*, Elia?", footnotes: ["℘ 1Mo 16,8"] },
      { number: 10, text: "Und er sagte: Ich habe sehr geeifert für den HERRN*, den Gott der Heerscharen. Deinen Bund haben die Söhne Israel verlassen*, haben deine Altäre niedergerissen* und deine Propheten mit dem Schwert umgebracht!* Und ich allein bin übrig geblieben*, ich allein, und <nun> trachten sie danach, <auch> mir das Leben zu nehmen*.", footnotes: ["℘ 4Mo 25,13; 2Kö 10,16; Ps 119,139", "℘ Ps 78,37; 119,26", "℘ Kap. 18,30", "℘ Mk 12,4.5; Hebr 11,37", "℘ Kap. 18,22; Jes 49,4; Jer 2,30", "℘ Neh 9,26; Mk 9,13; Joh 7,1; Röm 11,2.3"] },
      { number: 11, text: "Da sprach er: Geh hinaus und stell dich auf den Berg vor den HERRN! Und siehe, der HERR ging vorüber*. Da <kam> ein Wind, groß und stark*, der die Berge zerriss und die Felsen zerschmetterte vor dem HERRN her*; der HERR <aber> war nicht in dem Wind. Und nach dem Wind ein Erdbeben; der HERR <aber> war nicht in dem Erdbeben*.", footnotes: ["o. Und der HERR wird vorübergehen. — Dieser Satz gehört dann noch zur Rede des Engels.", "℘ Hes 1,4", "℘ Nah 1,3.6", "℘ Ps 68,9"] },
      { number: 12, text: "Und nach dem Erdbeben ein Feuer*, der HERR <aber> war nicht in dem Feuer. Und nach dem Feuer der Ton eines leisen Wehens*.", footnotes: ["℘ 5Mo 4,11.12", "℘ Sach 4,6"] },
      { number: 13, text: "Und es geschah, als Elia das hörte, verhüllte er sein Gesicht* mit seinem Mantel, ging hinaus und stellte sich in den Eingang der Höhle. Und siehe, eine Stimme geschah zu ihm: Was tust du hier, Elia?", footnotes: ["℘ 2Mo 3,6"] },
      { number: 14, text: "Und er sagte: Ich habe sehr geeifert für den HERRN, den Gott der Heerscharen. Deinen Bund haben die Söhne Israel ja verlassen, haben deine Altäre niedergerissen und deine Propheten mit dem Schwert umgebracht. Und ich bin übrig geblieben, ich allein, und <nun> trachten sie danach, <auch> mir das Leben zu nehmen." },
      { number: 15, text: "Da sprach der HERR zu ihm: Geh, kehre auf deinem Weg durch die Wüste* zurück <und geh> nach Damaskus! Und wenn du <dort> angekommen bist, dann salbe Hasaël zum König über Aram*!", footnotes: ["w. in die Wüste; d. h. auf deinem Weg, den du in die Wüste hineingegangen bist", "℘ 2Kö 8,15"] },
      { number: 16, text: "Und Jehu, den Sohn des Nimschi, sollst du zum König über Israel salben*; und Elisa*, den Sohn Schafats, von Abel-Mehola*, sollst du zum Propheten an deiner Stelle salben!", footnotes: ["℘ Kap. 1,34; 2Kö 9,2.3", "℘ 2Kö 2,1", "℘ Kap. 4,12"] },
      { number: 17, text: "Und es soll geschehen: Wer dem Schwert Hasaëls entkommt, den wird Jehu töten; und wer dem Schwert Jehus entkommt, den wird Elisa töten*.", footnotes: ["℘ 2Kö 9,24"] },
      { number: 18, text: "Aber ich habe 7 000 in Israel übrig gelassen*, alle die Knie, die sich nicht vor dem Baal gebeugt haben*, und jeden Mund, der ihn nicht geküsst hat*.", footnotes: ["Andere verstehen das Perfekt als prophetisches Perfekt und üs.: ich werde 7 000 in Israel übrig lassen", "℘ Röm 11,4", "℘ Hi 31,27; Hos 13,2"] },
      { number: 19, text: "Und er ging von dort <weg> und fand Elisa, den Sohn Schafats, der gerade mit zwölf Gespannen vor sich her pflügte*. Er selbst aber war bei dem zwölften. Und Elia ging zu ihm hin und warf seinen Mantel über ihn*.", heading: "Berufung Elisas", footnotes: ["℘ 2Mo 3,1; Ri 6,11; Am 7,14.15", "℘ 2Kö 2,8.13"] },
      { number: 20, text: "Da verließ er die Rinder und lief hinter Elia her und sagte: Lass mich doch meinen Vater und meine Mutter küssen! Dann will ich dir nachfolgen*. Er aber sagte zu ihm: Geh, kehre um! Denn was habe ich dir getan?", footnotes: ["℘ 1Mo 31,28; Lk 9,59-62"] },
      { number: 21, text: "Da kehrte er sich von ihm ab, nahm das Gespann Rinder und schlachtete sie, und mit dem Geschirr der Rinder briet er* ihr Fleisch und gab es den Leuten, und sie aßen. Dann machte er sich auf und folgte Elia nach* und diente ihm*.", footnotes: ["℘ 2Sam 24,22", "℘ Mt 4,22; 9,9", "℘ 2Kö 3,11; Phil 2,22"] },
    ]},
    { number: 20, verses: [
      { number: 1, text: "Und Ben-Hadad*, der König von Aram, versammelte seine ganze Heeresmacht: 32 Könige waren mit ihm und Pferd und Wagen. Und er zog herauf und belagerte Samaria* und kämpfte gegen es.", heading: "Ahabs Siege über Aram — Bund mit dem König von Aram", footnotes: ["℘ 2Kö 6,8; 8,7", "℘ 2Kö 6,24"] },
      { number: 2, text: "Und er sandte Boten zu Ahab, dem König von Israel, in die Stadt" },
      { number: 3, text: "und ließ ihm sagen: So spricht Ben-Hadad: Dein Silber und dein Gold gehören mir, und deine Frauen und deine edlen Söhne gehören mir." },
      { number: 4, text: "Da antwortete der König von Israel und sagte: Nach deinem Wort, mein Herr <und> König: Dein bin ich mit allem, was mir gehört*.", footnotes: ["℘ 1Sam 11,10; 2Kö 18,14"] },
      { number: 5, text: "Und die Boten kamen zurück und sagten: So spricht Ben-Hadad: Jawohl, ich habe zu dir gesandt und gesagt: Dein Silber und dein Gold und deine Frauen und deine Söhne sollst du mir geben." },
      { number: 6, text: "Fürwahr, wenn ich morgen um diese Zeit meine Knechte zu dir sende, dann werden sie dein Haus und die Häuser deiner Knechte gründlich durchsuchen. Und es wird geschehen, alles in deinen Augen Begehrenswerte* werden sie in ihre Gewalt bringen und mitnehmen.", footnotes: ["LXX, Vulg. und die syr. Üs.: alles in ihren Augen Begehrenswerte"] },
      { number: 7, text: "Da berief der König von Israel alle Ältesten des Landes und sagte: Erkennt doch und seht, dass dieser Böses sucht!* Denn er hat zu mir gesandt wegen meiner Frauen und meiner Söhne und wegen meines Silbers und meines Goldes, und ich habe ihm nichts verweigert.", footnotes: ["℘ 2Kö 5,7"] },
      { number: 8, text: "Da sagten alle Ältesten und alles Volk zu ihm: Höre nicht <auf ihn> und willige nicht ein!" },
      { number: 9, text: "So sagte er <denn> zu den Boten Ben-Hadads: Sagt meinem Herrn, dem König: Alles, weswegen du zuerst zu deinem Knecht gesandt hast, will ich tun; aber diese Sache kann ich nicht tun. Und die Boten gingen hin und brachten ihm Antwort." },
      { number: 10, text: "Da sandte Ben-Hadad zu ihm und ließ <ihm> sagen: So sollen mir die Götter tun und so sollen sie hinzufügen*, wenn der Schutt* von Samaria ausreichen sollte für die hohlen Hände all des <Kriegs>volkes, das in meinem Gefolge ist*!", footnotes: ["eine hebr. Schwurformel\n℘ Kap. 2,23", "w. der Staub", "℘ 2Kö 18,24"] },
      { number: 11, text: "Der König von Israel aber antwortete und sprach: Sagt <ihm>: Wer <das Schwert> umgürtet, rühme sich nicht wie einer, der <es wieder> ablegt*!", footnotes: ["℘ Spr 27,1"] },
      { number: 12, text: "Und es geschah, als er dieses Wort hörte — er zechte gerade im Zeltlager*, er und die Könige —, da sagte er zu seinen Knechten: Zum Angriff! Und sie stellten sich zum Angriff auf.*", footnotes: ["w. trank gerade in den Hütten\n℘ Spr 31,4", "w. Richtet <die Belagerungsmaschinen> auf! Und sie richteten <sie> auf."] },
      { number: 13, text: "Und siehe, ein Prophet trat zu Ahab, dem König von Israel, und sagte: So spricht der HERR: Hast du diese ganze gewaltige Menge gesehen? Siehe, ich gebe sie heute in deine Hand*, und du sollst erkennen, dass ich der HERR bin*.", footnotes: ["℘ Jos 10,8; 2Kö 3,18; 2Chr 20,15", "℘ V. 28; Kap. 18,39"] },
      { number: 14, text: "Da sagte Ahab: Durch wen? Und er sagte: So spricht der HERR: Durch die Leute der Provinzstatthalter*. Und er sagte: Wer soll den Kampf eröffnen? Er sagte: Du.", footnotes: ["w. die Knaben der Obersten der Provinzen. — Mit dem Wort »Knaben« sind Offiziere gemeint."] },
      { number: 15, text: "Da musterte er die Leute der Provinzstatthalter*; es waren 232. Und nach ihnen musterte er das ganze Volk, alle Söhne Israel, 7 000 <Mann>.*", footnotes: ["w. die Knaben der Obersten der Provinzen. — Mit dem Wort »Knaben« sind Offiziere gemeint.", "℘ Ps 33,16"] },
      { number: 16, text: "Und sie zogen aus am Mittag. Ben-Hadad aber trank und berauschte sich im Zeltlager*, er und die Könige, die 32 Könige, die ihm halfen.", footnotes: ["w. in den Hütten\n℘ Kap. 16,9; Jes 5,22"] },
      { number: 17, text: "Und die Leute der Provinzstatthalter* zogen zuerst aus. Und Ben-Hadad sandte <Leute aus>, und man berichtete ihm: Männer aus Samaria sind ausgezogen.", footnotes: ["s. Anm. zu V. 14"] },
      { number: 18, text: "Da sagte er: Wenn sie zum Frieden ausgezogen sind, greift sie lebendig, und wenn sie zum Kampf ausgezogen sind, greift sie <auch> lebendig!" },
      { number: 19, text: "Als jene aber aus der Stadt herausgezogen waren — die Leute der Provinzstatthalter* und das Heer, das ihnen folgte —,", footnotes: ["s. Anm. zu V. 14"] },
      { number: 20, text: "da schlugen sie jeder seinen Gegner*, so dass die Aramäer flohen; und Israel jagte ihnen nach*. Ben-Hadad, der König von Aram, entkam aber auf einem Pferd mit <einigen> Gespannen.", footnotes: ["w. seinen Mann", "℘ Ri 7,21.23; 2Kö 7,6.7"] },
      { number: 21, text: "Da zog der König von Israel aus und schlug die Pferde und die Kriegswagen, und er richtete unter den Aramäern eine große Niederlage an*.", footnotes: ["℘ Jos 10,20; Ri 11,33; 1Sam 19,8"] },
      { number: 22, text: "Da trat der Prophet zum König von Israel und sagte zu ihm: Wohlan, zeige dich mutig* und erkenne und sieh zu, was du <jetzt> tun musst! Denn bei der Wiederkehr des Jahres* wird der König von Aram <erneut> gegen dich heraufziehen*.", footnotes: ["o. sammle Kräfte o. Verstärkung", "d. h. im folgenden Frühjahr", "℘ 2Sam 11,1"] },
      { number: 23, text: "Und die Knechte des Königs von Aram sagten zu ihm: Ihre Götter sind Berggötter, darum waren sie uns überlegen. Lasst uns jedoch in der Ebene mit ihnen kämpfen, <dann wird es sich zeigen,> ob wir ihnen nicht überlegen sein werden!" },
      { number: 24, text: "Diese <eine> Sache aber musst du tun: Entferne die Könige, jeden von seiner Stellung, und setze Statthalter an ihre Stelle!" },
      { number: 25, text: "Und du, stelle dir ein Heer auf* wie das Heer, das dir verloren ging*, und Pferde wie die <verlorenen> Pferde und Kriegswagen wie die <verlorenen> Kriegswagen! Dann wollen wir in der Ebene mit ihnen kämpfen <und sehen>, ob wir ihnen nicht überlegen sein werden. Und er hörte auf ihre Stimme und machte es so.", footnotes: ["w. zähle dir ein Heer", "w. das dir gefallen ist"] },
      { number: 26, text: "Und es geschah bei der Wiederkehr des Jahres*, da musterte Ben-Hadad die Aramäer und zog hinauf* nach Afek* zum Kampf mit Israel.", footnotes: ["d. h. im folgenden Frühjahr", "℘ 2Sam 11,1", "d. i. in der Ebene Jesreel\n℘ 1Sam 4,1; 2Kö 13,17"] },
      { number: 27, text: "Und die Söhne Israel wurden gemustert und <mit Vorrat> versorgt und zogen ihnen entgegen. Und die Söhne Israel lagerten sich ihnen gegenüber wie zwei kleine Herden Ziegen*. Die Aramäer aber füllten das Land*.", footnotes: ["Die Bedeutung »kleine Herde« ist nicht gesichert. Andere üs.: wie zwei zu früh geworfene Zicklein", "℘ Ri 7,12"] },
      { number: 28, text: "Da trat der Mann Gottes herzu und sprach zum König von Israel und sagte: So spricht der HERR: Weil die Aramäer gesagt haben: Der HERR ist ein Gott der Berge, aber ein Gott der Täler ist er nicht*! — darum will ich diese ganze gewaltige Menge in deine Hand geben; und ihr werdet erkennen, dass ich der HERR bin*.", footnotes: ["℘ 2Chr 32,19", "℘ V. 13; Kap. 18,36.37; 2Mo 6,7; 5Mo 32,27; Ps 46,11"] },
      { number: 29, text: "Und sie lagerten einander gegenüber sieben Tage lang. Und es geschah am siebten Tag, da kam es zum Kampf*, und die Söhne Israel schlugen die Aramäer, 100 000 Mann zu Fuß, an einem Tag*.", footnotes: ["w. da rückte der Kampf heran", "℘ 2Kö 13,17-19.25"] },
      { number: 30, text: "Und die übrigen flohen nach Afek in die Stadt. Da fiel die Mauer auf die 27 000 Mann, die übrig geblieben waren.Und Ben-Hadad floh und kam in die Stadt <und verkroch sich> von Kammer zu Kammer*.", heading: "Ahabs Bund mit dem König der Aramäer — Gottes Gerichtsandrohung", footnotes: ["℘ Kap. 22,25"] },
      { number: 31, text: "Da sagten seine Diener zu ihm: Sieh doch, wir haben gehört, dass die Könige des Hauses Israel gnädige Könige sind. Lass uns doch Sacktuch um unsere Hüften legen* und Stricke um unsere Köpfe und zum König von Israel hinausgehen! Vielleicht lässt er dich* am Leben*.", footnotes: ["℘ 1Mo 37,34", "w. deine Seele", "℘ Hi 2,4"] },
      { number: 32, text: "So gürteten sie Sacktuch um ihre Hüften und <legten> Stricke um ihre Köpfe und kamen zum König von Israel und sagten: Dein Knecht Ben-Hadad lässt <dir> sagen: Lass mich doch* am Leben! Und er sagte: Lebt er noch? Er ist mein Bruder.", footnotes: ["w. Lass doch meine Seele"] },
      { number: 33, text: "Und die Männer nahmen es als ein gutes Vorzeichen und eilten, sich es von ihm bestätigen zu lassen*, und sagten: <Ja,> Ben-Hadad ist dein Bruder. Und er sagte: Geht, holt ihn! Da ging Ben-Hadad zu ihm hinaus, und der ließ ihn <zu sich> auf den Wagen steigen*.", footnotes: ["w. beeilten sich, es von ihm als unwiderruflich festzuhalten", "℘ 2Kö 10,15"] },
      { number: 34, text: "Und Ben-Hadad* sagte: Die Städte, die mein Vater deinem Vater genommen hat*, will ich <dir> zurückgeben, und du kannst dir Straßen in Damaskus anlegen, wie sie mein Vater in Samaria angelegt hat. — Und ich<, sagte der König von Israel,> will dich mit diesem Bund* ziehen lassen. Und er schloss einen Bund* mit ihm und ließ ihn ziehen*.", footnotes: ["w. Und er", "℘ Kap. 15,20", "o. Vertrag", "o. Vertrag", "℘ 5Mo 7,2; 1Sam 15,8.9"] },
      { number: 35, text: "Und ein Mann von den Prophetenjüngern* sagte zu seinem Gefährten auf das Wort des HERRN hin: Schlag mich doch! Aber der Mann weigerte sich, ihn zu schlagen.", footnotes: ["w. von den Söhnen der Propheten\n℘ 2Kö 2,3-7.15; Am 7,14"] },
      { number: 36, text: "Da sagte er zu ihm: Dafür, dass du nicht auf die Stimme des HERRN gehört hast — siehe, sobald du von mir weggehst, wird dich ein Löwe schlagen*. Und als er von ihm wegging, da fand ihn ein Löwe und schlug* ihn*.", footnotes: ["d. h. töten", "d. h. tötete", "℘ Kap. 13,21-24"] },
      { number: 37, text: "Und er fand einen anderen Mann und sagte: Schlag mich doch! Und der Mann schlug ihn, schlug und verwundete ihn." },
      { number: 38, text: "Da ging der Prophet hin und stellte sich an den Weg, <um> dem König <zu begegnen>. Und er machte sich unkenntlich durch eine Binde über seinen Augen." },
      { number: 39, text: "Und es geschah, als der König vorüberging, da schrie er dem König zu und sagte: Dein Knecht war ausgezogen mitten in den Kampf, und siehe, da wandte sich ein Mann herzu und brachte einen <anderen> Mann zu mir und sagte: Bewache diesen Mann! Sollte er etwa vermisst werden, dann soll dein Leben für sein Leben einstehen*, oder du sollst ein Talent Silber darwiegen.", footnotes: ["℘ 2Kö 10,24"] },
      { number: 40, text: "Und es geschah, während dein Knecht da und dort zu tun hatte, da war er nicht <mehr> da. Und der König von Israel sagte zu ihm: So ist dein Urteil <gesprochen>, du selbst hast entschieden*.", footnotes: ["℘ 2Sam 12,1-7; Hi 15,6; Lk 19,22"] },
      { number: 41, text: "Da entfernte er schnell die Binde von seinen Augen, und der König von Israel erkannte ihn, dass er <einer> von den Propheten war." },
      { number: 42, text: "Und er sagte zu ihm: So spricht der HERR: Weil du den Mann, auf dem mein Bann lag*, aus der Hand gelassen hast, soll dein Leben für sein Leben einstehen* und dein Volk für sein Volk!", footnotes: ["w. den Mann meines Bannes; d. h. der dem Tod geweiht war", "℘ Kap. 22,31-37; 3Mo 27,29"] },
      { number: 43, text: "Da ging der König von Israel <weg> in sein Haus, missmutig und wütend*, und kam nach Samaria.", footnotes: ["℘ Kap. 21,4"] },
    ]},
    { number: 21, verses: [
      { number: 1, text: "Und es geschah nach diesen Ereignissen: Nabot, der Jesreeliter*, hatte einen Weinberg, der in Jesreel war, <und zwar gleich> neben dem Palast Ahabs, des Königs von Samaria.", heading: "Ahabs Gewalttat an Nabot — Elias Strafrede und Ahabs Buße", footnotes: ["℘ Kap. 18,45.46"] },
      { number: 2, text: "Und Ahab redete zu Nabot und sagte: Gib mir deinen Weinberg! Er soll mein Gemüsegarten werden, denn er ist nahe bei meinem Haus. Ich gebe dir dafür einen besseren Weinberg als den <hier>. <Oder> wenn es besser ist in deinen Augen, gebe ich dir Geld als Kaufpreis für ihn." },
      { number: 3, text: "Aber Nabot sagte zu Ahab: Das lasse der HERR fern von mir sein*, dass ich dir das Erbe meiner Väter gebe*!", footnotes: ["w. <Das sei> mir <etwas> Entweihtes vor dem HERRN", "℘ 4Mo 36,7; Hes 46,18"] },
      { number: 4, text: "Da ging Ahab in sein Haus, missmutig und wütend* über das Wort, das der Jesreeliter Nabot zu ihm geredet hatte, dass er gesagt hatte: Ich gebe dir das Erbe meiner Väter nicht. Und er legte sich auf sein Bett und wandte sein Gesicht ab und aß nichts*.", footnotes: ["℘ Kap. 20,43; Jon 4,8.9", "w. und aß kein Brot (V. 4) bzw. und isst du kein Brot? (V. 5) bzw. iss Brot (V. 7)"] },
      { number: 5, text: "Da kam seine Frau Isebel zu ihm hinein und sagte zu ihm: Warum denn ist dein Geist missmutig, und <warum> isst du nichts?*", footnotes: ["w. und aß kein Brot (V. 4) bzw. und isst du kein Brot? (V. 5) bzw. iss Brot (V. 7)\n℘ 2Sam 13,4"] },
      { number: 6, text: "Er sagte zu ihr: Weil ich zu dem Jesreeliter Nabot geredet und ihm gesagt habe: Gib mir deinen Weinberg für Geld, oder wenn es dir gefällt, will ich dir stattdessen einen <anderen> Weinberg geben! Er aber sagte: Ich gebe dir meinen Weinberg nicht." },
      { number: 7, text: "Da sagte seine Frau Isebel zu ihm: Du, du übst <doch> jetzt die Königsherrschaft über Israel aus. Steh auf, iss* und lass dein Herz fröhlich sein! Ich werde dir den Weinberg des Jesreeliters Nabot geben*.", footnotes: ["w. und aß kein Brot (V. 4) bzw. und isst du kein Brot? (V. 5) bzw. iss Brot (V. 7)", "℘ Mi 2,1.2"] },
      { number: 8, text: "Dann schrieb sie Briefe im Namen Ahabs und siegelte sie mit seinem Siegel und sandte die Briefe an die Ältesten und an die Vornehmen, die mit Nabot <zusammen> in seiner Stadt wohnten*.", footnotes: ["w. die in seiner Stadt waren, die mit Nabot wohnten\n℘ Rt 4,2; 2Kö 10,1"] },
      { number: 9, text: "Und sie schrieb in den Briefen Folgendes: Ruft ein Fasten aus* und lasst Nabot obenan im Volk sitzen!", footnotes: ["℘ Jes 58,4"] },
      { number: 10, text: "Und setzt ihm gegenüber zwei Männer, Söhne der Bosheit, dass sie gegen ihn zeugen*, indem sie sagen: Du hast Gott und den König gelästert*! Dann führt ihn hinaus und steinigt ihn, dass er stirbt!*", footnotes: ["℘ Spr 6,19", "w. gesegnet; hier beschönigend gebraucht\n℘ Apg 6,11", "℘ 3Mo 24,14-16; Jes 59,14"] },
      { number: 11, text: "Da taten die Männer seiner Stadt, die Ältesten und die Vornehmen, die in seiner Stadt wohnten, wie Isebel zu ihnen gesandt hatte, so, wie in den Briefen geschrieben stand, die sie ihnen gesandt hatte." },
      { number: 12, text: "Sie riefen ein Fasten aus und ließen Nabot obenan im Volk sitzen." },
      { number: 13, text: "Dann kamen die beiden Männer, die Söhne der Bosheit, und setzten sich ihm gegenüber. Und die Männer der Bosheit zeugten gegen ihn*, gegen Nabot vor dem Volk, indem sie sagten: Nabot hat Gott und den König gelästert*! Dann führte man ihn zur Stadt hinaus und steinigte ihn, und er starb*.", footnotes: ["℘ Spr 19,28", "w. gesegnet; hier beschönigend gebraucht", "℘ 4Mo 15,36; Hi 31,39; Hebr 11,37"] },
      { number: 14, text: "Und sie sandten zu Isebel und ließen <ihr> sagen: Nabot ist gesteinigt worden und ist tot." },
      { number: 15, text: "Und es geschah, als Isebel hörte, dass Nabot gesteinigt worden und tot war, sagte Isebel zu Ahab: Mache dich auf, nimm in Besitz den Weinberg des Jesreeliters Nabot, der sich geweigert hat, ihn dir für Geld zu geben! Denn Nabot lebt nicht mehr, er ist tot." },
      { number: 16, text: "Und es geschah, als Ahab hörte, dass Nabot tot war, da machte sich Ahab auf, um in den Weinberg des Jesreeliters Nabot hinabzugehen <und> ihn in Besitz zu nehmen*.", footnotes: ["℘ 2Sam 11,26.27; 2Kö 9,21"] },
      { number: 17, text: "Da geschah das Wort des HERRN zu Elia, dem Tischbiter:" },
      { number: 18, text: "Mache dich auf, geh hinab Ahab, dem König von Israel, entgegen*, der in Samaria <wohnt>! Siehe, er ist im Weinberg Nabots, wohin er hinabgegangen ist, um ihn in Besitz zu nehmen.", footnotes: ["℘ 2Sam 12,1"] },
      { number: 19, text: "Und rede zu ihm und sage: So spricht der HERR: Hast du gemordet* und auch <fremdes Gut> in Besitz genommen*? Und rede zu ihm: So spricht der HERR: An der Stelle, wo die Hunde das Blut Nabots geleckt haben, sollen die Hunde dein Blut, ja deines, lecken*.", footnotes: ["℘ 2Kö 6,32", "℘ Ps 9,13", "℘ Kap. 22,38; Ri 1,7; 2Kö 9,25.26; Ps 7,16.17"] },
      { number: 20, text: "Und Ahab sagte zu Elia: Hast du mich gefunden, mein Feind*? Und er sagte: Ich habe <dich> gefunden, weil du dich verkauft hast, um zu tun, was böse ist in den Augen des HERRN*.", footnotes: ["℘ Kap. 22,8; Am 5,10", "℘ 2Sam 11,27; 2Kö 17,17"] },
      { number: 21, text: "Siehe, ich bringe Unheil über dich* und fege aus hinter dir her. Ich werde von Ahab ausrotten, was männlich ist*, den Unmündigen und den Mündigen* in Israel*.", footnotes: ["℘ Jes 3,11", "w. was an die Wand pisst", "s. Anm. zu Kap. 14,10", "℘ Kap. 14,10; 2Kö 9,8; 10,17; 21,13"] },
      { number: 22, text: "Und ich mache dein Haus dem Haus Jerobeams, des Sohnes Nebats, gleich und dem Haus Baschas, des Sohnes Ahijas, wegen des Zornes, zu dem du mich gereizt hast, und <weil> du Israel zur Sünde verführt hast*.", footnotes: ["℘ Kap. 14,16; 15,29.30; 2Kö 10,10"] },
      { number: 23, text: "Und auch über Isebel hat der HERR geredet und gesprochen: Die Hunde sollen Isebel fressen an der Vormauer* von Jesreel*.", footnotes: ["9 hebr. Handschr., LXX, Vulg. und die syr. Üs.: auf dem Feld", "℘ Kap. 18,45; 2Kö 9,10.36"] },
      { number: 24, text: "Wer von Ahab in der Stadt stirbt, den werden die Hunde fressen, und wer auf <freiem> Feld stirbt, den werden die Vögel des Himmels fressen*.", footnotes: ["℘ Kap. 14,11"] },
      { number: 25, text: "Es hat in der Tat keinen wie Ahab gegeben*, der sich <so> verkauft hätte, um zu tun, was in den Augen des HERRN böse ist. Ihn hatte seine Frau Isebel verführt*.", footnotes: ["℘ Kap. 16,25.30.33", "℘ Kap. 16,30.31; 22,53.54; 2Mo 34,16; 2Kö 9,22; Neh 13,26"] },
      { number: 26, text: "Und er handelte ganz abscheulich, indem er den Götzen* nachlief, ganz wie es die Amoriter getan hatten*, die der HERR vor den Söhnen Israel vertrieben hatte.*", footnotes: ["w. Mistkugeln, o. Klötzen; ein verächtlicher Ausdruck", "℘ 3Mo 18,30; 2Kö 21,11", "℘ Jos 23,9"] },
      { number: 27, text: "Und es geschah, als Ahab diese Worte hörte, da zerriss er seine Kleider* und legte Sacktuch um seinen Leib* und fastete; und er lag im Sacktuch und ging still* einher.", footnotes: ["℘ Jer 36,24", "℘ 2Mo 33,4; 2Kö 6,30; 19,1; 1Chr 21,16; Jon 3,6", "o. bedrückt"] },
      { number: 28, text: "Da geschah das Wort des HERRN zu Elia, dem Tischbiter:" },
      { number: 29, text: "Hast du gesehen, dass Ahab sich vor mir gedemütigt hat?* Weil er sich vor mir gedemütigt hat, will ich das Unheil nicht in seinen Tagen kommen lassen*; <erst> in den Tagen seines Sohnes werde ich das Unheil über sein Haus kommen lassen*.", footnotes: ["℘ 2Mo 10,3; 2Kö 22,19; Jes 66,2", "℘ Kap. 11,12; 2Chr 12,7; Jon 3,10", "℘ 2Kö 9,24-26; 10,1-11"] },
    ]},
    { number: 22, verses: [
      { number: 1, text: "*Und sie verhielten sich drei Jahre lang ruhig; es war kein Krieg zwischen Aram und Israel*.", heading: "Ahabs und Joschafats Kriegsabsichten — Weissagung des Micha", footnotes: ["℘ 2Chr 18,1-27", "℘ 2Kö 6,8"] },
      { number: 2, text: "Aber im dritten Jahr, da kam Joschafat, der König von Juda*, zum König von Israel herab.", footnotes: ["℘ V. 41"] },
      { number: 3, text: "Und der König von Israel sagte zu seinen Dienern: Habt ihr nicht erkannt, dass Ramot in Gilead* uns gehört? Und wir bleiben still*, anstatt es der Hand des Königs von Aram zu entreißen.", footnotes: ["℘ 5Mo 4,43; 2Kö 8,28", "℘ Ri 18,9"] },
      { number: 4, text: "Und er sagte zu Joschafat: Willst du mit mir nach Ramot in Gilead in den Kampf ziehen? Da sagte Joschafat zum König von Israel: Ich bin wie du, mein Volk ist wie dein Volk, meine Pferde sind wie deine Pferde.*", footnotes: ["℘ 2Kö 3,7"] },
      { number: 5, text: "Und Joschafat sagte zum König von Israel: Befrage doch heute* das Wort des HERRN!*", footnotes: ["o. zuerst", "℘ Ri 1,1; Jer 21,2"] },
      { number: 6, text: "Da versammelte der König von Israel die Propheten*, etwa vierhundert Mann, und er sagte zu ihnen: Soll ich gegen Ramot in Gilead in den Kampf ziehen, oder soll ich es lassen? Sie sagten: Zieh hinauf! Und der Herr wird es in die Hand des Königs geben*.", footnotes: ["℘ Kap. 18,20; 2Kö 10,19", "℘ Jer 5,31"] },
      { number: 7, text: "Aber Joschafat sagte: Ist hier kein Prophet des HERRN mehr, dass wir durch ihn <den HERRN> befragen?*", footnotes: ["℘ 2Kö 3,11; Jes 30,2"] },
      { number: 8, text: "Da sagte der König von Israel zu Joschafat: Einen Mann gibt es noch, durch den man den HERRN befragen könnte; aber ich hasse ihn*, denn er weissagt nichts Gutes über mich, sondern <nur> Böses*: <Es ist> Micha, der Sohn des Jimla. Joschafat aber sagte: Der König spreche nicht so!", footnotes: ["℘ Kap. 21,20; Spr 29,10", "℘ Joh 3,20; 2Tim 4,3"] },
      { number: 9, text: "Da rief der König von Israel einen Hofbeamten* und sagte: Hole schnell Micha, den Sohn des Jimla!", footnotes: ["w. einen Eunuchen"] },
      { number: 10, text: "Und der König von Israel und Joschafat, der König von Juda, saßen jeder auf seinem Thron, bekleidet mit königlichen Gewändern, auf einem freien Platz am Toreingang von Samaria. Und alle Propheten weissagten vor ihnen." },
      { number: 11, text: "Und Zedekia, der Sohn des Kenaana, machte sich eiserne Hörner* und sagte: So spricht der HERR: Mit denen wirst du die Aramäer niederstoßen, bis du sie vernichtet hast*.", footnotes: ["℘ Jer 27,2", "℘ 5Mo 33,17; Jer 23,16.31"] },
      { number: 12, text: "Ebenso weissagten alle Propheten, indem sie sagten: Zieh hinauf nach Ramot in Gilead und führe <Israel> zum Sieg! Der HERR wird es in die Hand des Königs geben*.", footnotes: ["℘ Hes 13,6-9"] },
      { number: 13, text: "Der Bote aber, der hingegangen war, Micha zu rufen, redete zu ihm und sagte: Sieh doch, die Worte der Propheten sind einstimmig* gut für den König. Lass doch dein Wort sein wie das Wort eines von ihnen und rede Gutes!*", footnotes: ["w. mit einem Mund", "℘ Jes 30,10"] },
      { number: 14, text: "Micha aber sagte: So wahr der HERR lebt — nur, was der HERR mir sagen wird, das werde ich reden!*", footnotes: ["℘ 4Mo 22,38; Jer 23,28"] },
      { number: 15, text: "Und als er zum König kam, sagte der König zu ihm: Micha, sollen wir nach Ramot in Gilead in den Kampf ziehen, oder sollen wir es lassen? Da sagte er zu ihm: Zieh hinauf und führe <Israel> zum Sieg! Denn der HERR wird es in die Hand des Königs geben*.", footnotes: ["℘ Hes 13,6-9"] },
      { number: 16, text: "Der König aber sagte zu ihm: Wievielmal muss ich dich beschwören, dass du im Namen des HERRN nichts zu mir redest als nur Wahrheit?*", footnotes: ["℘ 4Mo 22,38; Jer 23,28"] },
      { number: 17, text: "Da sagte er: Ich sah* ganz Israel auf den Bergen zerstreut* wie Schafe, die keinen Hirten haben*. Und der HERR sprach: Diese haben keinen Herrn, sie sollen in Frieden zurückkehren, jeder in sein Haus.", footnotes: ["℘ 4Mo 24,3.4", "℘ Nah 3,18", "℘ 4Mo 27,17; Hes 34,5; Mt 9,36"] },
      { number: 18, text: "Da sagte der König von Israel zu Joschafat: Habe ich dir nicht gesagt, er weissagt nichts Gutes über mich, sondern <nur> Böses?*", footnotes: ["℘ Joh 3,20; 2Tim 4,3"] },
      { number: 19, text: "Und Micha* sprach: Darum höre das Wort des HERRN!* Ich sah* den HERRN auf seinem Thron sitzen*, und das ganze Heer des Himmels stand um ihn, zu seiner Rechten und zu seiner Linken*.", footnotes: ["w. er", "℘ Ps 81,9", "℘ 4Mo 24,3.4", "℘ 2Mo 24,10; Jes 6,1; Offb 4,2", "℘ Hi 1,6; Dan 7,9.10; Offb 5,11"] },
      { number: 20, text: "Und der HERR sprach: Wer will Ahab betören*, dass er hinaufzieht und bei Ramot in Gilead fällt? Und der eine sagte dies, und der andere sagte das.", footnotes: ["℘ Jes 6,8"] },
      { number: 21, text: "Da trat der Geist hervor und stellte sich vor den HERRN und sagte: Ich will ihn betören. Und der HERR sprach zu ihm: Womit?" },
      { number: 22, text: "Da sagte er: Ich will ausgehen und will ein Lügengeist sein im Mund aller seiner Propheten.* Und er sprach: Du sollst ihn betören und wirst es auch können*. Geh aus und mache es so!*", footnotes: ["℘ Jes 19,14", "℘ Hi 12,16; Hes 14,9; 2Thes 2,10-12; Offb 16,14", "℘ Kap. 13,18; Hi 1,12; Hes 14,9"] },
      { number: 23, text: "Und nun, siehe, der HERR hat einen Lügengeist in den Mund all dieser deiner Propheten gegeben, denn der HERR hat Unheil über dich geredet*.", footnotes: ["℘ Ri 9,23; Jer 18,11"] },
      { number: 24, text: "Da trat Zedekia, der Sohn des Kenaana, heran und schlug Micha auf die Backe* und sprach: Auf welchem Weg ist <denn> der Geist des HERRN von mir gewichen, um mit dir zu reden?", footnotes: ["℘ Mt 26,67; Apg 23,2"] },
      { number: 25, text: "Micha sagte: Siehe, du wirst es an jenem Tag sehen, wenn du von Zimmer zu Zimmer flüchtest*, um dich zu verstecken.", footnotes: ["w. kommst\n℘ Kap. 20,30"] },
      { number: 26, text: "Da sagte der König von Israel: Nimm Micha und führe ihn zurück zu Amon, dem Obersten der Stadt, und zu Joasch, dem Sohn des Königs*,", footnotes: ["℘ Jer 36,26"] },
      { number: 27, text: "und sage: So spricht der König: Setzt diesen ins Gefängnis* und speist ihn mit Brot der Bedrängnis und mit Wasser der Bedrängnis*, bis ich in Frieden zurückkomme!", footnotes: ["℘ Kap. 13,4; Lk 3,20; Apg 12,4; Hebr 11,36", "Die Wendung »Brot der Bedrängnis« bzw. »Wasser der Bedrängnis« stammt aus der Belagerungssituation einer Stadt, in der Brot und Wasser rationiert werden mussten. Daher ist hier gemeint: Gebt ihm verkürzte Ration Brot und Wasser!"] },
      { number: 28, text: "Micha aber sagte: Wenn du je in Frieden zurückkehrst, <dann> hat der HERR nicht durch mich geredet!* Und er sprach: Hört es, ihr Völker alle!*", footnotes: ["℘ Kap. 18,36; 5Mo 18,22", "℘ Jer 28,7; Mi 1,2"] },
      { number: 29, text: "*Und der König von Israel und Joschafat, der König von Juda, zogen hinauf nach Ramot in Gilead.", heading: "Gemeinsamer Krieg Ahabs und Joschafats — Joschafats Rettung und Ahabs Tod", footnotes: ["℘ 2Chr 18,28-34"] },
      { number: 30, text: "Und der König von Israel sagte zu Joschafat: Ich will mich verkleiden und in den Kampf ziehen. Du aber lege deine <königlichen> Kleider an! So verkleidete sich der König von Israel und zog in den Kampf*.", footnotes: ["℘ 2Chr 35,22"] },
      { number: 31, text: "Der König von Aram hatte aber seinen 32 Wagenführern befohlen: Ihr sollt weder gegen einen Geringen noch gegen einen Großen kämpfen, sondern gegen den König von Israel allein*!", footnotes: ["℘ 2Sam 17,2"] },
      { number: 32, text: "Und es geschah, als die Wagenführer Joschafat sahen, da sagten sie <sich>: Das ist gewiss der König von Israel! Und sie lenkten <ihre Wagen> auf ihn zu, um ihn anzugreifen*. Da schrie Joschafat um Hilfe.", footnotes: ["w. um zu kämpfen"] },
      { number: 33, text: "Und es geschah, als die Wagenführer sahen, dass nicht er der König von Israel war, da wandten sie sich von ihm ab." },
      { number: 34, text: "Und ein Mann spannte den Bogen aufs Geratewohl* und traf den König von Israel zwischen die Tragbänder <des Panzers> und den Panzer. Da sagte er zu seinem Wagenlenker: Wende um* und bring mich aus der Schlacht* hinaus! Denn ich bin schwer verwundet*.", footnotes: ["w. in seiner Arglosigkeit\n℘ Kla 3,37", "w. Wende deine Hände", "so mit LXX und Vulg.; Mas. T.: aus dem Lager", "w. ich bin <durch eine Verwundung> entkräftet\n℘ 2Chr 35,23"] },
      { number: 35, text: "Und der Kampf wurde heftig an jenem Tag. Und der König hielt sich angesichts der Aramäer im Wagen <noch> aufrecht; und am Abend starb er, und das Blut der Wunde floss* in das Innere des Wagens*.", footnotes: ["w. ergoss sich", "℘ 2Kö 9,24"] },
      { number: 36, text: "Beim Untergang der Sonne erging der laute Ruf durchs Lager: Jeder Mann in seine Stadt und jeder Mann in sein Land!" },
      { number: 37, text: "So starb der König* und kam nach Samaria. Und man begrub* den König in Samaria.", footnotes: ["℘ Kap. 20,42", "LXX: jeder Mann in sein Land! 37 Denn der König ist tot. Und man kam nach Samaria und begrub"] },
      { number: 38, text: "Und als man den Wagen am Teich von Samaria<, wo die Huren sich wuschen,> abspülte, da leckten die Hunde sein Blut, und die Huren badeten <darin> nach dem Wort des HERRN, das er geredet hatte*.", footnotes: ["℘ Kap. 21,19; 2Kö 1,17"] },
      { number: 39, text: "Und die übrige Geschichte* Ahabs und alles, was er getan, und das Elfenbeinhaus*, das er gebaut, und alle Städte, die er gebaut hat, ist das nicht geschrieben im Buch der Geschichte* der Könige von Israel?*", footnotes: ["w. der Rest der Begebenheiten", "℘ Am 3,15", "w. im Buch der Begebenheiten der Tage", "℘ Kap. 14,19"] },
      { number: 40, text: "Und Ahab legte sich zu seinen Vätern*. Und sein Sohn Ahasja wurde an seiner Stelle König*.", footnotes: ["℘ Kap. 11,43", "℘ V. 52; 2Kö 1,2"] },
      { number: 41, text: "*Und Joschafat, der Sohn Asas, wurde König über Juda* im vierten Jahr Ahabs, des Königs von Israel.", heading: "Joschafat von Juda", footnotes: ["℘ 2Chr 20,31-21,1", "℘ V. 2; Kap. 15,24; Mt 1,8"] },
      { number: 42, text: "Joschafat war 35 Jahre alt, als er König wurde, und er regierte 25 Jahre in Jerusalem; und der Name seiner Mutter war Asuba, die Tochter des Schilhi." },
      { number: 43, text: "Und er ging den ganzen Weg seines Vaters Asa*; er wich nicht davon ab, indem er tat, was recht war in den Augen des HERRN*.", footnotes: ["℘ Spr 13,1", "℘ Kap. 15,11"] },
      { number: 44, text: "Nur die Höhen wichen nicht: Das Volk brachte auf den Höhen noch Schlachtopfer und Rauchopfer dar*.", footnotes: ["℘ Kap. 3,3; Jes 65,7"] },
      { number: 45, text: "Und Joschafat hatte Frieden mit dem König von Israel.*", footnotes: ["℘ 2Chr 18,1"] },
      { number: 46, text: "Und die übrige Geschichte* Joschafats und seine Machttaten, die er ausgeübt, und wie er Krieg geführt hat, ist das nicht geschrieben im Buch der Geschichte* der Könige von Juda?*", footnotes: ["w. der Rest der Begebenheiten", "w. im Buch der Begebenheiten der Tage", "℘ Kap. 14,29"] },
      { number: 47, text: "Auch rottete er* aus dem Land den Rest der Tempelhurer aus*, der in den Tagen seines Vaters Asa übrig geblieben war.", footnotes: ["o. fegte er", "℘ Kap. 15,12"] },
      { number: 48, text: "Und es war kein König in Edom; ein Vogt <regierte als> König*.", footnotes: ["℘ 1Mo 27,37; 2Sam 8,14; 2Kö 8,20"] },
      { number: 49, text: "Joschafat baute Tarsisschiffe*, die nach Ofir fahren sollten, um Gold <zu holen>*; aber man fuhr nicht, denn die Schiffe wurden bei Ezjon-Geber* zertrümmert*.", footnotes: ["℘ Kap. 10,22", "℘ Kap. 9,28", "℘ Kap. 9,26", "℘ Ps 48,8"] },
      { number: 50, text: "Damals sagte Ahasja, der Sohn Ahabs, zu Joschafat: Lass meine Knechte mit deinen Knechten auf den Schiffen fahren! Aber Joschafat wollte nicht." },
      { number: 51, text: "Und Joschafat legte sich zu seinen Vätern und wurde bei seinen Vätern begraben in der Stadt seines Vaters David*. Und sein Sohn Joram* wurde an seiner Stelle König*.", footnotes: ["℘ Kap. 2,10", "℘ 1Chr 3,11", "℘ 2Kö 8,16"] },
      { number: 52, text: "Ahasja, der Sohn Ahabs, wurde König über Israel* in Samaria, im siebzehnten Jahr Joschafats, des Königs von Juda; und er regierte zwei Jahre über Israel.", heading: "Ahasja von Israel", footnotes: ["℘ V. 40"] },
      { number: 53, text: "Und er tat, was böse war in den Augen des HERRN*, und ging auf dem Weg seines Vaters und auf dem Weg seiner Mutter* und auf dem Weg Jerobeams, des Sohnes Nebats, der Israel zur Sünde verführt hatte*.", footnotes: ["℘ 2Kö 8,18", "℘ Kap. 21,25", "℘ Kap. 14,16; 2Chr 20,35"] },
      { number: 54, text: "Und er diente dem Baal* und warf sich vor ihm nieder. Und er reizte den HERRN, den Gott Israels, nach allem, was sein Vater getan hatte*.", footnotes: ["℘ 2Kö 1,2.16; 17,16", "℘ Kap. 21,25"] },
    ]},
  ]
};
